# V63.2: heavy imports lazy — pandas/numpy/openpyxl dimuat saat pertama dipakai,
# sehingga cold-boot (mis. restart PythonAnywhere) jauh lebih cepat.
class _V67LazyModule:
    _loaded = {}
    def __init__(self, name):
        object.__setattr__(self, "_name", name)
    def __getattr__(self, k):
        name = object.__getattribute__(self, "_name")
        mod = _V67LazyModule._loaded.get(name)
        if mod is None:
            mod = __import__(name)
            _V67LazyModule._loaded[name] = mod
        return getattr(mod, k)

class _V67LazyAttr:
    def __init__(self, name, attr):
        self._na = (name, attr)
    def __call__(self, *a, **k):
        name, attr = self._na
        mod = __import__(name, fromlist=[attr])
        return getattr(mod, attr)(*a, **k)

