_READ_RESPONSE_CACHE = {}

def runtime_cache_get(key):
    with _READ_CACHE_LOCK:
        item = _READ_RESPONSE_CACHE.get(key)
        if not item: return None
        expires_at, payload = item
        if expires_at <= datetime.utcnow():
            # V63.20: selama upload aktif entri kedaluwarsa TETAP dilayani
            # (cache data terakhir sebelum upload) — tanpa recompute, tanpa
            # pop supaya request lain juga dilayani instan.
            if _upload_proc_active() and not getattr(_SWR_FORCE_LOCAL, 'on', False):
                return payload
            _READ_RESPONSE_CACHE.pop(key, None)
            _READ_CACHE_SIZES.pop(key, None)
            return None
        return payload

def _v63_est_size(obj, depth=0):
    """V63.27.4: estimasi deep-size payload dgn sampling (murah, toleransi ±30%).
    Dipakai utk byte-budget cache respons — dulu cache dibatasi JUMLAH entri
    (400) tanpa memandang ukuran, sehingga beberapa entri dataset penuh
    (puluhan/ratusan MB per entri) membuat RAM melewati batas 3GB PythonAnywhere
    (notif exceed + restart berulang = semua page jadi lambat)."""
    try:
        import sys as _sys
        if obj is None:
            return 16
        t = type(obj)
        if t is str:
            return 49 + len(obj)
        if t is bytes:
            return 33 + len(obj)
        if t in (int, float, bool):
            return 32
        if depth >= 6:
            return 64
        if t in (list, tuple, set, frozenset):
            n = len(obj)
            head = _sys.getsizeof(obj)
            if n == 0:
                return head
            if t in (list, tuple):
                items = obj if n <= 120 else (list(obj)[:80] + list(obj)[-20:])
            else:
                items = list(obj) if n <= 120 else list(obj)[:100]
            per = sum(_v63_est_size(x, depth + 1) for x in items) / float(len(items))
            return head + int(per * n)
        if t is dict:
            n = len(obj)
            head = _sys.getsizeof(obj)
            if n == 0:
                return head
            kv = list(obj.items())
            if n > 80:
                kv = kv[:60] + kv[-20:]
            per = sum(_v63_est_size(k, depth + 1) + _v63_est_size(v, depth + 1) for k, v in kv) / float(len(kv))
            return head + int(per * n)
        return 64
    except Exception:
        return 64

# V63.27.4: memo ukuran + budget byte (env-tunable utk eksperimen di PA)
_READ_CACHE_SIZES = {}
_READ_CACHE_MAX_BYTES = max(32, int(os.environ.get('PO_MONITOR_CACHE_MAX_MB', '256'))) * 1024 * 1024
_READ_CACHE_ENTRY_MAX_BYTES = max(4, int(os.environ.get('PO_MONITOR_CACHE_ENTRY_MAX_MB', '96'))) * 1024 * 1024
_READ_CACHE_GIANT_BYTES = 16 * 1024 * 1024  # entri > ini dianggap raksasa: TTL dipangkas

# Compact dashboard aggregates survive app restarts. The UI gets the last real
# snapshot immediately, while SWR refreshes it against the current database.
_DASHBOARD_SNAPSHOT_NAMESPACES = {
    'dashboard_stats_v2_sql', 'registered_items_summary', 'aging',
    'pending_settlement_v13', 'dashboard_pending_total', 'pic_kpi',
    'completed_summary',
}
_DASHBOARD_SNAPSHOT_DIR = os.path.join(
    os.environ.get('SERVEONE_DATA_DIR', os.path.dirname(os.path.abspath(__file__))),
    'instance', 'dashboard_snapshots')
_DASHBOARD_SNAPSHOT_LOCK = threading.Lock()
_DASHBOARD_SNAPSHOT_MAX_AGE_SECONDS = 30 * 24 * 60 * 60
_DASHBOARD_SNAPSHOT_FRESH_SECONDS = 10 * 60

def _dashboard_snapshot_namespace(key):
    return str(key[0]) if isinstance(key, tuple) and key else str(key)

def _dashboard_snapshot_path(key):
    raw = json.dumps(key, ensure_ascii=True, default=str, separators=(',', ':'))
    digest = hashlib.sha256(raw.encode('utf-8')).hexdigest()
    return os.path.join(_DASHBOARD_SNAPSHOT_DIR, digest + '.json')

def _dashboard_snapshot_load(key):
    if _dashboard_snapshot_namespace(key) not in _DASHBOARD_SNAPSHOT_NAMESPACES:
        return None
    try:
        path = _dashboard_snapshot_path(key)
        if time.time() - os.path.getmtime(path) > _DASHBOARD_SNAPSHOT_MAX_AGE_SECONDS:
            return None
        with _DASHBOARD_SNAPSHOT_LOCK, io.open(path, 'r', encoding='utf-8') as fh:
            saved = json.load(fh)
        return saved.get('payload') if isinstance(saved, dict) else None
    except (OSError, ValueError, TypeError):
        return None

def _dashboard_snapshot_is_fresh(key):
    try:
        return time.time() - os.path.getmtime(_dashboard_snapshot_path(key)) < _DASHBOARD_SNAPSHOT_FRESH_SECONDS
    except OSError:
        return False

def _dashboard_snapshot_store(key, payload):
    if _dashboard_snapshot_namespace(key) not in _DASHBOARD_SNAPSHOT_NAMESPACES:
        return
    try:
        os.makedirs(_DASHBOARD_SNAPSHOT_DIR, exist_ok=True)
        path = _dashboard_snapshot_path(key)
        tmp = path + '.tmp'
        saved = {'saved_at': datetime.utcnow().isoformat() + 'Z', 'payload': payload}
        with _DASHBOARD_SNAPSHOT_LOCK:
            with io.open(tmp, 'w', encoding='utf-8') as fh:
                json.dump(saved, fh, ensure_ascii=False, separators=(',', ':'), default=str)
            os.replace(tmp, path)
            snapshots = sorted(
                (os.path.join(_DASHBOARD_SNAPSHOT_DIR, name)
                 for name in os.listdir(_DASHBOARD_SNAPSHOT_DIR) if name.endswith('.json')),
                key=os.path.getmtime, reverse=True)
            for old in snapshots[200:]:
                try: os.remove(old)
                except OSError: pass
    except (OSError, TypeError, ValueError):
        pass

def runtime_cache_set(key, payload, ttl_seconds=20):
    # V63.27.4: byte-budget — total cache respons dibatasi (default 256MB,
    # env PO_MONITOR_CACHE_MAX_MB), per entri max 48MB. Entri raksasa tetap
    # masuk cache tapi TTL pendek (120s) — SWR tetap menyajikan entri stale
    # sambil rebuild background, jadi UX instan bertahan, RAM tidak menumpuk.
    est = None
    try:
        est = _v63_est_size(payload)
        if est > _READ_CACHE_ENTRY_MAX_BYTES:
            return  # terlalu besar utk di-cache -> dihitung ulang per request
        if est > _READ_CACHE_GIANT_BYTES:
            ttl_seconds = min(int(ttl_seconds or 20), 120)
    except Exception:
        est = None
    with _READ_CACHE_LOCK:
        _READ_RESPONSE_CACHE[key] = (datetime.utcnow() + timedelta(seconds=ttl_seconds), payload)
        if est is not None:
            _READ_CACHE_SIZES[key] = est
        # V63.20: evict kedaluwarsa dulu, lalu yang ter-tua (batas jumlah 400).
        if len(_READ_RESPONSE_CACHE) > 400:
            _now = datetime.utcnow()
            for _k in [k for k, (exp, _p) in _READ_RESPONSE_CACHE.items() if exp <= _now]:
                _READ_RESPONSE_CACHE.pop(_k, None); _READ_CACHE_SIZES.pop(_k, None)
            if len(_READ_RESPONSE_CACHE) > 400:
                for _k, _ in sorted(_READ_RESPONSE_CACHE.items(),
                                    key=lambda kv: kv[1][0])[:len(_READ_RESPONSE_CACHE) - 400]:
                    _READ_RESPONSE_CACHE.pop(_k, None); _READ_CACHE_SIZES.pop(_k, None)
        # V63.27.4: evict by BYTES — entri terbesar dulu sampai total di bawah budget.
        try:
            total = sum(_READ_CACHE_SIZES.values())
            if total > _READ_CACHE_MAX_BYTES:
                for _k, _e in sorted(_READ_CACHE_SIZES.items(), key=lambda kv: -kv[1]):
                    if total <= _READ_CACHE_MAX_BYTES:
                        break
                    _READ_CACHE_SIZES.pop(_k, None)
                    if _k in _READ_RESPONSE_CACHE:
                        _READ_RESPONSE_CACHE.pop(_k, None)
                        total -= _e
        except Exception:
            pass
    _dashboard_snapshot_store(key, payload)

# ── V61.4: stale-while-revalidate (SWR) untuk semua page ────────────────────
# Sebelum V61.4: TTL habis -> request berikutnya menanggung recompute penuh
# secara sinkron (di produksi: >10 detik). Sekarang: TTL habis -> payload lama
# tetap dilayani INSTAN dan rebuild jalan di background thread. Invalidasi
# saat data berubah tetap total (clear_runtime_caches mengosongkan semua).
_SWR_REFRESHING = set()
_SWR_FORCE_LOCAL = threading.local()

# ── V63.20: ANTI-FREEZE SAAT UPLOAD — layani cache data terakhir ────────────
# Keluhan user: selama proses upload data baru berlangsung dashboard cenderung
# freeze dan sangat lambat. Sesuai permintaan user: selama ada proses upload
# AKTIF (worker background ATAU upload inline ?sync=1 dari automation), SEMUA
# GET data dilayani dari cache respons TERAKHIR (data pra-upload) tanpa
# recompute dan tanpa rebuild background; begitu upload selesai, SWR normal
# bekerja -> data kembali fresh otomatis. Cache murni IN-MEMORY dan bounded —
# tidak menulis apa pun ke disk (aman kuota PythonAnywhere).
_UPLOAD_PROC_LOCK = threading.Lock()
_UPLOAD_PROC_N = 0
_UPLOAD_PROC_TS = 0.0
_UPLOAD_INLINE_PROC = threading.local()
_UPLOAD_PROC_MAX_S = 1800.0  # pengaman deadlock: >30 menit dianggap selesai


def _upload_proc_begin():
    global _UPLOAD_PROC_N, _UPLOAD_PROC_TS
    with _UPLOAD_PROC_LOCK:
        _UPLOAD_PROC_N += 1
        _UPLOAD_PROC_TS = time.time()


def _upload_proc_end():
    global _UPLOAD_PROC_N
    with _UPLOAD_PROC_LOCK:
        _UPLOAD_PROC_N = max(0, _UPLOAD_PROC_N - 1)


def _upload_proc_active():
    """True selama ada proses upload berjalan (worker ATAU inline)."""
    with _UPLOAD_PROC_LOCK:
        n, ts = _UPLOAD_PROC_N, _UPLOAD_PROC_TS
    if n <= 0:
        return False
    return (time.time() - ts) < _UPLOAD_PROC_MAX_S

def _swr_spawn_refresh(guard_key, refresh_url):
    """V61.4: jalankan rebuild di background via test_client replay (single-flight)."""
    # V63.20: selama upload berjalan JANGAN spawn rebuild background — user
    # dilayani cache data terakhir; rebuild ditunda sampai upload selesai
    # supaya CPU tidak berebut dengan worker upload (dashboard tetap lancar).
    if _upload_proc_active() and not getattr(_SWR_FORCE_LOCAL, 'on', False):
        return
    with _READ_CACHE_LOCK:
        if guard_key in _SWR_REFRESHING:
            return
        _SWR_REFRESHING.add(guard_key)
    try:
        from flask import current_app
        app_obj = current_app._get_current_object()
    except Exception:
        with _READ_CACHE_LOCK:
            _SWR_REFRESHING.discard(guard_key)
        return
    def _swr_refresh():
        try:
            # Tandai thread ini sebagai thread rebuild: cache get di thread ini
            # harus menghasilkan miss supaya endpoint benar-benar menghitung ulang.
            _SWR_FORCE_LOCAL.on = True
            with app_obj.app_context():
                with app_obj.test_client() as client:
                    client.get(refresh_url)
        except Exception as exc:
            try: print(f'[swr-refresh] {refresh_url} failed: {exc}', flush=True)
            except Exception: pass
        finally:
            _SWR_FORCE_LOCAL.on = False
            with _READ_CACHE_LOCK:
                _SWR_REFRESHING.discard(guard_key)
    threading.Thread(target=_swr_refresh, daemon=True, name='swr-refresh').start()

def runtime_cache_get_swr(key, refresh_url=None):
    """V61.4: cache get dengan stale-while-revalidate.

    - fresh  -> return payload (perilaku lama).
    - stale  -> return payload LAMA + spawn background rebuild (sekali,
                single-flight per key). User tidak pernah menunggu recompute.
    - miss   -> return None (endpoint menghitung sinkron; cold miss pertama).
    - dipanggil dari thread rebuild -> selalu None (wajib recompute).
    """
    if getattr(_SWR_FORCE_LOCAL, 'on', False):
        return None
    with _READ_CACHE_LOCK:
        item = _READ_RESPONSE_CACHE.get(key)
    if not item:
        payload = _dashboard_snapshot_load(key)
        if payload is None:
            return None
        snapshot_fresh = _dashboard_snapshot_is_fresh(key)
        with _READ_CACHE_LOCK:
            expires_at = datetime.utcnow() + timedelta(seconds=_DASHBOARD_SNAPSHOT_FRESH_SECONDS) if snapshot_fresh else datetime.utcnow() - timedelta(seconds=1)
            _READ_RESPONSE_CACHE[key] = (expires_at, payload)
            _READ_CACHE_SIZES[key] = _v63_est_size(payload)
        if refresh_url and not snapshot_fresh:
            _swr_spawn_refresh(key, refresh_url)
        return payload
    with _READ_CACHE_LOCK:
        expires_at, payload = item
        is_fresh = expires_at > datetime.utcnow()
    if is_fresh:
        return payload
    if not refresh_url:
        return payload
    _swr_spawn_refresh(key, refresh_url)
    return payload

def runtime_cache_key(namespace):
    return (namespace, request.query_string.decode('utf-8', errors='ignore'))


# ══ V61.5: UPLOAD DI BACKGROUND — update data tidak mengganggu performa web ══
# Latar: setiap ada yang upload, request upload memproses file secara sinkron
# (puluhan detik di CPU PythonAnywhere) sehingga semua user lain antri, lalu
# clear_runtime_caches membuat semua page recompute. Solusi: file cukup
# DISIMPAN oleh request (instan), pemrosesan dijalankan worker background
# SATU PER SATU via test_client replay, cache di-invalidasi LEMBUT (data lama
# tetap dilayani instan sampai data baru siap), dan warmup berjalan inline
# dengan jeda supaya CPU tetap bisa dipakai request user.
