def _upload_job_write_state(job_dir, state):
    """Tulis status job ke job.json secara ATOMIK (tmp + rename) supaya
    endpoint status bisa membacanya dari proses mana pun tanpa pernah
    melihat file setengah jadi."""
    try:
        os.makedirs(job_dir, exist_ok=True)
        tmp = os.path.join(job_dir, 'job.json.tmp')
        with io.open(tmp, 'w', encoding='utf-8') as fh:
            json.dump(state, fh, ensure_ascii=False, default=str)
        os.replace(tmp, os.path.join(job_dir, 'job.json'))
    except Exception as exc:
        try: print(f'[upload-job] write state failed: {exc}', flush=True)
        except Exception: pass

def _upload_job_read_state(job_id):
    # A completed job is stored in a tiny JSON file outside the temporary
    # upload payload folder, so a status poll on another WSGI worker still
    # returns DONE even after the source Excel has been deleted.
    if not re.fullmatch(r'[a-f0-9]{16}', str(job_id)):
        return None
    paths = (
        os.path.join(_UPLOAD_JOB_DIR, str(job_id), 'job.json'),
        os.path.join(_UPLOAD_JOB_DIR, f'{job_id}.status.json'),
    )
    for p in paths:
        try:
            with io.open(p, 'r', encoding='utf-8') as fh:
                return json.load(fh)
        except (OSError, ValueError):
            pass
    return None

def _upload_job_save_terminal_state(job_id, state):
    # Flat, kilobyte-sized status record.  No source Excel, DB copy, or backup.
    if not re.fullmatch(r'[a-f0-9]{16}', str(job_id)): return
    try:
        os.makedirs(_UPLOAD_JOB_DIR, exist_ok=True)
        dest = os.path.join(_UPLOAD_JOB_DIR, f'{job_id}.status.json')
        tmp = dest + '.tmp'
        with io.open(tmp, 'w', encoding='utf-8') as fh:
            json.dump(state, fh, ensure_ascii=False, default=str)
        os.replace(tmp, dest)
    except Exception as exc:
        try: print(f'[upload-job] terminal status persist failed: {exc}', flush=True)
        except Exception: pass

def _upload_job_record(job_id):
    with _UPLOAD_JOBS_LOCK:
        job = _UPLOAD_JOBS.get(str(job_id))
        return dict(job) if job else None

def _upload_job_update(job_id, **fields):
    with _UPLOAD_JOBS_LOCK:
        job = _UPLOAD_JOBS.get(str(job_id))
        if job is None: return None
        job.update(fields)
        snapshot = dict(job)
    return snapshot

# V63.27.73: one tiny revision marker shared by WSGI workers. No DB
# snapshot, cache JSON payload or Excel is persisted by this mechanism.
_DATA_REVISION_PATH = os.path.join(os.path.dirname(_UPLOAD_JOB_DIR), 'data_revision.txt')
_DATA_REVISION_LOCK = threading.Lock()
_DATA_REVISION_STATE = {'seen': None, 'checked': 0.0}

def _publish_data_revision():
    import uuid as _rev_uuid
    with _DATA_REVISION_LOCK:
        try:
            os.makedirs(os.path.dirname(_DATA_REVISION_PATH), exist_ok=True)
            tmp = _DATA_REVISION_PATH + '.' + _rev_uuid.uuid4().hex[:8] + '.tmp'
            with io.open(tmp, 'w', encoding='ascii') as fh:
                fh.write(_rev_uuid.uuid4().hex + '\n')
            os.replace(tmp, _DATA_REVISION_PATH)
            with io.open(_DATA_REVISION_PATH, 'r', encoding='ascii') as fh:
                _DATA_REVISION_STATE['seen'] = fh.read(80)
            _DATA_REVISION_STATE['checked'] = time.monotonic()
        except OSError as exc:
            print(f'[data-revision] warning: cannot publish update ({exc})', flush=True)

def _check_data_revision():
    # Max 1 shared-file read/worker/3s, not on every request.
    now = time.monotonic()
    with _DATA_REVISION_LOCK:
        if now - _DATA_REVISION_STATE['checked'] < 3.0:
            return
        _DATA_REVISION_STATE['checked'] = now
        try:
            with io.open(_DATA_REVISION_PATH, 'r', encoding='ascii') as fh:
                revision = fh.read(80)
        except OSError:
            return
        old = _DATA_REVISION_STATE['seen']
        _DATA_REVISION_STATE['seen'] = revision
    if old is not None and old != revision:
        _soft_invalidate_response_caches()
        print('[data-revision] updated caches after upload in another worker', flush=True)

@app.before_request
def _sync_upload_revision_v632773():
    if request.method == 'GET' and (request.path or '').startswith('/api/'):
        _check_data_revision()

def _upload_job_prune_locked():
    if len(_UPLOAD_JOBS) <= _UPLOAD_JOB_MAX_KEEP: return
    ordered = sorted(_UPLOAD_JOBS.items(), key=lambda kv: kv[1].get('created_at') or 0, reverse=True)
    for job_id, _job in ordered[_UPLOAD_JOB_MAX_KEEP:]:
        _UPLOAD_JOBS.pop(job_id, None)

