_UPLOAD_PAYLOAD_TTL_S = 15 * 60       # V63.13: 2j→15m — salinan Excel job crash dibuang cepat
_UPLOAD_DIR_TTL_S = 1 * 3600          # V63.13: 6j→1j — job.json job gagal cukup 1 jam utk diagnosa
_UPLOAD_SWEEP_INTERVAL_S = 5 * 60     # V63.13: janitor disk berjalan tiap 5 menit (dulu 30)
