# ── V61 SECURITY FIX: proteksi endpoint admin/debug/destructive ──────────────
# Endpoint di bawah ini TIDAK dipakai oleh frontend (diverifikasi dari bundle
# hasil build), jadi aman diproteksi tanpa memutus fitur dashboard.
# Cara pakai: set env var ADMIN_API_KEY (mis. di WSGI file PythonAnywhere:
# os.environ['ADMIN_API_KEY'] = 'kunci-rahasia-anda'), lalu panggil endpoint
# dengan header: X-Admin-Key: <nilai ADMIN_API_KEY>.
_ADMIN_API_KEY_V61 = (os.environ.get('ADMIN_API_KEY') or '').strip()

# ── V63.27.40 ACCESS MONITOR: hidden /admin password session ───────────────
# ADMIN_PASSWORD is the password typed on /admin. For backward compatibility,
# when it is not set we accept ADMIN_API_KEY as the admin password too.
_ADMIN_PASSWORD_V632740 = (os.environ.get('ADMIN_PASSWORD') or _ADMIN_API_KEY_V61 or '').strip()
_ADMIN_COOKIE_V632740 = 'serveone_admin_session'
_ADMIN_SESSION_TTL_V632740 = 12 * 60 * 60
_ADMIN_LOGIN_ATTEMPTS_V632740 = {}
_ADMIN_LOGIN_LOCK_V632740 = threading.Lock()

def _request_ip_v632740():
    # PythonAnywhere/reverse proxies normally provide X-Forwarded-For. Keep the
    # first hop (original client). Fallback to X-Real-IP / remote_addr.
    xff = (request.headers.get('X-Forwarded-For') or '').strip()
    if xff:
        return xff.split(',')[0].strip()[:64]
    return (request.headers.get('X-Real-IP') or request.remote_addr or 'unknown').strip()[:64]

def _secure_cookie_v632740():
    proto = (request.headers.get('X-Forwarded-Proto') or '').lower()
    host = (request.host or '').lower()
    return bool(request.is_secure or proto == 'https' or host.endswith('.pythonanywhere.com'))

def _admin_secret_v632740():
    seed = (os.environ.get('ADMIN_SESSION_SECRET') or _ADMIN_PASSWORD_V632740 or _ADMIN_API_KEY_V61 or 'serveone-admin-unconfigured')
    return hashlib.sha256(('serveone-v632740|' + seed).encode('utf-8')).digest()

def _admin_make_token_v632740():
    ts = str(int(time.time()))
    nonce = secrets.token_urlsafe(16)
    body = ts + '.' + nonce
    sig = hmac.new(_admin_secret_v632740(), body.encode('utf-8'), hashlib.sha256).hexdigest()
    return body + '.' + sig

def _admin_session_valid_v632740():
    token = (request.cookies.get(_ADMIN_COOKIE_V632740) or '').strip()
    try:
        ts_s, nonce, sig = token.split('.', 2)
        if not nonce or abs(time.time() - int(ts_s)) > _ADMIN_SESSION_TTL_V632740:
            return False
        body = ts_s + '.' + nonce
        good = hmac.new(_admin_secret_v632740(), body.encode('utf-8'), hashlib.sha256).hexdigest()
        return hmac.compare_digest(sig, good)
    except Exception:
        return False

def _admin_password_ok_v632740(value):
    if not _ADMIN_PASSWORD_V632740:
        return False
    try:
        return hmac.compare_digest(str(value or ''), _ADMIN_PASSWORD_V632740)
    except Exception:
        return False

def _admin_login_allowed_v632740(ip):
    now = time.time()
    with _ADMIN_LOGIN_LOCK_V632740:
        attempts = [t for t in _ADMIN_LOGIN_ATTEMPTS_V632740.get(ip, []) if now - t < 900]
        _ADMIN_LOGIN_ATTEMPTS_V632740[ip] = attempts
        return len(attempts) < 5

def _admin_login_failed_v632740(ip):
    now = time.time()
    with _ADMIN_LOGIN_LOCK_V632740:
        attempts = [t for t in _ADMIN_LOGIN_ATTEMPTS_V632740.get(ip, []) if now - t < 900]
        attempts.append(now)
        _ADMIN_LOGIN_ATTEMPTS_V632740[ip] = attempts[-8:]

def _admin_login_clear_v632740(ip):
    with _ADMIN_LOGIN_LOCK_V632740:
        _ADMIN_LOGIN_ATTEMPTS_V632740.pop(ip, None)

_PROTECTED_PREFIXES_V61 = (
    '/api/admin/',
    '/api/debug/',
    '/api/import/debug',
    '/api/import/cleanup',
    '/api/db/repair',
    '/api/disk/cleanup',
    '/api/vendor-control/debug',
)

@app.before_request
def _guard_protected_endpoints_v61():
    p = request.path
    for pref in _PROTECTED_PREFIXES_V61:
        if p == pref.rstrip('/') or p.startswith(pref):
            # V63.27.40: existing scripts may still use X-Admin-Key, while the
            # hidden /admin UI uses a signed HttpOnly admin-session cookie.
            header_ok = bool(_ADMIN_API_KEY_V61 and hmac.compare_digest(
                request.headers.get('X-Admin-Key', '').strip(), _ADMIN_API_KEY_V61))
            if not header_ok and not _admin_session_valid_v632740():
                if not (_ADMIN_API_KEY_V61 or _ADMIN_PASSWORD_V632740):
                    return jsonify({'error': 'Admin belum dikonfigurasi. Set ADMIN_PASSWORD atau ADMIN_API_KEY.'}), 403
                return jsonify({'error': 'Admin authentication required.'}), 403
            return None
    return None

