# ── V63.27.40 ACCESS MONITOR ───────────────────────────────────────────────
# Keep this intentionally small: device registry is persistent, while IP history
# and activity logs are automatically retained for only 30 days.
class AccessDevice(db.Model):
    __tablename__ = 'access_device'
    id = db.Column(db.Integer, primary_key=True)
    device_id = db.Column(db.String(40), nullable=False, unique=True, index=True)
    token_hash = db.Column(db.String(64), nullable=False, unique=True, index=True)
    # V63.27.65: secondary browser-persistence credential. The raw recovery
    # token lives only in browser localStorage; the DB stores only its hash.
    # It lets the same browser restore its HttpOnly device cookie after a
    # cookie-only reset without tying identity to IP/network.
    nickname = db.Column(db.String(80), nullable=False, index=True)
    alias = db.Column(db.String(120))
