# ── V63.27.40 ACCESS MONITOR helpers ───────────────────────────────────────
_ACCESS_DEVICE_COOKIE_V632740 = 'serveone_device'
_ACCESS_RETENTION_DAYS_V632740 = 30
_ACCESS_PURGE_LOCK_V632740 = threading.Lock()
_ACCESS_PURGE_LAST_V632740 = 0.0
_ACCESS_DEVICE_CACHE_V632740 = {}  # token_hash -> (expires_ts, principal dict or None)
_ACCESS_IP_BLOCK_CACHE_V632740 = {}  # ip -> (expires_ts, blocked bool)

# V63.27.45: Serveone's shared VPN egress is expected to be used by many employees.
# Extra trusted/shared egress IPs can be added without editing code via
# ACCESS_TRUSTED_IPS=1.2.3.4,5.6.7.8
_ACCESS_TRUSTED_IPS_V632745 = frozenset(
    {'218.49.227.86'} |
    {x.strip() for x in str(os.environ.get('ACCESS_TRUSTED_IPS') or '').split(',') if x.strip()}
)

def _access_hash_token_v632740(raw):
    return hashlib.sha256(str(raw or '').encode('utf-8')).hexdigest()

def _access_new_recovery_token_v632765():
    """Return (raw, hash) for the localStorage recovery credential.

    The raw token is returned to the browser exactly when it is issued; only
    the SHA-256 hash is persisted server-side. It is intentionally independent
    from IP so Wi-Fi/VPN/network changes never create a new device identity.
    """
    raw = secrets.token_urlsafe(32)
    return raw, _access_hash_token_v632740(raw)

# V63.27.70: recovery identity is optional and must never lock the dashboard.
# The normal browser Device ID continues to use the existing HttpOnly cookie.
# recovery_hash is managed with raw SQL so an older DB that has not migrated yet
# can still serve /admin and every dashboard page normally.
_ACCESS_RECOVERY_SCHEMA_LOCK_V632770 = threading.Lock()
_ACCESS_RECOVERY_SCHEMA_READY_V632770 = None

def _access_ensure_recovery_schema_v632770(force=False):
    global _ACCESS_RECOVERY_SCHEMA_READY_V632770
    if _ACCESS_RECOVERY_SCHEMA_READY_V632770 is True and not force:
        return True
    with _ACCESS_RECOVERY_SCHEMA_LOCK_V632770:
        if _ACCESS_RECOVERY_SCHEMA_READY_V632770 is True and not force:
            return True
        try:
            uri = str(app.config.get('SQLALCHEMY_DATABASE_URI') or '')
            with db.engine.begin() as conn:
                if 'sqlite' in uri:
                    cols = {str(r[1]).lower() for r in conn.execute(text('PRAGMA table_info(access_device)'))}
                    if 'recovery_hash' not in cols:
                        conn.execute(text('ALTER TABLE access_device ADD COLUMN recovery_hash VARCHAR(64)'))
                    conn.execute(text('CREATE UNIQUE INDEX IF NOT EXISTS idx_access_device_recovery_hash ON access_device (recovery_hash)'))
                else:
                    cols = {str(r[0]).lower() for r in conn.execute(text("SELECT column_name FROM information_schema.columns WHERE table_name='access_device'"))}
                    if 'recovery_hash' not in cols:
                        conn.execute(text('ALTER TABLE access_device ADD COLUMN recovery_hash VARCHAR(64)'))
                    try:
                        conn.execute(text('CREATE UNIQUE INDEX IF NOT EXISTS idx_access_device_recovery_hash ON access_device (recovery_hash)'))
                    except Exception:
                        pass
            _ACCESS_RECOVERY_SCHEMA_READY_V632770 = True
            return True
        except Exception as exc:
            _ACCESS_RECOVERY_SCHEMA_READY_V632770 = False
            try:
                db.session.rollback()
            except Exception:
                pass
            try:
                app.logger.warning('Access recovery schema unavailable; continuing with cookie-only device identity: %s', exc)
            except Exception:
                pass
            return False

def _access_recovery_hash_for_device_v632770(device_id):
    if not _access_ensure_recovery_schema_v632770():
        return None
    try:
        row = db.session.execute(text('SELECT recovery_hash FROM access_device WHERE device_id=:d'), {'d': device_id}).first()
        return row[0] if row else None
    except Exception:
        try: db.session.rollback()
        except Exception: pass
        return None

def _access_set_recovery_hash_v632770(device_id, recovery_hash):
    if not _access_ensure_recovery_schema_v632770():
        return False
    try:
        db.session.execute(text('UPDATE access_device SET recovery_hash=:h WHERE device_id=:d'), {'h': recovery_hash, 'd': device_id})
        return True
    except Exception:
        try: db.session.rollback()
        except Exception: pass
        return False

def _access_device_from_recovery_v632770(recovery_hash):
    if not recovery_hash or not _access_ensure_recovery_schema_v632770():
        return None
    try:
        row = db.session.execute(text('SELECT id FROM access_device WHERE recovery_hash=:h LIMIT 1'), {'h': recovery_hash}).first()
        if not row:
            return None
        return db.session.get(AccessDevice, row[0])
    except Exception:
        try: db.session.rollback()
        except Exception: pass
        return None

def _access_user_agent_v632740(ua):
    u = str(ua or '')
    browser = 'Unknown Browser'
    os_name = 'Unknown OS'
    m = re.search(r'Edg/([\d.]+)', u)
    if m: browser = 'Edge ' + m.group(1).split('.')[0]
    else:
        m = re.search(r'OPR/([\d.]+)', u)
        if m: browser = 'Opera ' + m.group(1).split('.')[0]
        else:
            m = re.search(r'Chrome/([\d.]+)', u)
            if m: browser = 'Chrome ' + m.group(1).split('.')[0]
            else:
                m = re.search(r'Firefox/([\d.]+)', u)
                if m: browser = 'Firefox ' + m.group(1).split('.')[0]
                else:
                    m = re.search(r'Version/([\d.]+).*Safari/', u)
                    if m: browser = 'Safari ' + m.group(1).split('.')[0]
    if 'Windows NT 10.0' in u:
        os_name = 'Windows 10/11'
    elif 'Windows NT' in u:
        os_name = 'Windows'
    elif 'Mac OS X' in u:
        mm = re.search(r'Mac OS X ([0-9_]+)', u)
        os_name = 'macOS' + ((' ' + mm.group(1).replace('_','.')) if mm else '')
    elif 'Android' in u:
        mm = re.search(r'Android ([0-9.]+)', u)
        os_name = 'Android' + ((' ' + mm.group(1)) if mm else '')
    elif 'iPhone' in u or 'iPad' in u:
        os_name = 'iOS/iPadOS'
    elif 'Linux' in u:
        os_name = 'Linux'
    return browser[:120], os_name[:120]

def _access_get_device_v632740():
    raw = (request.cookies.get(_ACCESS_DEVICE_COOKIE_V632740) or '').strip()
    if not raw:
        return None
    try:
        return AccessDevice.query.filter_by(token_hash=_access_hash_token_v632740(raw)).first()
    except Exception:
        return None

def _access_principal_v632740():
    cached_req = getattr(g, '_access_principal_v632740', '__missing__')
    if cached_req != '__missing__':
        return cached_req
    raw = (request.cookies.get(_ACCESS_DEVICE_COOKIE_V632740) or '').strip()
    if not raw:
        g._access_principal_v632740 = None
        return None
    th = _access_hash_token_v632740(raw)
    now = time.time()
    cached = _ACCESS_DEVICE_CACHE_V632740.get(th)
    if cached and cached[0] > now:
        g._access_principal_v632740 = cached[1]
        return cached[1]
    try:
        row = db.session.query(AccessDevice.device_id, AccessDevice.nickname, AccessDevice.blocked).filter_by(token_hash=th).first()
        info = None if row is None else {'device_id': row[0], 'nickname': row[1], 'blocked': bool(row[2]), 'token_hash': th}
        if len(_ACCESS_DEVICE_CACHE_V632740) > 2000:
            _ACCESS_DEVICE_CACHE_V632740.clear()
        _ACCESS_DEVICE_CACHE_V632740[th] = (now + 30.0, info)
        g._access_principal_v632740 = info
        return info
    except Exception:
        try: db.session.rollback()
        except Exception: pass
        g._access_principal_v632740 = None
        return None

def _access_invalidate_device_cache_v632740(token_hash=None):
    if token_hash:
        _ACCESS_DEVICE_CACHE_V632740.pop(token_hash, None)
    else:
        _ACCESS_DEVICE_CACHE_V632740.clear()

def _access_is_ip_blocked_v632740(ip):
    now = time.time()
    cached = _ACCESS_IP_BLOCK_CACHE_V632740.get(ip)
    if cached and cached[0] > now:
        return cached[1]
    try:
        blocked = AccessBlockedIP.query.filter_by(ip=ip).first() is not None
        if len(_ACCESS_IP_BLOCK_CACHE_V632740) > 1000:
            _ACCESS_IP_BLOCK_CACHE_V632740.clear()
        _ACCESS_IP_BLOCK_CACHE_V632740[ip] = (now + 30.0, blocked)
        return blocked
    except Exception:
        try: db.session.rollback()
        except Exception: pass
        return False

def _access_touch_v632740(device, ip=None):
    if not device:
        return
    ip = (ip or _request_ip_v632740())[:64]
    now = datetime.utcnow()
    ua = (request.headers.get('User-Agent') or '')[:2000]
    browser, os_name = _access_user_agent_v632740(ua)
    try:
        device.last_seen_at = now
        device.last_ip = ip
        if not device.first_ip: device.first_ip = ip
        if ua: device.user_agent = ua
        device.browser = browser
        device.os_name = os_name
        seen = AccessIPSeen.query.filter_by(device_id=device.device_id, ip=ip).first()
        if seen is None:
            seen = AccessIPSeen(device_id=device.device_id, nickname=device.nickname, ip=ip,
                                first_seen_at=now, last_seen_at=now, request_count=1)
            db.session.add(seen)
        else:
            seen.nickname = device.nickname
            seen.last_seen_at = now
            seen.request_count = int(seen.request_count or 0) + 1
        db.session.commit()
    except Exception:
        try: db.session.rollback()
        except Exception: pass

def _access_purge_old_v632740(force=False):
    global _ACCESS_PURGE_LAST_V632740
    now_ts = time.time()
    if not force and now_ts - _ACCESS_PURGE_LAST_V632740 < 6 * 3600:
        return
    if not _ACCESS_PURGE_LOCK_V632740.acquire(False):
        return
    try:
        if not force and now_ts - _ACCESS_PURGE_LAST_V632740 < 6 * 3600:
            return
        cutoff = datetime.utcnow() - timedelta(days=_ACCESS_RETENTION_DAYS_V632740)
        try:
            AccessActivity.query.filter(AccessActivity.created_at < cutoff).delete(synchronize_session=False)
            AccessIPSeen.query.filter(AccessIPSeen.last_seen_at < cutoff).delete(synchronize_session=False)
            db.session.commit()
            _ACCESS_PURGE_LAST_V632740 = now_ts
        except Exception:
            try: db.session.rollback()
            except Exception: pass
    finally:
        _ACCESS_PURGE_LOCK_V632740.release()

def _access_dataset_name_v632745(path=None):
    """Human-readable dataset/action scope. This is audit metadata only."""
    p = str(path or request.path or '').lower()
    if 'item-registration-vendor' in p:
        return 'Item Registration - For Vendor'
    if '/api/export/item-registration' in p:
        return 'Item Registration - All Data'
    if '/api/export/all-so' in p:
        return 'Pending Delivery'
    if '/api/export/settlement' in p:
        return 'Settlement'
    if '/api/export/rfq' in p:
        return 'RFQ'
    if '/api/import/export' in p:
        return 'Import Dashboard'
    if '/api/export/all-registered-items' in p:
        return 'All Registered Items'
    if '/api/cost-reduction/export' in p:
        kind = str(request.args.get('type') or 'pareto').strip().lower()
        return {
            'pareto': 'Cost Reduction - Pareto Top Priority',
            'vendor': 'Cost Reduction - Authorized Sourcing',
            'achieved': 'Achieved Cost Reduction',
            'risk': 'Watchlist',
            'details': 'Cost Reduction - Detailed Analysis',
        }.get(kind, 'Cost Reduction')
    if '/cost-reduction/authorized-vendors' in p:
        return 'Cost Reduction - Authorized Vendor'
    if '/cost-reduction/actions' in p:
        return 'Cost Reduction - Action'
    if '/settlement' in p:
        return 'Settlement'
    if '/item-registration' in p:
        return 'Item Registration'
    if '/rfq' in p:
        return 'RFQ'
    if '/import' in p:
        return 'Import Dashboard'
    return ''


def _access_activity_label_v632740(path, method, is_download=False):
    p = str(path or '').lower()
    m = str(method or '').upper()
    dataset = _access_dataset_name_v632745(path)
    if is_download or 'download' in p or 'export' in p:
        return ('Downloaded ' + dataset) if dataset else 'Downloaded / exported data'
    if '/upload' in p:
        return ('Uploaded ' + dataset) if dataset else 'Uploaded data'
    if 'delete' in p or m == 'DELETE':
        return ('Deleted ' + dataset) if dataset else 'Deleted data'
    if m == 'POST':
        return ('Updated ' + dataset) if dataset else 'Submitted data'
    if m in ('PUT', 'PATCH'):
        return ('Updated ' + dataset) if dataset else 'Edited data'
    return m + ' ' + str(path or '')[:120]


def _access_audit_details_v632745(response=None):
    """Build small, useful audit metadata without copying business/download data.

    We store only things such as dataset name, exported filename, active filter
    parameters, uploaded filename, changed field names, and compact identifiers.
    Spreadsheet/table rows and response bodies are never written to AccessActivity.
    """
    try:
        out = {}
        dataset = _access_dataset_name_v632745(request.path)
        if dataset:
            out['dataset'] = dataset

        # Download metadata: final filename from Content-Disposition, not file bytes.
        if response is not None:
            cd = str(response.headers.get('Content-Disposition') or '')
            m = re.search(r"filename\*?=(?:UTF-8''|\")?([^\";]+)", cd, re.I)
            if m:
                try:
                    from urllib.parse import unquote
                    out['file'] = unquote(m.group(1).strip().strip('"'))[:255]
                except Exception:
                    out['file'] = m.group(1).strip().strip('"')[:255]

        # Query-string values are filters/scope chosen by the user, not exported rows.
        filters = {}
        skip = {'password', 'token', 'api_key', 'key', 'secret'}
        for key in request.args.keys():
            if str(key).lower() in skip:
                continue
            vals = [str(v).strip()[:100] for v in request.args.getlist(key) if str(v).strip()]
            if vals:
                filters[str(key)[:80]] = vals[:20]
        if filters:
            out['filters'] = filters

        # Mutations: record field names + compact identifiers only. Do not duplicate
        # free-text notes/remarks/specifications or other payload contents.
        method = str(request.method or '').upper()
        if method in ('POST', 'PUT', 'PATCH', 'DELETE'):
            body = request.get_json(silent=True)
            if isinstance(body, dict):
                sensitive = {'password', 'token', 'api_key', 'secret'}
                out['fields'] = sorted(str(k)[:80] for k in body.keys() if str(k).lower() not in sensitive)[:30]
                id_keys = ('id', 'item_id', 'product_id', 'so_number', 'so_item', 'vendor_id', 'vendor_name',
                           'pic', 'pic_name', 'client', 'client_name', 'status', 'action_id', 'opportunity_key', 'row_key')
                ids = {}
                for k in id_keys:
                    v = body.get(k)
                    if v is None or isinstance(v, (dict, list)):
                        continue
                    txt = str(v).strip()
                    if txt:
                        ids[k] = txt[:120]
                if ids:
                    out['identifiers'] = ids
            elif request.form:
                keys = [str(k)[:80] for k in request.form.keys() if str(k).lower() not in {'password','token','api_key','secret'}]
                if keys:
                    out['fields'] = sorted(keys)[:30]
            if request.files:
                files = [str(f.filename or '').strip()[:255] for f in request.files.values() if getattr(f, 'filename', None)]
                if files:
                    out['uploaded_files'] = files[:10]

        # URL path IDs are useful for identifying edited/deleted records.
        nums = re.findall(r'/([0-9]{1,12})(?:/|$)', str(request.path or ''))
        if nums:
            out['record_id'] = nums[-1]

        return json.dumps(out, ensure_ascii=False, separators=(',', ':'))[:4000] if out else None
    except Exception:
        return None


def _access_log_v632740(device, action, method=None, path=None, page=None, status_code=None, ip=None, details=None):
    if not device:
        return
    try:
        if isinstance(device, dict):
            device_id = device.get('device_id')
            nickname = device.get('nickname')
        else:
            device_id = device.device_id
            nickname = device.nickname
        if not device_id or not nickname:
            return
        row = AccessActivity(
            device_id=device_id, nickname=nickname,
            ip=(ip or _request_ip_v632740())[:64], action=str(action or 'Activity')[:160],
            method=(method or '')[:10], path=str(path or '')[:500], page=str(page or '')[:255],
            details=(str(details)[:4000] if details else None),
            status_code=int(status_code) if status_code is not None else None, created_at=datetime.utcnow())
        db.session.add(row)
        db.session.commit()
    except Exception:
        try: db.session.rollback()
        except Exception: pass


def _access_log_response_v632740(principal, action, method, path, status_code, ip=None, details=None):
    """Write audit row on a separate transaction so after_request never commits
    or rolls back business-data changes from the endpoint being audited."""
    if not principal:
        return
    try:
        values = {
            'device_id': principal.get('device_id'), 'nickname': principal.get('nickname'),
            'ip': (ip or _request_ip_v632740())[:64], 'action': str(action or 'Activity')[:160],
            'method': str(method or '')[:10], 'path': str(path or '')[:500], 'page': None,
            'details': (str(details)[:4000] if details else None),
            'status_code': int(status_code) if status_code is not None else None,
            'created_at': datetime.utcnow(),
        }
        if not values['device_id'] or not values['nickname']:
            return
        with db.engine.begin() as conn:
            conn.execute(AccessActivity.__table__.insert().values(**values))
    except Exception:
        pass

def _access_browser_request_v632740():
    # Keep external automation/server-to-server integrations working. Normal
    # browser fetch/XHR sends Sec-Fetch-Site or an Origin/Referer.
    if request.headers.get('Sec-Fetch-Site'):
        return True
    origin = (request.headers.get('Origin') or '').strip()
    referer = (request.headers.get('Referer') or '').strip()
    return bool(origin or referer)

@app.before_request
def _access_browser_guard_v632740():
    # Desktop-only: the original browser-device registration is a web-server
    # access-monitor control, not an authentication requirement for a single-PC
    # application. In desktop mode, localhost session validation is handled by
    # desktop_session_guard (registered first in desktop_runtime.py).
    # Never disable this guard when running the normal web deployment.
    if (os.environ.get('SERVEONE_DESKTOP_MODE') == '1'
            and (request.host.split(':')[0] in ('127.0.0.1', 'localhost', '[::1]'))):
        return None
    p = request.path or ''
    if not p.startswith('/api/'):
        return None
    if p.startswith('/api/access/') or p.startswith('/api/admin/') or p.startswith('/api/debug/'):
        return None
    # Explicit IP blocks apply to every non-admin API request, including
    # server-to-server clients.  This makes the admin Block IP action a real
    # network block; /admin remains reachable so the block can be reversed.
    ip = _request_ip_v632740()
    if _access_is_ip_blocked_v632740(ip):
        return jsonify({'error':'Access blocked by administrator.','blocked':True,'blocked_scope':'ip'}), 403
    # Registration is browser-only so existing scheduled uploads/integrations
    # that do not send browser navigation headers keep working unchanged.
    if not _access_browser_request_v632740():
        return None
    device = _access_principal_v632740()
    if device is None:
        return jsonify({'error':'Device registration required.','registration_required':True}), 428
    if device.get('blocked'):
        return jsonify({'error':'This device has been blocked by administrator.','blocked':True,'blocked_scope':'device'}), 403
    return None

@app.after_request
def _access_audit_mutations_v632740(response):
    # No browser identity or multi-user access log in single-user desktop mode.
    if os.environ.get('SERVEONE_DESKTOP_MODE') == '1':
        return response
    try:
        p = request.path or ''
        if p.startswith('/api/') and not p.startswith('/api/access/') and not p.startswith('/api/admin/'):
            device = _access_principal_v632740()
            if device and not device.get('blocked'):
                method = (request.method or '').upper()
                cd = (response.headers.get('Content-Disposition') or '').lower()
                is_download = ('attachment' in cd) or ('download' in p.lower()) or ('export' in p.lower())
                if method in ('POST','PUT','PATCH','DELETE') or is_download:
                    _access_log_response_v632740(
                        device, _access_activity_label_v632740(p, method, is_download=is_download),
                        method, p, response.status_code, details=_access_audit_details_v632745(response)
                    )
    except Exception:
        try: db.session.rollback()
        except Exception: pass
    return response

_RATE_CACHE = {}
_FX_RATE_CACHE = {}

# V63.5: semua mata uang frankfurter yang didukung untuk konversi ke IDR.
# Sebelumnya hanya USD/EUR — JPY/SGD/dll lolos mentah tanpa dikonversi.
_FX_SUPPORTED_CURRENCIES = frozenset({'USD', 'EUR', 'JPY', 'SGD', 'GBP', 'AUD', 'HKD', 'CNY', 'KRW', 'CHF', 'CAD', 'NZD', 'MYR', 'THB', 'PHP', 'INR', 'SEK', 'NOK', 'DKK', 'MXN', 'BRL', 'PLN', 'CZK', 'HUF', 'ILS', 'TRY', 'ZAR', 'ISK', 'BGN', 'RON'})
_FX_SELFHEAL_DONE = set()  # V63.5: self-heal fetch sekali per currency per proses
_FX_SELFHEAL_LAST_TRY = {}  # V63.12: timestamp gagal fetch terakhir per currency (retry 10 menit)

_FX_OPENER_CACHE = {}  # V63.12: {'idx': handler sukses, 'fail_until': timestamp breaker}

def _fetch_rate_from_api(d, currency='USD'):
    """V63.12: direct dulu, lalu env proxy, lalu proxy PythonAnywhere
    (proxy.server:3128 — outbound PA free/basic DILARANG langsung, sehingga
    versi lama SELALU gagal fetch -> exchange_rate_fx kosong -> KPI 0).
    Handler sukses diingat; kalau semua gagal, breaker 5 menit supaya KPI
    tidak menghabiskan waktu mencoba lagi di tiap request."""
    import urllib.request, json as _json, os as _os, time as _time
    cur = (currency or 'USD').strip().upper()
    url = f"https://api.frankfurter.dev/v2/rate/{cur}/IDR?date={d.isoformat()}"
    fu = _FX_OPENER_CACHE.get('fail_until')
    if fu and _time.time() < fu:
        return None
    handlers = [('direct', urllib.request.ProxyHandler({}))]
    _env_px = _os.environ.get('https_proxy') or _os.environ.get('HTTPS_PROXY')
    if _env_px:
        handlers.append(('env', urllib.request.ProxyHandler({'https': _env_px, 'http': _env_px})))
    handlers.append(('pa', urllib.request.ProxyHandler({'https': 'http://proxy.server:3128', 'http': 'http://proxy.server:3128'})))
    order = list(range(len(handlers)))
    _ok = _FX_OPENER_CACHE.get('idx')
    if _ok is not None and _ok in order:
        order.remove(_ok); order.insert(0, _ok)
    for i in order:
        try:
            with urllib.request.build_opener(handlers[i][1]).open(url, timeout=6) as resp:
                data = _json.loads(resp.read())
            rate = float(data['rate'])
            if rate > 0:
                _FX_OPENER_CACHE['idx'] = i
                return rate
        except Exception:
            continue
    _FX_OPENER_CACHE['fail_until'] = _time.time() + 300
    return None

def _fx_persist(cur, d, rate):
    """V63.5: simpan kurs non-USD ke tabel exchange_rate_fx (best-effort)."""
    try:
        db.session.add(ExchangeRateFX(currency=cur, rate_date=d, rate_to_idr=rate, source='frankfurter'))
        db.session.commit()
    except Exception:
        db.session.rollback()

def _get_fallback_rate():
    last = ExchangeRate.query.order_by(ExchangeRate.rate_date.desc()).first()
    return last.usd_to_idr if last else 16000.0

def get_usd_to_idr(d, cache_only=False):
    if d is None: return _get_fallback_rate()
    if d in _RATE_CACHE: return _RATE_CACHE[d]
    rec = ExchangeRate.query.filter_by(rate_date=d).first()
    if rec:
        _RATE_CACHE[d] = rec.usd_to_idr
        return rec.usd_to_idr
    if not cache_only and d <= date.today():
        rate = _fetch_rate_from_api(d)
        if rate:
            try:
                db.session.add(ExchangeRate(rate_date=d, usd_to_idr=rate, source='frankfurter'))
                db.session.commit()
            except Exception: db.session.rollback()
            _RATE_CACHE[d] = rate
            return rate
    nearest = ExchangeRate.query.order_by(func.abs(func.julianday(ExchangeRate.rate_date) - func.julianday(str(d)))).first()
    if nearest:
        _RATE_CACHE[d] = nearest.usd_to_idr
        return nearest.usd_to_idr
    return _get_fallback_rate()

def get_currency_to_idr(currency, d, cache_only=False):
    """V63.5: konversi 1 unit `currency` -> IDR pada tanggal `d`.
    USD = jalur lama (tabel exchange_rate, fallback 16000) — tidak berubah.
    Mata uang lain (EUR/JPY/SGD/dll) = _FX_RATE_CACHE -> tabel exchange_rate_fx
    -> fetch frankfurter (bila diizinkan) -> rate terdekat mata uang sama.
    Return None bila benar-benar tidak ada rate (pemanggil = 0/abaikan)."""
    cur = (currency or 'IDR').strip().upper()
    if cur in ('IDR', ''): return 1.0
    if cur == 'USD': return get_usd_to_idr(d, cache_only=cache_only)
    if cur not in _FX_SUPPORTED_CURRENCIES: return None
    if d is None: d = date.today()
    key = (cur, d)
    if key in _FX_RATE_CACHE: return _FX_RATE_CACHE[key]
    try:
        rec = ExchangeRateFX.query.filter_by(currency=cur, rate_date=d).first()
    except Exception:
        rec = None
    if rec:
        _FX_RATE_CACHE[key] = rec.rate_to_idr
        return rec.rate_to_idr
    if not cache_only and d <= date.today():
        rate = _fetch_rate_from_api(d, cur)
        if rate:
            _fx_persist(cur, d, rate)
            _FX_RATE_CACHE[key] = rate
            return rate
    try:
        # V63.12: baris rate_date/rate NULL di SQLite sort paling depan (ASC)
        # -> nearest bisa balik baris kosong -> rate None ter-cache.
        nearest = ExchangeRateFX.query.filter(ExchangeRateFX.currency == cur,
                                              ExchangeRateFX.rate_date.isnot(None),
                                              ExchangeRateFX.rate_to_idr.isnot(None)).order_by(
            func.abs(func.julianday(ExchangeRateFX.rate_date) - func.julianday(str(d)))).first()
    except Exception:
        nearest = None
    if nearest:
        _FX_RATE_CACHE[key] = nearest.rate_to_idr
        return nearest.rate_to_idr
    return None



# Cap on parallel FX API calls per prefetch — prevents hammering the upstream
# frankfurter API when a large upload introduces many new unique dates.
_FX_PARALLEL_MAX = 8
_FX_FETCH_CAP_PER_CALL = 40  # max unique dates to fetch in a single prefetch call


def _fetch_rates_parallel(dates_sorted, currency='USD'):
    """Fetch multiple FX rates concurrently. Returns dict {date: rate}."""
    if not dates_sorted:
        return {}
    from concurrent.futures import ThreadPoolExecutor, as_completed
    results = {}
    # Cap to avoid runaway API calls
    capped = list(dates_sorted)[:_FX_FETCH_CAP_PER_CALL]
    try:
        with ThreadPoolExecutor(max_workers=_FX_PARALLEL_MAX) as ex:
            futures = {ex.submit(_fetch_rate_from_api, d, currency): d for d in capped}
            for fut in as_completed(futures):
                d = futures[fut]
                try:
                    rate = fut.result()
                    if rate is not None:
                        results[d] = rate
                except Exception:
                    pass
    except Exception:
        # Fallback to sequential if thread pool fails
        for d in capped:
            rate = _fetch_rate_from_api(d, currency)
            if rate is not None:
                results[d] = rate
    return results


def prefetch_exchange_rates(dates, fetch_missing=True, currency='USD'):
    cur = (currency or 'USD').strip().upper()
    if not dates or cur in ('IDR', ''): return
    if cur != 'USD':
        # V63.5: cabang non-USD kini DB-backed (exchange_rate_fx) — dulu hanya
        # memori + fallback rate USD yang salah makna untuk mata uang lain.
        needed = {d for d in dates if d is not None and (cur, d) not in _FX_RATE_CACHE}
        if not needed: return
        try:
            db_rows = ExchangeRateFX.query.filter(
                ExchangeRateFX.currency == cur,
                ExchangeRateFX.rate_date.in_(list(needed))).all()
        except Exception:
            db_rows = []
        for row in db_rows:
            _FX_RATE_CACHE[(cur, row.rate_date)] = row.rate_to_idr
        needed -= {row.rate_date for row in db_rows}
        if not needed: return
        to_fetch = sorted(d for d in needed if d <= date.today())
        # fetch_missing=True (jalur upload) ATAU self-heal: DB kosong total utk
        # currency ini -> sekali per proses, fetch capped agar halaman pertama
        # menampilkan konversi nyata (bukan 0), lalu tersimpan di DB.
        _fx_allowed = fetch_missing or (cur not in _FX_SELFHEAL_DONE and not db_rows)
        if (not _fx_allowed) and (cur not in _FX_SELFHEAL_DONE) and (cur in _FX_SELFHEAL_LAST_TRY):
            # V63.12: fetch terakhir GAGAL -> izinkan retry tiap 10 menit.
            # Dulu DONE di-set SEBELUM fetch -> sekali gagal, tidak pernah
            # dicoba lagi sampai app reload -> kurs kosong selamanya.
            import time as _t6312
            if _t6312.time() - _FX_SELFHEAL_LAST_TRY[cur] >= 600:
                _fx_allowed = True
        if to_fetch and _fx_allowed:
            rates = _fetch_rates_parallel(to_fetch, cur)
            if rates:
                _FX_SELFHEAL_DONE.add(cur)
            else:
                import time as _t6312b
                _FX_SELFHEAL_LAST_TRY[cur] = _t6312b.time()
            for d, rate in rates.items():
                _FX_RATE_CACHE[(cur, d)] = rate
                _fx_persist(cur, d, rate)
                needed.discard(d)
        if not needed: return
        try:
            all_cur = ExchangeRateFX.query.filter(ExchangeRateFX.currency == cur,
                                                  ExchangeRateFX.rate_date.isnot(None),
                                                  ExchangeRateFX.rate_to_idr.isnot(None)).order_by(ExchangeRateFX.rate_date).all()
        except Exception:
            all_cur = []
        mem_dates = sorted({d0 for (c0, d0) in _FX_RATE_CACHE if c0 == cur and _FX_RATE_CACHE[(c0, d0)]})
        for d in needed:
            nearest_rate = None
            if all_cur:
                nearest_rate = min(all_cur, key=lambda r: abs((r.rate_date - d).days)).rate_to_idr
            if nearest_rate is None and mem_dates:
                nd = min(mem_dates, key=lambda d0: abs((d0 - d).days))
                nearest_rate = _FX_RATE_CACHE[(cur, nd)]
            if nearest_rate is not None:
                _FX_RATE_CACHE[(cur, d)] = nearest_rate
        return
    needed = {d for d in dates if d is not None and d not in _RATE_CACHE}
    if not needed: return
    db_rows = ExchangeRate.query.filter(ExchangeRate.rate_date.in_(list(needed))).all()
    for row in db_rows:
        _RATE_CACHE[row.rate_date] = row.usd_to_idr
    needed -= {row.rate_date for row in db_rows}
    if not needed: return
    if fetch_missing:
        today = date.today()
        to_api = sorted(d for d in needed if d <= today)
        if to_api:
            rates = _fetch_rates_parallel(to_api, 'USD')
            fetched_rows = []
            for d, rate in rates.items():
                _RATE_CACHE[d] = rate
                fetched_rows.append(ExchangeRate(rate_date=d, usd_to_idr=rate, source='frankfurter'))
                needed.discard(d)
            if fetched_rows:
                try:
                    db.session.bulk_save_objects(fetched_rows)
                    db.session.commit()
                except Exception: db.session.rollback()
    if needed:
        fallback = _get_fallback_rate()
        all_rates = ExchangeRate.query.order_by(ExchangeRate.rate_date).all()
        for d in needed:
            if all_rates:
                nearest = min(all_rates, key=lambda r: abs((r.rate_date - d).days))
                _RATE_CACHE[d] = nearest.usd_to_idr
            else:
                _RATE_CACHE[d] = fallback

def convert_to_idr(amount, currency, rate_date=None, cache_only=False):
    if not amount: return 0.0
    cur = (currency or 'IDR').strip().upper()
    if cur in ('IDR', ''): return float(amount)
    if cur in _FX_SUPPORTED_CURRENCIES:
        _rt = get_currency_to_idr(cur, rate_date, cache_only=cache_only)
        return float(amount) * _rt if _rt else 0.0
    return float(amount)

def prefetch_convertible_exchange_rates(rows, fetch_missing=False):
    """V63.5: prefetch rate utk SEMUA mata uang yang didukung (dulu hanya
    USD/EUR) — dikelompokkan per currency, cache sama dgn Pending Delivery."""
    by_cur = {}
    for s in rows:
        cur = (getattr(s, 'purchasing_currency', '') or '').strip().upper()
        if cur in ('', 'IDR') or cur not in _FX_SUPPORTED_CURRENCIES: continue
        d = getattr(s, 'so_create_date', None)
        if d is not None: by_cur.setdefault(cur, set()).add(d)
    for cur, dates in by_cur.items():
        prefetch_exchange_rates(dates, fetch_missing=fetch_missing, currency=cur)


def raw_purchase_amount(s):
    raw = float(s.purchasing_amount or 0)
    if raw == 0 and s.purchasing_price: raw = float(s.purchasing_price) * float(s.so_qty or 0)
    return raw


# ── V61 PERF: agregasi order stats SO (delivered/returned) di-cache bersama ─
# Dulu SETIAP request /api/all-registered-items dan /api/dashboard/
# registered-items-summary menarik SEMUA baris SO 'Delivery Completed' +
# 'Return' sebagai full ORM rows lalu menghitung raw_purchase_amount per
# baris — inilah penyebab search (terutama saat mengetik di All Registered
# Items) dan initial load dashboard lambat. Sekarang agregasi dihitung SEKALI
# (hanya kolom yang dibutuhkan) lalu di-cache 120 detik, dan di-invalidate
# otomatis saat upload SO / clear-cache.
_SO_ORDER_STATS_CACHE_V61 = {'expires_at': None, 'delivered': None, 'returned': None}
_SO_ORDER_STATS_LOCK_V61 = threading.Lock()

def _invalidate_so_order_stats():
    with _SO_ORDER_STATS_LOCK_V61:
        _SO_ORDER_STATS_CACHE_V61['expires_at'] = None
        _SO_ORDER_STATS_CACHE_V61['delivered'] = None
        _SO_ORDER_STATS_CACHE_V61['returned'] = None

def so_order_stats_maps(force=False):
    """Map product_id -> (jumlah, total_amount) untuk Delivery Completed & Return."""
    now = datetime.utcnow()
    if not force:
        with _SO_ORDER_STATS_LOCK_V61:
            if (_SO_ORDER_STATS_CACHE_V61['delivered'] is not None
                    and _SO_ORDER_STATS_CACHE_V61['expires_at']
                    and _SO_ORDER_STATS_CACHE_V61['expires_at'] > now):
                return _SO_ORDER_STATS_CACHE_V61['delivered'], _SO_ORDER_STATS_CACHE_V61['returned']
    def _build(status_filter):
        # V63.20: Total Amount wajib IDR — baris non-IDR dikonversi dulu
        # (kolom purchasing_amount_idr / kurs cache). Dulu raw
        # purchasing_amount dijumlah mentah -> USD/EUR tercampur IDR.
        from types import SimpleNamespace as _NS
        m = {}
        rows = db.session.query(
            SOData.product_id, SOData.purchasing_amount, SOData.purchasing_price, SOData.so_qty,
            SOData.purchasing_currency, SOData.purchasing_amount_idr, SOData.so_create_date,
        ).filter(status_filter, SOData.product_id.isnot(None)).all()
        for pid, pamt, pprice, qty, pcur, pidr, sdate in rows:
            cp = clean_product_id(pid)
            if not cp: continue
            _row = _NS(purchasing_amount=pamt, purchasing_price=pprice, so_qty=qty,
                       purchasing_currency=pcur, purchasing_amount_idr=pidr, so_create_date=sdate)
            amt = purchase_amount_idr_for_margin(_row)
            cur = m.get(cp, (0, 0.0))
            m[cp] = (cur[0] + 1, cur[1] + float(amt or 0))
        return m
    delivered = _build(SOData.so_status == 'Delivery Completed')
    returned = _build(SOData.so_status.ilike('%return%'))
    # V63.27.15: old finalized rows may have moved to compact history. Merge
    # their product-level counts/amounts so Order Freq remains all-time.
    try:
        hist_rows = db.session.query(
            SOHistoryLite.product_id, SOHistoryLite.so_status,
            func.count(SOHistoryLite.id), func.coalesce(func.sum(SOHistoryLite.purchase_amount_idr), 0.0)
        ).filter(SOHistoryLite.product_id.isnot(None), SOHistoryLite.product_id != '').group_by(
            SOHistoryLite.product_id, SOHistoryLite.so_status
        ).all()
        for pid, status, cnt, amt in hist_rows:
            cp = clean_product_id(pid)
            if not cp: continue
            target = delivered if clean(status) == 'Delivery Completed' else (returned if 'return' in clean(status).lower() else None)
            if target is None: continue
            cur = target.get(cp, (0, 0.0))
            target[cp] = (cur[0] + int(cnt or 0), cur[1] + float(amt or 0))
    except Exception as _hist_order_exc:
        try: print(f'[history-lite] order stats merge skipped: {_hist_order_exc}', flush=True)
        except Exception: pass
    with _SO_ORDER_STATS_LOCK_V61:
        _SO_ORDER_STATS_CACHE_V61['delivered'] = delivered
        _SO_ORDER_STATS_CACHE_V61['returned'] = returned
        _SO_ORDER_STATS_CACHE_V61['expires_at'] = now + timedelta(seconds=120)
    return delivered, returned

def is_purchase_valid(s):
    """Margin is only valid when purchase price/amount is present AND positive.
    Empty, zero, or negative purchase → margin = None (invalid for KPIs).
    Used across the entire dashboard to keep margin KPIs accurate."""
    try:
        return raw_purchase_amount(s) > 0
    except Exception:
        return False

def purchase_price_idr(s):
    """Convert purchasing_price to IDR using cached exchange rates.
    If currency is already IDR (or empty), return as-is.
    If USD/EUR, convert using the rate for the SO create date.
    Returns 0 if no exchange rate is available (cache_only)."""
    price = float(s.purchasing_price or 0)
    if price <= 0: return 0.0
    cur = (s.purchasing_currency or 'IDR').strip().upper()
    if cur in ('IDR', ''): return price
    if cur in _FX_SUPPORTED_CURRENCIES:
        rate = get_currency_to_idr(cur, s.so_create_date, cache_only=True)
        return price * rate if rate else 0.0
    return price  # unknown currency — return as-is

def purchase_amount_idr_for_margin(s):
    """Purchase amount in IDR, used for ALL margin calculations.
    Priority:
    1. purchasing_amount_idr (cached column) if present
    2. Convert raw_purchase_amount to IDR using cached rates
    If currency is IDR → use raw amount directly.
    Returns 0.0 if conversion not possible (no rate cached)."""
    cached = getattr(s, 'purchasing_amount_idr', None)
    if cached is not None and cached > 0: return float(cached)
    raw = raw_purchase_amount(s)
    if raw <= 0: return 0.0
    cur = (s.purchasing_currency or 'IDR').strip().upper()
    if cur in ('IDR', ''): return raw
    if cur in _FX_SUPPORTED_CURRENCIES:
        rate = get_currency_to_idr(cur, s.so_create_date, cache_only=True)
        return raw * rate if rate else 0.0
    return raw  # unknown currency — return as-is

def purchase_amount_idr(s, allow_persist=False):
    cached = getattr(s, 'purchasing_amount_idr', None)
    cur = (s.purchasing_currency or 'IDR').strip().upper()
    if cached is not None: return float(cached)
    raw = raw_purchase_amount(s)
    if cur in ('IDR', ''): return raw
    if not allow_persist: return 0.0
    converted = convert_to_idr(raw, s.purchasing_currency, s.so_create_date, cache_only=True)
    # V63.14 ANTI-RACUN: jangan pernah menulis 0/None ke kolom cache. Dulu 0.0
    # ikut tersimpan saat kurs belum tersedia -> baris tidak pernah dianggap
    # "missing" lagi -> PO Amount terkunci 0 permanen (chart Summary bantet)
    # walau kurs akhirnya berhasil di-fetch.
    if converted and converted > 0:
        s.purchasing_amount_idr = converted
        s.purchasing_amount_idr_cached_at = datetime.utcnow()
    return converted

def dashboard_purchase_sql_expr():
    currency_expr = func.upper(func.trim(func.coalesce(SOData.purchasing_currency, '')))
    raw_purchase_expr = case(
        (func.coalesce(SOData.purchasing_amount, 0) != 0, func.coalesce(SOData.purchasing_amount, 0)),
        else_=func.coalesce(SOData.purchasing_price, 0) * func.coalesce(SOData.so_qty, 0),
    )
    # V63.20: kolom cache idr hanya boleh dipakai bila > 0 — baris korban
    # racun 0.0 (era pra-V63.14) tidak boleh menenggelamkan PO Amount; baris
    # IDR jatuh ke raw. SEMUA penjumlahan PO Amount wajib IDR.
    return case(
        (db.and_(SOData.purchasing_amount_idr.isnot(None), SOData.purchasing_amount_idr != 0), SOData.purchasing_amount_idr),
        (currency_expr.in_(['', 'IDR']), raw_purchase_expr),
        else_=0.0,
    )

def ensure_purchase_amount_idr_cache(rows, fetch_missing=False):
    if not fetch_missing: return 0
    # V63.14: baris dengan cache 0.0 (korban racun versi lama) ikut dianggap missing
    missing = [s for s in rows if (getattr(s, 'purchasing_amount_idr', None) is None or float(getattr(s, 'purchasing_amount_idr', None) or 0) == 0) and (s.purchasing_currency or '').strip().upper() in _FX_SUPPORTED_CURRENCIES and raw_purchase_amount(s) > 0]
    if not missing: return 0
    prefetch_convertible_exchange_rates(missing, fetch_missing=True)
    for s in missing: purchase_amount_idr(s, allow_persist=True)
    try: db.session.commit()
    except Exception: db.session.rollback(); raise
    return len(missing)

# ── V63.14: self-heal backfill konversi kurs utk dashboard Summary ───────────
# Jalur light /api/completed/summary memberi 0 utk baris EUR/USD yang kolom
# purchasing_amount_idr-nya NULL (cache konversi hilang pasca-recovery DB) ->
# bar PO Amount di chart "Monthly Trend Delivery Complete" jatuh -> chart
# terlihat bantet/berubah bentuk. Kini begitu jalur light mendeteksi baris
# belum terkonversi, satu thread background (single-flight + cooldown) mengisi
# kurs (via proxy, V63.12), menulis purchasing_amount_idr ke DB, lalu menghapus
# cache summary -> chart pulih sendiri dalam beberapa request tanpa memblokir.
import time as _t6314
_FX_BACKFILL_STATE = {'running': False, 'last_done': 0.0}
_FX_BACKFILL_LOCK = threading.Lock()

def _spawn_fx_backfill_completed(min_interval=120.0):
    now_ts = _t6314.time()
    with _FX_BACKFILL_LOCK:
        if _FX_BACKFILL_STATE['running']: return False
        if now_ts - _FX_BACKFILL_STATE['last_done'] < min_interval: return False
        _FX_BACKFILL_STATE['running'] = True
    def _fx_backfill_worker():
        converted = 0
        try:
            with app.app_context():
                cur_expr = func.upper(func.trim(func.coalesce(SOData.purchasing_currency, '')))
                has_raw = db.or_(db.and_(SOData.purchasing_amount.isnot(None), SOData.purchasing_amount != 0),
                                 db.and_(SOData.purchasing_price.isnot(None), SOData.purchasing_price != 0, SOData.so_qty.isnot(None), SOData.so_qty != 0))
                rows = db.session.query(SOData).filter(
                    db.or_(SOData.purchasing_amount_idr.is_(None), SOData.purchasing_amount_idr == 0),
                    cur_expr.in_(list(_FX_SUPPORTED_CURRENCIES)),
                    has_raw,
                ).order_by(SOData.so_create_date.desc().nullslast() if hasattr(SOData.so_create_date.desc(), 'nullslast') else SOData.so_create_date.desc()).limit(5000).all()
                if rows:
                    before_missing = len(rows)
                    ensure_purchase_amount_idr_cache(rows, fetch_missing=True)
                    try:
                        # hitung nyata (bukan len(missing)) agar cache hanya dihapus
                        # bila memang ada baris yang baru terkonversi
                        cur_expr2 = func.upper(func.trim(func.coalesce(SOData.purchasing_currency, '')))
                        after_missing = db.session.query(SOData.id).filter(
                            db.or_(SOData.purchasing_amount_idr.is_(None), SOData.purchasing_amount_idr == 0),
                            cur_expr2.in_(list(_FX_SUPPORTED_CURRENCIES))).count()
                        converted = max(before_missing - int(after_missing or 0), 0)
                    except Exception:
                        converted = before_missing
                try:
                    db.session.rollback()
                except Exception:
                    pass
        except Exception as exc:
            try: print(f'[fx-backfill] gagal: {exc}', flush=True)
            except Exception: pass
        finally:
            try:
                if converted:
                    with _COMPLETED_CACHE_LOCK:
                        _COMPLETED_SUMMARY_CACHE.clear()
                    try:
                        clear_runtime_caches()
                    except Exception:
                        pass
                    try: print(f'[fx-backfill] {converted} baris baru terkonversi; cache summary dihapus', flush=True)
                    except Exception: pass
            except Exception:
                pass
            with _FX_BACKFILL_LOCK:
                _FX_BACKFILL_STATE['running'] = False
                _FX_BACKFILL_STATE['last_done'] = _t6314.time()
    threading.Thread(target=_fx_backfill_worker, daemon=True, name='fx-backfill').start()
    return True


def _ensure_extra_columns():
    is_sqlite = 'sqlite' in app.config['SQLALCHEMY_DATABASE_URI']
    def existing_columns(table_name):
        try:
            if is_sqlite:
                result = db.session.execute(text(f"PRAGMA table_info({table_name})"))
                return {row[1].lower() for row in result}
            result = db.session.execute(text("SELECT column_name FROM information_schema.columns WHERE table_name = '{}'".format(table_name)))
            return {row[0].lower() for row in result}
        except Exception: return set()
    migration_plan = {
        'so_data': [('specification', 'TEXT'), ('product_id', 'VARCHAR(100)'), ('vendor_id', 'VARCHAR(100)'), ('client_id', 'VARCHAR(100)'), ('manufacturer_name', 'VARCHAR(300)'), ('purchasing_currency', 'VARCHAR(10)'), ('purchasing_amount_idr', 'DOUBLE PRECISION'), ('purchasing_amount_idr_cached_at', 'TIMESTAMP'), ('pic_name', 'VARCHAR(100)'), ('updated_at', 'TIMESTAMP'),
            # V62 SETTLEMENT: kolom dari Excel Search Client Odr
            ('settlement_status', 'VARCHAR(100)'), ('purchasing_settlement_check', 'VARCHAR(100)'), ('purchasing_settlement_month', 'VARCHAR(20)'),
            ('sales_settlement_status', 'VARCHAR(100)'), ('sales_settlement_month', 'VARCHAR(20)'),
            ('shipping_trade_statement_number', 'VARCHAR(100)'), ('exception_process', 'VARCHAR(255)'),
            ('original_so_number', 'VARCHAR(100)'), ('original_so_item', 'VARCHAR(100)'), ('operation_unit_id', 'VARCHAR(100)'),
            ('return_qty', 'DOUBLE PRECISION'), ('po_confirm_date', 'DATE'), ('delivery_complete_date', 'DATE')],
        # V60z37: Added new fields for Prod. Reg. Status sheet.
        # Old vendor fields (vendor_name, vendor_id, prod_price, curr) are NOT removed from DB
        # (SQLite doesn't support DROP COLUMN easily), but they are no longer used in code.
        # Existing rows stay intact; new nullable columns are populated on later imports.
        'item_registration': [('req_date', 'DATE'), ('existing_owner', 'VARCHAR(200)'), ('client_id', 'VARCHAR(100)'), ('operation_unit_name', 'VARCHAR(300)'), ('bid_except_type', 'VARCHAR(255)'), ('category_id', 'VARCHAR(100)'), ('pic_name', 'VARCHAR(200)'), ('product_status', 'VARCHAR(100)'), ('hub_handling_check', 'VARCHAR(100)'), ('tax_type', 'VARCHAR(50)'), ('registration_date', 'DATE'), ('remarks', 'TEXT'), ('vendor_id', 'VARCHAR(100)'), ('updated_at', 'TIMESTAMP'),
            # V60z37: New fields from Prod. Reg. Status sheet
            ('req_owner', 'VARCHAR(200)'), ('req_by', 'VARCHAR(300)'), ('sales_pic_name', 'VARCHAR(300)'), ('pre_reg_recomm_id', 'VARCHAR(100)'), ('stock_no', 'VARCHAR(100)'),
        ],
        'product_id_db': [('specification', 'TEXT'), ('manufacturer_name', 'VARCHAR(255)'), ('vendor_name', 'VARCHAR(300)'), ('order_unit', 'VARCHAR(50)'), ('product_status', 'VARCHAR(100)'), ('hub_handling_check', 'VARCHAR(100)'), ('tax_type', 'VARCHAR(100)'), ('registration_date', 'DATE')],
        'import_vendor': [('origin', 'VARCHAR(100)'), ('top', 'VARCHAR(50)'), ('non_ski', 'VARCHAR(50)'), ('brand_handling', 'TEXT')],
        # V63.27.45: existing Access Monitor DBs get the metadata-only details column automatically.
        'access_activity': [('details', 'TEXT')],
        # V63.27.65: persistent browser identity recovery. Existing devices get
        # a recovery token lazily on their next successful browser visit.
        'access_device': [('recovery_hash', 'VARCHAR(64)')],
    }
    for table_name, columns in migration_plan.items():
        cols = existing_columns(table_name)
        for col_name, col_type in columns:
            if col_name.lower() not in cols:
                try:
                    db.session.execute(text(f"ALTER TABLE {table_name} ADD COLUMN {col_name} {col_type}"))
                    db.session.commit()
                except Exception: db.session.rollback()
    # Preserve imported Item Registration rows. Added columns are nullable, so
    # existing data remains readable and can be refreshed through normal import.

def _ensure_performance_indexes():
    # Catatan: kolom yang dideklarasikan index=True di model (so_number, req_no, existing_owner)
    # sudah otomatis di-index SQLAlchemy sebagai ix_<tabel>_<kolom> — JANGAN buat duplikatnya di sini.
    # Duplikat lama (idx_so_number, idx_item_reg_req_no, idx_item_reg_owner) sudah dihapus;
    # bersihkan DB lama dengan: python3 cleanup_duplicate_indexes.py --apply
    statements = [
        "CREATE INDEX IF NOT EXISTS idx_so_status_date ON so_data (so_status, so_create_date)",
        "CREATE INDEX IF NOT EXISTS idx_so_op_unit ON so_data (operation_unit_name)",
        "CREATE INDEX IF NOT EXISTS idx_so_pic_name ON so_data (pic_name)",
        "CREATE INDEX IF NOT EXISTS idx_so_vendor_name ON so_data (vendor_name)",
        "CREATE INDEX IF NOT EXISTS idx_so_item ON so_data (so_item)",
        "CREATE INDEX IF NOT EXISTS idx_so_product_id ON so_data (product_id)",
        "CREATE INDEX IF NOT EXISTS idx_so_customer_po ON so_data (customer_po_number)",
        "CREATE INDEX IF NOT EXISTS idx_so_settlement_status ON so_data (settlement_status)",
        "CREATE INDEX IF NOT EXISTS idx_so_po_confirm_date ON so_data (po_confirm_date)",
        "CREATE INDEX IF NOT EXISTS idx_so_delivery_complete ON so_data (delivery_complete_date)",
        # V63.27.11: tiga composite index Settlement V63.27.9 dihapus.
        # Cache filter + index single-column yang sudah ada cukup; tiga index ini
        # menambah puluhan MB pada DB PythonAnywhere tanpa manfaat sebanding.
        "CREATE INDEX IF NOT EXISTS idx_upload_log_type_date ON upload_log (file_type, uploaded_at)",
        "CREATE INDEX IF NOT EXISTS idx_item_reg_proc_client ON item_registration (proc_status, client_name)",
        "CREATE INDEX IF NOT EXISTS idx_item_reg_pic ON item_registration (pic)",
        "CREATE INDEX IF NOT EXISTS idx_item_reg_mfr ON item_registration (mfr_name)",
        "CREATE INDEX IF NOT EXISTS idx_product_status_unit ON product_id_db (product_status, order_unit)",
    ]
    for stmt in statements:
        try: db.session.execute(text(stmt))
        except Exception: db.session.rollback()
    try: db.session.commit()
    except Exception: db.session.rollback()

def _v6321_drop_dead_columns():
    """V63.21: buang kolom DB yang tidak dipakai dashboard (hemat storage).

    - so_data.delivery_possible_date        (tidak pernah tampil di UI)
    - item_registration.batch_grp_no        (tidak pernah tampil di UI)
    - item_registration.product_registry_pic (dihapus user: tidak dipakai)
    - product_id_db.product_registry_pic     (dihapus user: tidak dipakai)
    Idempoten + best-effort: SQLite lawas yang menolak DROP COLUMN hanya
    melewatkan kolom tsb (tidak lagi menerima data baru dari upload).
    """
    targets = [
        ('so_data', 'delivery_possible_date'),
        ('item_registration', 'batch_grp_no'),
        ('item_registration', 'product_registry_pic'),
        ('product_id_db', 'product_registry_pic'),
    ]
    try:
        insp = sa_inspect(db.engine)
    except Exception as exc:
        print(f'[v6321] drop-columns skip (inspector): {exc}', flush=True)
        return
    dropped = []
    for tbl, col in targets:
        try:
            if not insp.has_table(tbl): continue
            cols = [c['name'] for c in insp.get_columns(tbl)]
            if col not in cols: continue
            db.session.execute(text(f'ALTER TABLE {tbl} DROP COLUMN {col}'))
            db.session.commit()
            dropped.append(f'{tbl}.{col}')
        except Exception as exc:
            db.session.rollback()
            try:
                # varian Postgres: IF EXISTS utk kondisi race antar-worker
                db.session.execute(text(f'ALTER TABLE {tbl} DROP COLUMN IF EXISTS {col}'))
                db.session.commit()
                dropped.append(f'{tbl}.{col}')
            except Exception as exc2:
                db.session.rollback()
                print(f'[v6321] skip drop {tbl}.{col}: {exc2}', flush=True)
    if dropped:
        print(f'[v6321] dropped unused columns: {", ".join(dropped)}', flush=True)

def _v632711_remove_settlement_composite_indexes():
    """Hapus 3 index composite V63.27.9 yang terlalu boros storage.

    DROP INDEX membuat halamannya menjadi freelist dan langsung dapat dipakai
    ulang SQLite. Ukuran file fisik baru benar-benar turun setelah VACUUM;
    cleanup_disk.py --apply --vacuum melakukan langkah itu dengan eksplisit.
    """
    names = (
        'idx_so_status_delivery_complete',
        'idx_so_status_op_unit',
        'idx_so_status_vendor',
    )
    removed = []
    logical_mb = 0.0
    try:
        uri = app.config.get('SQLALCHEMY_DATABASE_URI', '') or ''
        if 'sqlite' not in uri:
            return removed, logical_mb
        # dbstat memberi ukuran index sebelum di-drop (best effort).
        try:
            import sqlite3 as _sq3i
            dbp = uri.replace('sqlite:///', '', 1)
            con = _sq3i.connect(dbp, timeout=10)
            try:
                for name in names:
                    try:
                        b = con.execute('SELECT COALESCE(SUM(pgsize),0) FROM dbstat WHERE name=?', (name,)).fetchone()[0] or 0
                        logical_mb += float(b) / 1048576.0
                    except Exception:
                        pass
            finally:
                con.close()
        except Exception:
            pass
        for name in names:
            try:
                exists = db.session.execute(text(
                    "SELECT 1 FROM sqlite_master WHERE type='index' AND name=:n"
                ), {'n': name}).first()
                if exists:
                    db.session.execute(text(f'DROP INDEX IF EXISTS {name}'))
                    removed.append(name)
            except Exception:
                db.session.rollback()
        try:
            db.session.commit()
        except Exception:
            db.session.rollback()
        if removed:
            print('[v632711] removed oversized Settlement indexes: ' + ', '.join(removed) +
                  (f' (~{logical_mb:.1f} MB logical)' if logical_mb else ''), flush=True)
    except Exception as exc:
        try: db.session.rollback()
        except Exception: pass
        print(f'[v632711] index reclaim skipped: {exc}', flush=True)
    return removed, logical_mb

