def item_registration_kpi_status_expr(): return func.lower(func.trim(func.coalesce(ItemRegistration.proc_status, '')))
def item_registration_existing_owner_expr(): return func.lower(func.trim(func.coalesce(ItemRegistration.existing_owner, '')))
def item_registration_stock_no_expr(): return func.lower(func.trim(func.coalesce(ItemRegistration.stock_no, '')))

def apply_item_registration_kpi_status_filter(query):
    # V60z37: KPI status filter now based on existing_owner column:
    #   - Show items where existing_owner contains 'pur. pic' (normal PURCHASE/individual PIC KPI)
    #   - OR existing_owner is empty/other (fall through to Master PIC resolution)
    # Exclude:
    #   - ITEM_REG_KPI_EXCLUDED_STATUSES (regardless of existing_owner)
    #   - existing_owner contains 'sales pic' (counted in KPI Sales instead)
    #   - existing_owner contains 'db part' (counted in KPI DB instead)
    status_expr = item_registration_kpi_status_expr()
    owner_expr = item_registration_existing_owner_expr()
    not_excluded = ~status_expr.in_(list(ITEM_REG_KPI_EXCLUDED_STATUSES))
    not_sales_owner = ~owner_expr.like('%sales pic%')
    not_db_owner = ~owner_expr.like('%db part%')
    return query.filter(not_excluded, not_sales_owner, not_db_owner)

def apply_item_registration_visible_status_filter(query):
    # V60z37: Show all items in table (no status-based hiding except TERMINATED)
    return query

def refresh_item_registration_mappings():
    rows = ItemRegistration.query.all()
    changed = False
    for row in rows:
        category = source_category_level1(row.category)
        normalized_cat_id = normalize_category_id(row.category_id)
        if row.category_id != normalized_cat_id: row.category_id = normalized_cat_id; changed = True
        if row.category != category: row.category = category; changed = True
        pic = resolve_pic_with_overrides(
            category_id=normalized_cat_id, category_name=category,
            client_id=row.client_id, vendor_id=None, bid_except_type=row.bid_except_type,
        ) or ''
        if row.pic != pic: row.pic = pic; changed = True
    if changed: db.session.commit()

