@app.route('/api/debug/smro-columns', methods=['POST'])
def debug_smro_columns():
    try:
        if 'file' not in request.files: return jsonify({'error': 'No file uploaded'}), 400
        file = request.files['file']
        df = pd.read_excel(file, engine='openpyxl', nrows=3)
        df.columns = [str(c).strip() for c in df.columns]
        all_cols = df.columns.tolist()
        detected = {
            'col_so_item': find_column(df, ['SO Item', 'SO Item No', 'SO Line', 'Item No', 'Line']),
            'col_so_number': find_column(df, ['SO Number','SO No','SO No.','SO','Sales Order Number','No SO','Nomor SO']),
            'col_spec': find_column(df, ['Specification','Spec','Specifications','Product Specification','Material Description','Material Desc','Short Text']),
            'col_pid': find_column(df, ['Product ID','Product Id','Product Code','Material','Material No','Material Number','Material Code','SKU','Article','Article Number']),
            'col_prod': find_column(df, ['Product Name','Item Name','Description','Product']),
            'col_status': find_column(df, ['SO Status','Status','Order Status']),
            'col_vendor': find_column(df, ['Vendor Name','Vendor','Supplier']),
            'col_sodate': find_column(df, ['SO Create Date','Order Date','SO Date','Create Date']),
        }
        col_primary = detected['col_so_item'] or detected['col_so_number']
        missing_critical = []
        if not col_primary: missing_critical.append('col_so_item / col_so_number')
        for k in ('col_spec', 'col_pid'):
            if not detected[k]: missing_critical.append(k)
        return jsonify({
            'total_columns': len(all_cols), 'all_columns': all_cols, 'detected': detected,
            'primary_key_column': col_primary, 'missing_critical': missing_critical,
            'diagnosis': ('col_spec and/or col_pid NOT detected — column names in this file do not match any known alias. Check "all_columns" list and update backend aliases.' if missing_critical else 'SO Item key, col_spec, and col_pid all detected — upload should work correctly.')
        })
    except Exception as e: return jsonify({'error': str(e)}), 500

@app.route('/api/data/aging', methods=['GET'])
def get_aging_data():
    try:
        cache_key = runtime_cache_key('aging')
        cached = runtime_cache_get_swr(cache_key, request.full_path)
        if cached is not None: return jsonify(cached)
        today = date.today()
        hidden_so = get_hidden_so_items()
        clients = selected_clients()
        pics = selected_pics()
        date_year, date_from, date_to = parse_so_date_args()
        vendors = {}
        # V60s: Aging includes ALL statuses (removed open_so_filter)
        q = db.session.query(SOData).filter(so_countable_sql_filter())
        q = apply_so_client_filter(q, clients)
        q = apply_so_pic_filter(q, pics)
        q = apply_so_create_date_filter(q, date_year, date_from, date_to)
        aging_fields = (SOData.so_number, SOData.so_item, SOData.vendor_name, SOData.customer_po_number, SOData.delivery_memo, SOData.so_create_date, SOData.sales_amount)
        for s in q.options(load_only(*aging_fields)).all():
            if s.so_item in hidden_so or s.so_number in hidden_so: continue
            if not so_is_countable(s.so_item, customer_po_number=s.customer_po_number, delivery_memo=s.delivery_memo): continue
            v = s.vendor_name or 'Unknown'
            if v not in vendors: vendors[v] = {'vendor': v, 'less_30': 0, 'days_30_90': 0, 'days_90_180': 0, 'more_180': 0, 'total_open': 0, 'sales_amount': 0.0}
            age = days_since(s.so_create_date, today) if s.so_create_date else None
            if age is None: vendors[v]['more_180'] += 1
            elif age < 30: vendors[v]['less_30'] += 1
            elif age < 90: vendors[v]['days_30_90'] += 1
            elif age < 180: vendors[v]['days_90_180'] += 1
            else: vendors[v]['more_180'] += 1
            vendors[v]['total_open'] += 1
            vendors[v]['sales_amount'] += float(s.sales_amount or 0)
        payload = sorted(vendors.values(), key=lambda x: x['total_open'], reverse=True)
        runtime_cache_set(cache_key, payload, ttl_seconds=600)
        return jsonify(payload)
    except Exception as e:
        import traceback; traceback.print_exc()
        return jsonify({'error': str(e)}), 500

@app.route('/api/data/pending-settlement', methods=['GET'])
def get_pending_settlement_data():
    """V63.20: agregasi section "Pending Settlement" di page Summary.

    - kpi: aging buckets (0-30/30-90/90-180/180+ = hari sejak Delivery
      Complete, hanya settlement_status belum complete — konvensi V63.6
      sama dgn kolom Aging halaman Settlement) + total + amount IDR.
    - heatmap: baris op unit x kolom bulan-tahun (so_create_date), isi =
      jumlah settlement belum complete (persebaran utk heatmap).
    - pie: sales settlement belum / purchasing settlement belum /
      keduanya belum (count + amount IDR).
    - monthly: per bulan — count pending settlement + Sales Amount.
    - combo: per op unit — PO pending settlement (purchasing belum, count
      nomor PO unik, konvensi V62.1) + amount (PO Amount IDR, non-IDR
      dikonversi). Semua menghormati filter global (client/pic/date).
    """
    try:
        cache_key = runtime_cache_key('pending_settlement_v13')
        cached = runtime_cache_get_swr(cache_key, request.full_path)
        if cached is not None: return jsonify(cached)
        clients = selected_clients()
        pics = selected_pics()
        date_year, date_from, date_to = parse_so_date_args()
        is_sqlite = 'sqlite' in app.config.get('SQLALCHEMY_DATABASE_URI', '')
        rows = _settlement_base_q(clients, pics, date_year, date_from, date_to,
                                  is_sqlite=is_sqlite).options(load_only(*SETTLEMENT_LOAD_FIELDS)).all()
        prefetch_convertible_exchange_rates(rows, fetch_missing=False)

        def _pend(v): return clean(v) not in SETTLEMENT_COMPLETE_PHRASES
        pending = [s for s in rows if _pend(s.settlement_status)]
        purch_not = [s for s in pending if _pend(s.purchasing_settlement_check)]
        sales_not = [s for s in pending if _pend(s.sales_settlement_status)]

        kpi = {'less_30': 0, 'days_30_90': 0, 'days_90_180': 0, 'more_180': 0, 'no_date': 0}
        for s in pending:
            d = days_since(s.delivery_complete_date) if s.delivery_complete_date else None
            if d is None: kpi['no_date'] += 1
            else:
                lb = get_aging_label(d)
                if lb == '0-30': kpi['less_30'] += 1
                elif lb == '30-90': kpi['days_30_90'] += 1
                elif lb == '90-180': kpi['days_90_180'] += 1
                else: kpi['more_180'] += 1
        kpi['total_pending'] = len(pending)
        kpi['pending_amount'] = round(sum(purchase_amount_idr_for_margin(s) for s in pending), 2)
        # V63.27.13: Sales Amount total utk line chart Monthly Pending Settlements
        # (samakan metrik dengan Monthly Pending Deliveries).
        kpi['pending_sales_amount'] = round(sum(float(s.sales_amount or 0) for s in pending), 2)

        # V63.27.13: monthly combo Pending Settlement — pola sama dengan
        # Monthly Pending Deliveries: bar=count, line=Sales Amount.
        monthly_acc = {}
        for s in pending:
            if not s.so_create_date:
                continue
            mo = s.so_create_date.strftime('%Y-%m')
            mr = monthly_acc.setdefault(mo, {'so_count': 0, 'amount': 0.0})
            mr['so_count'] += 1
            mr['amount'] += float(s.sales_amount or 0)
        monthly = [
            {'month': mo, 'so_count': r['so_count'], 'amount': round(r['amount'], 2)}
            for mo, r in sorted(monthly_acc.items())
        ]

        months_set, by_unit = set(), {}
        for s in pending:
            u = (s.operation_unit_name or '').strip() or 'Unknown'
            mo = s.so_create_date.strftime('%Y-%m') if s.so_create_date else 'Unknown'
            months_set.add(mo)
            r = by_unit.setdefault(u, {'op_unit': u, 'cells': {}, 'amount_cells': {}, 'total': 0, 'amount': 0.0})
            r['cells'][mo] = r['cells'].get(mo, 0) + 1
            # V63.27.2: sales amount per (op unit, bulan) utk toggle Qty/Amount heatmap PS
            r['amount_cells'][mo] = round(r['amount_cells'].get(mo, 0.0) + float(s.sales_amount or 0), 2)
            r['total'] += 1
            r['amount'] += purchase_amount_idr_for_margin(s)
        months = sorted(m for m in months_set if m != 'Unknown')
        if 'Unknown' in months_set: months.append('Unknown')
        if len(months) > 14: months = months[-14:]
        hm_rows = sorted(by_unit.values(), key=lambda r: -r['total'])
        for r in hm_rows: r['amount'] = round(r['amount'], 2)
        heatmap = {'months': months, 'rows': hm_rows}

        both = [s for s in pending if _pend(s.purchasing_settlement_check) and _pend(s.sales_settlement_status)]
        sales_only = [s for s in sales_not if not _pend(s.purchasing_settlement_check)]
        purch_only = [s for s in purch_not if not _pend(s.sales_settlement_status)]
        pie = {
            'sales_only': {'count': len(sales_only),
                           'amount': round(sum(float(s.sales_amount or 0) for s in sales_only), 2)},
            'purch_only': {'count': len(purch_only),
                           'amount': round(sum(purchase_amount_idr_for_margin(s) for s in purch_only), 2)},
            'both': {'count': len(both),
                     'amount': round(sum(purchase_amount_idr_for_margin(s) for s in both), 2)},
        }

        combo_acc = {}
        for s in purch_not:
            u = (s.operation_unit_name or '').strip() or 'Unknown'
            r = combo_acc.setdefault(u, {'pos': set(), 'amount': 0.0, 'rows': 0})
            po = clean(s.matched_po_number)
            if po: r['pos'].add(po)
            r['amount'] += purchase_amount_idr_for_margin(s)
            r['rows'] += 1
        combo_list = [{'op_unit': u, 'po_count': len(r['pos']), 'row_count': r['rows'],
                       'amount': round(r['amount'], 2)} for u, r in combo_acc.items()]
        combo_list.sort(key=lambda x: (-x['amount'], x['op_unit']))
        # V63.21: judul widget jadi "Top 10 PO Pending Settlement per Op Unit"
        # — backend kirim maksimal 10 op unit teratas (by amount IDR).
        combo_list = combo_list[:10]

        payload = {'kpi': kpi, 'heatmap': heatmap, 'pie': pie, 'combo': combo_list,
                   'monthly': monthly,
                   'generated_at': utc_isoformat(datetime.utcnow())}
        runtime_cache_set(cache_key, payload, ttl_seconds=60)
        return jsonify(payload)
    except Exception as e:
        import traceback; traceback.print_exc()
        return jsonify({'error': str(e)}), 500


@app.route('/api/data/pending-settlement-detail', methods=['GET'])
def get_pending_settlement_detail():
    """V63.21: detail baris utk klik heatmap "Pending Settlement Distribution".

    Perilaku sama dgn heatmap Pending Delivery (klik sel -> popup detail baris).
    Params kombinasi bebas:
      - sel            : op_unit=.. & month=YYYY-MM
      - total per baris: op_unit=.. (semua bulan)
      - total per kolom: month=YYYY-MM (semua op unit)
      - grand total    : tanpa keduanya
    Selalu hanya settlement belum complete + filter global (client/pic/date).
    """
    try:
        cache_key = runtime_cache_key('pending_settlement_detail')
        cached = runtime_cache_get_swr(cache_key, request.full_path)
        if cached is not None: return jsonify(cached)
        op_unit = (request.args.get('op_unit') or '').strip()
        month = (request.args.get('month') or '').strip()
        clients = selected_clients()
        pics = selected_pics()
        date_year, date_from, date_to = parse_so_date_args()
        is_sqlite = 'sqlite' in app.config.get('SQLALCHEMY_DATABASE_URI', '')
        # V63.27.2: filter didorong ke level SQL (arsitektur yang sama dengan
        # popup Pending Delivery /api/dashboard/status-detail) sehingga popup
        # terbuka INSTAN — sebelumnya SEMUA baris settlement dimuat lalu
        # difilter di Python (puluhan ribu baris = popup beberapa detik).
        q = _settlement_base_q(clients, pics, date_year, date_from, date_to,
                               is_sqlite=is_sqlite)
        _ss = func.trim(func.coalesce(SOData.settlement_status, ''))
        q = q.filter(~_ss.in_(list(SETTLEMENT_COMPLETE_PHRASES)))
        _ou = func.trim(func.coalesce(SOData.operation_unit_name, ''))
        if op_unit:
            if op_unit == 'Unknown':
                q = q.filter(_ou == '')          # 'Unknown' = op unit kosong
            else:
                q = q.filter(_ou == op_unit)
        if month:
            _mo = func.strftime('%Y-%m', SOData.so_create_date) if is_sqlite else \
                func.to_char(func.date_trunc('month', SOData.so_create_date), 'YYYY-MM')
            if month == 'Unknown':
                q = q.filter(SOData.so_create_date.is_(None))
            else:
                q = q.filter(_mo == month)
        rows = q.options(load_only(*SETTLEMENT_LOAD_FIELDS)).all()

        def _pend(v): return clean(v) not in SETTLEMENT_COMPLETE_PHRASES
        result = []
        for s in rows:
            if not _pend(s.settlement_status): continue
            u = (s.operation_unit_name or '').strip() or 'Unknown'
            if op_unit and u != op_unit: continue
            if month:
                mo = s.so_create_date.strftime('%Y-%m') if s.so_create_date else 'Unknown'
                if mo != month: continue
            result.append({
                'so_item': s.so_item, 'so_number': s.so_number, 'so_status': s.so_status,
                'pic_name': 'SALES' if clean(s.so_status) in SALES_STATUSES else canonical_pending_pic(s.pic_name, s.operation_unit_name),
                'po_number': s.matched_po_number or '',
                'operation_unit_name': s.operation_unit_name, 'vendor_name': s.vendor_name,
                'product_name': s.product_name, 'so_qty': s.so_qty,
                'sales_price': s.sales_price, 'sales_amount': s.sales_amount,
                'purchase_amount_idr': purchase_amount_idr_for_margin(s),
                'settlement_status': s.settlement_status,
                'purchasing_settlement_check': s.purchasing_settlement_check,
                'sales_settlement_status': s.sales_settlement_status,
                'customer_po_number': s.customer_po_number, 'delivery_memo': s.delivery_memo,
                'so_create_date': s.so_create_date.isoformat() if s.so_create_date else None,
                'delivery_complete_date': s.delivery_complete_date.isoformat() if s.delivery_complete_date else None,
                'remarks': s.remarks,
            })
        result.sort(key=lambda r: (r.get('so_create_date') or '', r.get('so_item') or ''))
        payload = {'op_unit': op_unit or None, 'month': month or None,
                   'count': len(result), 'rows': result,
                   'generated_at': utc_isoformat(datetime.utcnow())}
        runtime_cache_set(cache_key, payload, ttl_seconds=60)
        return jsonify(payload)
    except Exception as e:
        import traceback; traceback.print_exc()
        return jsonify({'error': str(e)}), 500


