# ── V63.27.5 PERF: helper filter SQL (semantik persis versi Python) ─────────
_WS = ' \t\n\r\v\f'  # set karakter strip() Python (str.strip)

def _age_expr(col):
    """Usia hari kalender di SQL — sama dengan days_since(): selisih tanggal
    lokal server; NULL utk tanggal NULL/invalid."""
    return func.julianday(func.date('now', 'localtime')) - func.julianday(func.date(col))

def _aging_sql_clause(age, labels):
    """Kondisi SQL bucket Aging — semantik persis get_aging_label():
    0-30 = age<30 (termasuk negatif), 30-90, 90-180, dan
    180+ = age>=180 ATAU tanggal NULL (get_aging_label(None)='180+')."""
    conds = []
    for a in (labels or []):
        if a == '0-30':
            conds.append(age < 30)
        elif a == '30-90':
            conds.append(db.and_(age >= 30, age < 90))
        elif a == '90-180':
            conds.append(db.and_(age >= 90, age < 180))
        elif a == '180+':
            conds.append(db.or_(age.is_(None), age >= 180))
    return db.or_(*conds) if conds else None

def _sett_pend_sql(col):
    """clean(col) NOT IN SETTLEMENT_COMPLETE_PHRASES di level SQL
    (None / '' / spasi = belum complete — sama seperti clean())."""
    return db.or_(col.is_(None), func.trim(col, _WS).notin_(list(SETTLEMENT_COMPLETE_PHRASES)))

@app.route('/api/data/all-so', methods=['GET'])
def get_all_so():
    try:
        cache_key = runtime_cache_key('all_so')
        cached = runtime_cache_get_swr(cache_key, request.full_path)
        if cached is not None: return jsonify(cached)
        page = max(1, int(request.args.get('page', 1)))
        per_page = max(1, int(request.args.get('per_page', 25)))
        op_units = request.args.getlist('op_unit')
        vendors = request.args.getlist('vendor')
        manufacturers = request.args.getlist('manufacturer')
        statuses = request.args.getlist('status')
        aging_list = request.args.getlist('aging')
        so_items = request.args.getlist('so_item')
        pics = request.args.getlist('pic')
        kpi_pic = (request.args.get('kpi_pic') or '').strip()
        global_pics = request.args.getlist('global_pic')
        clients = selected_clients()
        margin_filter = request.args.get('margin_filter', 'all')
        sort_order = request.args.get('sort_order', 'oldest')
        # V60z: show_finished toggle — when 0 (default), HIDDEN_SO_STATUSES are
        # hidden from the table. When 1, all statuses are shown.
        show_finished = str(request.args.get('show_finished', '0')).lower() in ('1', 'true', 'yes')
        date_year, date_from, date_to = parse_so_date_args()

        # ── V63.27.5 PERF: KPI (COUNT/SUM/GROUP BY) dan paginasi (LIMIT/
        # OFFSET) didorong ke SQL — dulu .all() seluruh hasil dimuat sebagai
        # objek ORM per request (puluhan ribu baris = filter terasa lambat,
        # RSS naik). Aging ikut ke SQL dgn semantik get_aging_label().
        _aging_cond = _aging_sql_clause(_age_expr(SOData.so_create_date), aging_list)

        if show_finished:
            q = SOData.query.filter(so_countable_sql_filter())
        else:
            q = SOData.query.filter(so_countable_sql_filter(), ~SOData.so_status.in_(list(HIDDEN_SO_STATUSES)))
        q = apply_so_client_filter(q, clients)
        q = apply_so_pic_filter(q, global_pics)
        if op_units: q = q.filter(SOData.operation_unit_name.in_(op_units))
        if vendors: q = q.filter(SOData.vendor_name.in_(vendors))
        if manufacturers: q = q.filter(SOData.manufacturer_name.in_(manufacturers))
        if statuses: q = q.filter(SOData.so_status.in_(statuses))
        q = apply_so_search_filter(q, so_items)

        # V62.6: trade type filter (Import = purchasing currency non-IDR,
        # Local = IDR; empty purchasing_currency dianggap IDR).
        trade_type = (request.args.get('trade_type') or '').strip().lower()
        _purc_cur_expr = func.upper(func.trim(func.coalesce(SOData.purchasing_currency, '')))
        if trade_type == 'import':
            q = q.filter(_purc_cur_expr.notin_(('', 'IDR')))
        elif trade_type == 'local':
            q = q.filter(_purc_cur_expr.in_(('', 'IDR')))

        q = apply_so_create_date_filter(q, date_year, date_from, date_to)
        if _aging_cond is not None:
            q = q.filter(_aging_cond)

        # Push PIC filter into SQL when possible — avoids loading all SOs
        # into Python just to filter by pic_name. canonical_pending_pic()
        # is now `pic or 'Unassigned'`, so 'Unassigned' = empty/null pic.
        if pics:
            pic_set = set(pics)
            non_empty_pics = [p for p in pic_set if p and p != 'Unassigned']
            wants_unassigned = 'Unassigned' in pic_set or '(Empty)' in pic_set
            if non_empty_pics and wants_unassigned:
                q = q.filter(db.or_(SOData.pic_name.in_(non_empty_pics), SOData.pic_name.is_(None), SOData.pic_name == ''))
            elif non_empty_pics:
                q = q.filter(SOData.pic_name.in_(non_empty_pics))
            elif wants_unassigned:
                q = q.filter(db.or_(SOData.pic_name.is_(None), SOData.pic_name == ''))

        if kpi_pic and kpi_pic != 'Unassigned':
            # V60x: KPI click logic:
            # - kpi_pic='SALES' → show SOs with SALES_STATUSES
            # - kpi_pic='<regular PIC>' → show SOs for that PIC, excluding SALES_STATUSES
            #   (Delivery Completed already excluded from the main query).
            if kpi_pic == 'SALES':
                q = q.filter(SOData.so_status.in_(list(SALES_STATUSES)))
            else:
                q = q.filter(SOData.pic_name == kpi_pic)
                # Exclude SALES_STATUSES (counted in SALES KPI, not this PIC's KPI)
                q = q.filter(~SOData.so_status.in_(list(SALES_STATUSES)))
        elif kpi_pic == 'Unassigned':
            q = q.filter(db.or_(SOData.pic_name.is_(None), SOData.pic_name == ''))

        raw_purchase_expr = case(
            (func.coalesce(SOData.purchasing_amount, 0) != 0, func.coalesce(SOData.purchasing_amount, 0)),
            else_=func.coalesce(SOData.purchasing_price, 0) * func.coalesce(SOData.so_qty, 0)
        )
        # Only consider rows with valid (positive) purchase amount — empty/
        # zero/negative purchase → margin is invalid, excluded from filter.
        valid_purchase_filter = (raw_purchase_expr > 0)
        if margin_filter == 'negative':
            q = q.filter(valid_purchase_filter, func.coalesce(SOData.sales_amount, 0) < raw_purchase_expr)
        elif margin_filter == 'positive':
            q = q.filter(valid_purchase_filter, func.coalesce(SOData.sales_amount, 0) >= raw_purchase_expr)

        so_list_fields = (
            SOData.id, SOData.so_number, SOData.so_item, SOData.so_status,
            SOData.operation_unit_name, SOData.vendor_name, SOData.manufacturer_name,
            SOData.customer_po_number, SOData.delivery_memo, SOData.so_create_date,
            SOData.pic_name, SOData.sales_amount, SOData.purchasing_amount,
            SOData.purchasing_price, SOData.so_qty, SOData.purchasing_currency,
            SOData.purchasing_amount_idr, SOData.product_id, SOData.product_name,
            SOData.specification, SOData.matched_po_number, SOData.remarks,
            SOData.delivery_plan_date, SOData.sales_price, SOData.sales_unit,
            SOData.vendor_id, SOData.currency, SOData.client_id,
        )

        # Lingkup KPI (ekuivalen kpi_sos): clean(so_status) NOT IN HIDDEN —
        # None/''/'nan' tetap ikut (clean() -> None -> bukan anggota list).
        _st_col = SOData.so_status
        _st_trim = func.trim(_st_col, _WS)
        _kpi_not_hidden = db.or_(_st_col.is_(None), _st_trim.notin_(list(HIDDEN_SO_STATUSES)))
        _kpi_not_sales = db.or_(_st_col.is_(None), _st_trim.notin_(list(SALES_STATUSES)))
        # PIC kanonik `pic or 'Unassigned'` + flag SALES (clean(status) IN SALES).
        _pic_col = SOData.pic_name
        _canon_pic = case((_pic_col.is_(None) | (_pic_col == ''), 'Unassigned'), else_=_pic_col)
        _is_sales = db.and_(_st_col.isnot(None), _st_trim.in_(list(SALES_STATUSES)))

        # total + subtotal: satu query COUNT+SUM (dulu len()+sum() di Python).
        _cnt, _sum = q.filter(_kpi_not_hidden, _kpi_not_sales).with_entities(
            func.count(SOData.id), func.sum(SOData.sales_amount)).first()
        total = int(_cnt or 0)
        subtotal_amount = float(_sum or 0.0)

        # Halaman tabel: ORDER BY + LIMIT/OFFSET — ORM hanya per_page baris.
        if sort_order == 'oldest':
            paged = q.options(load_only(*so_list_fields)).order_by(
                SOData.so_create_date.asc(), SOData.so_item.asc()
            ).offset((page - 1) * per_page).limit(per_page).all()
        else:
            paged = q.options(load_only(*so_list_fields)).order_by(
                SOData.so_create_date.desc(), SOData.so_item.asc()
            ).offset((page - 1) * per_page).limit(per_page).all()

        # Prefetch exchange rates for USD/EUR rows so purchase_price_idr /
        # purchase_amount_idr_for_margin can convert correctly.
        prefetch_convertible_exchange_rates(paged, fetch_missing=False)

        # V60z15: APPROVAL_Q — only fetch if we're on page 1 (approval data is only shown on first page)
        approval_sos = []
        if page == 1:
            approval_statuses = {'Approval Apply', 'Approval Reject'}
            approval_q = SOData.query.filter(SOData.so_status.in_(list(approval_statuses)), so_countable_sql_filter())
            approval_q = apply_so_client_filter(approval_q, clients)
            approval_q = apply_so_pic_filter(approval_q, global_pics)
            if op_units: approval_q = approval_q.filter(SOData.operation_unit_name.in_(op_units))
            if vendors: approval_q = approval_q.filter(SOData.vendor_name.in_(vendors))
            if manufacturers: approval_q = approval_q.filter(SOData.manufacturer_name.in_(manufacturers))
            if statuses: approval_q = approval_q.filter(SOData.so_status.in_(statuses))
            approval_q = apply_so_search_filter(approval_q, so_items)
            approval_q = apply_so_create_date_filter(approval_q, date_year, date_from, date_to)
            if pics:
                pic_set = set(pics)
                non_empty_pics = [p for p in pic_set if p and p != 'Unassigned']
                wants_unassigned = 'Unassigned' in pic_set or '(Empty)' in pic_set
                if non_empty_pics and wants_unassigned:
                    approval_q = approval_q.filter(db.or_(SOData.pic_name.in_(non_empty_pics), SOData.pic_name.is_(None), SOData.pic_name == ''))
                elif non_empty_pics:
                    approval_q = approval_q.filter(SOData.pic_name.in_(non_empty_pics))
                elif wants_unassigned:
                    approval_q = approval_q.filter(db.or_(SOData.pic_name.is_(None), SOData.pic_name == ''))
            if kpi_pic and kpi_pic != 'Unassigned' and kpi_pic != 'SALES':
                approval_q = approval_q.filter(SOData.pic_name == kpi_pic)
            elif kpi_pic == 'Unassigned':
                approval_q = approval_q.filter(db.or_(SOData.pic_name.is_(None), SOData.pic_name == ''))
            if sort_order == 'oldest':
                approval_sos = approval_q.options(load_only(*so_list_fields)).order_by(SOData.so_create_date.asc(), SOData.so_item.asc()).all()
            else:
                approval_sos = approval_q.options(load_only(*so_list_fields)).order_by(SOData.so_create_date.desc(), SOData.so_item.asc()).all()

        # ── V61.6 FILTER INTERDEPENDENCY (rework V60z20; V63.27.5: selalu SQL)
        # Opsi dropdown = baris lingkup DASAR TANPA lima filter dropdown.
        # Perilaku lama dipertahankan persis per cabang:
        #   - tanpa filter dropdown aktif -> lingkup = q (termasuk trade/margin;
        #     hidden ikut bila show_finished=1) = proyeksi all_sos lama.
        #   - dengan filter dropdown aktif -> query terpisah TANPA trade/margin
        #     dan SELALU tanpa hidden = options_q lama.
        _dropdown_filters_active = bool(op_units or vendors or manufacturers or statuses or pics)
        if _dropdown_filters_active:
            options_q = SOData.query.filter(so_countable_sql_filter(), ~SOData.so_status.in_(list(HIDDEN_SO_STATUSES)))
            options_q = apply_so_client_filter(options_q, clients)
            options_q = apply_so_pic_filter(options_q, global_pics)
            options_q = apply_so_search_filter(options_q, so_items)
            options_q = apply_so_create_date_filter(options_q, date_year, date_from, date_to)
            if kpi_pic and kpi_pic != 'Unassigned':
                if kpi_pic == 'SALES':
                    options_q = options_q.filter(SOData.so_status.in_(list(SALES_STATUSES)))
                else:
                    options_q = options_q.filter(SOData.pic_name == kpi_pic)
                    options_q = options_q.filter(~SOData.so_status.in_(list(SALES_STATUSES)))
            elif kpi_pic == 'Unassigned':
                options_q = options_q.filter(db.or_(SOData.pic_name.is_(None), SOData.pic_name == ''))
            if _aging_cond is not None:
                options_q = options_q.filter(_aging_cond)
        else:
            options_q = q
        opt_rows = options_q.with_entities(
            SOData.operation_unit_name, SOData.vendor_name, SOData.manufacturer_name,
            SOData.so_status, SOData.pic_name, SOData.so_create_date).distinct().all()

        def so_filtered(exclude=None):
            """opt_rows (tuple) + lima filter dropdown, KECUALI yang dikecualikan."""
            exclude = exclude or ''
            result = opt_rows
            if 'op_units' not in exclude and op_units:
                ou_set = set(op_units)
                result = [r for r in result if r[0] in ou_set]
            if 'vendors' not in exclude and vendors:
                v_set = set(vendors)
                result = [r for r in result if r[1] in v_set]
            if 'manufacturers' not in exclude and manufacturers:
                m_set = set(manufacturers)
                result = [r for r in result if r[2] in m_set]
            if 'statuses' not in exclude and statuses:
                s_set = set(statuses)
                result = [r for r in result if r[3] in s_set]
            if 'pics' not in exclude and pics:
                pic_set = set(pics)
                result = [r for r in result if canonical_pending_pic(r[4], r[0]) in pic_set]
            return result

        op_units_opts = sorted({r[0] for r in so_filtered('op_units') if r[0]})
        vendors_opts  = sorted({r[1] for r in so_filtered('vendors') if r[1]})
        manufacturers_opts = sorted({r[2] for r in so_filtered('manufacturers') if r[2]})
        statuses_opts = sorted({r[3] for r in so_filtered('statuses') if r[3]})

        # V61.6: opsi PIC kini dari BARIS pada lingkup berjalan (interdependen
        # penuh) — bukan lagi gabungan tabel master. 'SALES' hanya muncul bila
        # ada baris SALES_STATUSES; 'Unassigned' hanya bila ada baris tanpa PIC.
        _pic_opt_rows = so_filtered('pics')
        _pic_opt_set = set()
        for r in _pic_opt_rows:
            _pic_label = canonical_pending_pic(r[4], r[0])
            if _pic_label and _pic_label != 'Unassigned':
                _pic_opt_set.add(_pic_label)
        if any(clean(r[3]) in SALES_STATUSES for r in _pic_opt_rows):
            _pic_opt_set.add('SALES')
        if any(canonical_pending_pic(r[4], r[0]) == 'Unassigned' for r in _pic_opt_rows):
            _pic_opt_set.add('Unassigned')
        pics_opts = sorted(_pic_opt_set)

        # _all_known_so_pics tetap dipertahankan HANYA untuk pic_aggregations
        # (kartu KPI PIC — perilaku lama: PIC master ikut tampil dgn count 0).
        _all_cat_by_id, _all_cat_by_name = master_pic_maps()
        _all_known_so_pics = set()
        _all_known_so_pics.update(_all_cat_by_id.values())
        _all_known_so_pics.update(_all_cat_by_name.values())
        _all_known_so_pics.update(clean(m.pic_name) for m in db.session.query(MasterClientPIC).all() if clean(m.pic_name))
        _all_known_so_pics.update(clean(m.pic_name) for m in db.session.query(MasterVendorPIC).all() if clean(m.pic_name))
        _all_known_so_pics.discard('')
        _all_known_so_pics.discard(None)
        # V63.27.5: agregasi PIC via SQL GROUP BY (canon_pic x flag SALES) —
        # dulu loop kpi_sos di Python. Urutan PENTING untuk ekuivalensi:
        # (1) known set dari SEMUA baris lingkup KPI (canon != 'Unassigned',
        #     termasuk baris SALES) + master + 'SALES'; (2) init dict nol;
        # (3) agregasi per label ('SALES' bila flag, selain itu canon;
        #     baris Unassigned/'' tidak diagregasi = tetap 0).
        pic_rows = q.filter(_kpi_not_hidden).with_entities(
            _canon_pic, _is_sales, func.count(SOData.id), func.sum(SOData.sales_amount)
        ).group_by(_canon_pic, _is_sales).all()
        for _picv, _iss, _c, _a in pic_rows:
            if _picv and _picv != 'Unassigned':
                _all_known_so_pics.add(_picv)
        _all_known_so_pics.add('SALES')
        pic_aggregations = {p: {'pic': p, 'count': 0, 'amount': 0.0} for p in _all_known_so_pics}
        for _picv, _iss, _c, _a in pic_rows:
            if _iss:
                _label = 'SALES'
            else:
                _label = _picv
                if not _label or _label == 'Unassigned':
                    continue
            if _label not in pic_aggregations:
                pic_aggregations[_label] = {'pic': _label, 'count': 0, 'amount': 0.0}
            pic_aggregations[_label]['count'] += int(_c or 0)
            pic_aggregations[_label]['amount'] += float(_a or 0.0)
        pic_aggs_list = sort_pic_kpis(list(pic_aggregations.values()))

        # V60s: Sales KPI = SOs with SALES_STATUSES (CLOSED except Delivery Completed)
        sales_count = pic_aggregations.get('SALES', {}).get('count', 0)
        sales_amount = pic_aggregations.get('SALES', {}).get('amount', 0.0)

        payload = {
            'data': [so_dict(s) for s in paged],
            'approval_data': [so_dict(s) for s in approval_sos],
            'total': total, 'subtotal_amount': round(subtotal_amount, 2), 'page': page, 'per_page': per_page,
            'filters': {'op_units': list(op_units_opts), 'vendors': list(vendors_opts), 'manufacturers': list(manufacturers_opts), 'statuses': list(statuses_opts), 'pics': list(pics_opts)},
            'pic_aggregations': pic_aggs_list,
            'sales_count': sales_count, 'sales_amount': round(sales_amount, 2),
        }
        runtime_cache_set(cache_key, payload, ttl_seconds=600)
        return jsonify(payload)
    except Exception as e:
        import traceback; traceback.print_exc()
        return jsonify({'error': str(e)}), 500

@app.route('/api/data/so-status-detail/<path:status>', methods=['GET'])
def get_so_status_detail(status):
    try:
        month = request.args.get('month')
        hidden_so = get_hidden_so_items()
        date_year, date_from, date_to = parse_so_date_args()
        clients = selected_clients()
        pics = selected_pics()
        q = SOData.query.filter_by(so_status=status)
        q = apply_so_client_filter(q, clients)
        q = apply_so_pic_filter(q, pics)
        q = apply_so_create_date_filter(q, date_year, date_from, date_to)
        sos = q.all()
        if month:
            sos = [s for s in sos if s.so_create_date and s.so_create_date.strftime('%b %Y') == month]
        sos = [s for s in sos if s.so_item not in hidden_so and s.so_number not in hidden_so and so_is_countable(s.so_item, customer_po_number=s.customer_po_number, delivery_memo=s.delivery_memo)]
        return jsonify([so_dict(s) for s in sos])
    except Exception as e: return jsonify({'error': str(e)}), 500

