def _settlement_base_q(clients, pics, date_year='', date_from='', date_to='', is_sqlite=None):
    """Lingkup dasar Settlement: Delivery Completed + filter global (Op Unit/PIC/date)."""
    q = db.session.query(SOData).filter(SOData.so_status == 'Delivery Completed')
    q = apply_so_client_filter(q, clients)
    q = apply_so_pic_filter(q, pics)
    q = apply_so_create_date_filter(q, date_year, date_from, date_to, is_sqlite=is_sqlite)
    q = q.filter(~SOData.operation_unit_name.in_(list(EXCLUDED_OP_UNITS)))
    return q

def settlement_row_dict(s):
    """1 baris tabel Settlement — 33 kolom kuning + 7 kolom hijau (computed)."""
    pp_idr = purchase_price_idr(s)
    pa_idr = purchase_amount_idr_for_margin(s)
    sales = float(s.sales_amount or 0)
    # Konvensi margin sama dengan Completed Summary: valid hanya bila purchase > 0.
    margin = (sales - pa_idr) if (pa_idr > 0 and sales > 0) else None
    margin_pct = (margin / sales * 100.0) if (margin is not None and sales > 0) else None
    # Lead time hari KERJA (NETWORKDAYS): purchasing = PO Confirm - SO Create;
    # vendor = Delivery Complete - PO Confirm.
    # V63.6: Aging = HARI KALENDER sejak Delivery Complete (Sabtu/Minggu/libur
    # dihitung), hanya jika settlement belum complete
    _ss_clean = clean(s.settlement_status)
    _aging_days = days_since(s.delivery_complete_date) if (s.delivery_complete_date and _ss_clean not in SETTLEMENT_COMPLETE_PHRASES) else None
    lt_purch = count_workdays(s.so_create_date, s.po_confirm_date) if (s.so_create_date and s.po_confirm_date) else None
    lt_vendor = count_workdays(s.po_confirm_date, s.delivery_complete_date) if (s.po_confirm_date and s.delivery_complete_date) else None
    return {
        # ── kolom kuning (data Search Client Odr) — urutan = template Excel ──
        'id': s.id,
        'customer_po_number': s.customer_po_number or '',
        'operation_unit_name': s.operation_unit_name or '',
        'settlement_status': s.settlement_status or '',
        'purchasing_settlement_check': s.purchasing_settlement_check or '',
        'purchasing_settlement_month': s.purchasing_settlement_month or '',
        'sales_settlement_status': s.sales_settlement_status or '',
        'sales_settlement_month': s.sales_settlement_month or '',
        'so_item': s.so_item or '',
        'po_number': s.matched_po_number or '',
        'shipping_trade_statement_number': s.shipping_trade_statement_number or '',
        'exception_process': s.exception_process or '',
        'original_so_number': s.original_so_number or '',
        'original_so_item': s.original_so_item or '',
        'operation_unit_id': s.operation_unit_id or '',
        'so_status': s.so_status or '',
        'product_id': s.product_id or '',
        'product_name': s.product_name or '',
        'specification': s.specification or '',
        'manufacturer_name': s.manufacturer_name or '',
        'vendor_id': s.vendor_id or '',
        'vendor_name': s.vendor_name or '',
        'sales_unit': s.sales_unit or '',
        'so_qty': float(s.so_qty) if s.so_qty is not None else None,
        'return_qty': float(s.return_qty) if s.return_qty is not None else None,
        'purchasing_currency': s.purchasing_currency or '',
        'purchasing_price': float(s.purchasing_price) if s.purchasing_price is not None else None,
        'currency': s.currency or '',
        'sales_price': float(s.sales_price) if s.sales_price is not None else None,
        'sales_amount': float(s.sales_amount) if s.sales_amount is not None else None,
        'delivery_memo': s.delivery_memo or '',
        'so_create_date': s.so_create_date.isoformat() if s.so_create_date else '',
        'po_confirm_date': s.po_confirm_date.isoformat() if s.po_confirm_date else '',
        'delivery_complete_date': s.delivery_complete_date.isoformat() if s.delivery_complete_date else '',
        # ── kolom hijau (tambahan/computed) ──
        'remarks': s.remarks or '',
        'purchase_price_idr': round(pp_idr, 2) if pp_idr else 0.0,
        'purchase_amount_idr': round(pa_idr, 2) if pa_idr else 0.0,
        'gross_margin': round(margin, 2) if margin is not None else None,
        'gross_margin_pct': round(margin_pct, 2) if margin_pct is not None else None,
        'purchasing_lead_time': lt_purch,
        'vendor_lead_time': lt_vendor,
        'aging_days': _aging_days,
        'aging_label': get_aging_label(_aging_days) if _aging_days is not None else None,
        'pic_name': canonical_pending_pic(s.pic_name, s.operation_unit_name),
    }

SETTLEMENT_SORTS = {
    'so_create_date_desc': ('so_create_date', True),
    'so_create_date_asc': ('so_create_date', False),
    'po_confirm_date_desc': ('po_confirm_date', True),
    'delivery_complete_date_desc': ('delivery_complete_date', True),
}

def _settlement_filter_rows(rows, view='all', kpi_filter='', terms=None,
                            op_units=None, vendors=None, dc_months=None, exclude=None,
                            trade_type='', aging=None):
    """Filter baris Settlement: checklist(view) + KPI-click + search + dropdown
    (Op Unit / Vendor / bulan Delivery Complete). exclude=nama filter yg DIABAIKAN
    (dipakai untuk menghitung opsi dropdown agar tidak collapse — pola V61.6)."""
    out = rows
    if view == 'pending':
        out = [s for s in out if clean(s.settlement_status) not in SETTLEMENT_COMPLETE_PHRASES]
    if kpi_filter == 'purchase':
        out = [s for s in out if clean(s.purchasing_settlement_check) not in SETTLEMENT_COMPLETE_PHRASES]
    elif kpi_filter == 'sales':
        out = [s for s in out if clean(s.sales_settlement_status) not in SETTLEMENT_COMPLETE_PHRASES]
    # V62.6: trade type (Import = purchasing currency non-IDR, Local = IDR;
    # empty purchasing_currency dianggap IDR, konvensi sama dengan app).
    if trade_type == 'import':
        out = [s for s in out if (s.purchasing_currency or '').strip().upper() not in ('', 'IDR')]
    elif trade_type == 'local':
        out = [s for s in out if (s.purchasing_currency or '').strip().upper() in ('', 'IDR')]
    if terms:
        lowered = [t.lower() for t in terms]
        def _match_search(s):
            hay = ' '.join(filter(None, [
                s.so_item, s.so_number, s.customer_po_number, s.matched_po_number,
                s.product_id, s.product_name, s.specification, s.manufacturer_name,
                s.vendor_name, s.vendor_id, s.operation_unit_name, s.shipping_trade_statement_number,
            ])).lower()
            return any(t in hay for t in lowered)
        out = [s for s in out if _match_search(s)]
    if exclude != 'op_unit' and op_units:
        wanted = {str(u).strip() for u in op_units}
        out = [s for s in out if (s.operation_unit_name or '').strip() in wanted]
    if exclude != 'vendor' and vendors:
        wanted = {str(v).strip() for v in vendors}
        out = [s for s in out if (s.vendor_name or '').strip() in wanted]
    if exclude != 'dc_month' and dc_months:
        wanted = {str(m).strip() for m in dc_months}
        out = [s for s in out if (s.delivery_complete_date.strftime('%Y-%m') if s.delivery_complete_date else '') in wanted]
    if aging:
        # V63.15: filter Aging (bucket hari kalender sejak Delivery Complete;
        # baris settlement-complete / tanpa tanggal dianggap tanpa aging).
        _aging_wanted = {str(a).strip() for a in aging if a and str(a).strip()}
        if _aging_wanted:
            def _aging_ok(s):
                if not s.delivery_complete_date: return False
                if clean(s.settlement_status) in SETTLEMENT_COMPLETE_PHRASES: return False
                return get_aging_label(days_since(s.delivery_complete_date)) in _aging_wanted
            out = [s for s in out if _aging_ok(s)]
    return out

def _sort_settlement_rows(rows, sort_key):
    """Urutkan baris Settlement. Default: SO Create Date terbaru (desc)."""
    field, desc = SETTLEMENT_SORTS.get(sort_key, SETTLEMENT_SORTS['so_create_date_asc'])
    rows = sorted(rows, key=lambda s: (s.so_item or ''))
    if desc:
        rows.sort(key=lambda s: (getattr(s, field) or date(1970, 1, 1)), reverse=True)
    else:
        rows.sort(key=lambda s: (getattr(s, field) is None, getattr(s, field) or date(1970, 1, 1)))
    return rows

def _settlement_kpis(rows):
    """KPI dihitung dari lingkup filter global SAJA (mengabaikan checklist/KPI-click/search)
    supaya angka kartu KPI konsisten dan bisa dipakai untuk drill-down."""
    total_count = len(rows)
    total_purchase = sum(purchase_amount_idr_for_margin(s) for s in rows)
    total_sales = sum(float(s.sales_amount or 0) for s in rows)
    purch_not = [s for s in rows if clean(s.purchasing_settlement_check) not in SETTLEMENT_COMPLETE_PHRASES]
    sales_not = [s for s in rows if clean(s.sales_settlement_status) not in SETTLEMENT_COMPLETE_PHRASES]
    # V62.1: PO dihitung dari purchasing settlement (nomor PO unik),
    # SO dihitung dari sales settlement (nomor SO unik).
    all_pos = {clean(s.matched_po_number) for s in rows if clean(s.matched_po_number)}
    pos_not = {clean(s.matched_po_number) for s in purch_not if clean(s.matched_po_number)}
    all_sos = {clean(s.so_number) for s in rows if clean(s.so_number)}
    sos_not = {clean(s.so_number) for s in sales_not if clean(s.so_number)}
    # V63.5: KPI Settled PO — PO unik yang sudah Settlement Completed
    _settled_rows = [s for s in rows if clean(s.settlement_status) in SETTLEMENT_COMPLETE_PHRASES]
    settled_pos = {clean(s.matched_po_number) for s in _settled_rows if clean(s.matched_po_number)}
    return {
        'total_count': total_count,
        'total_po_count': len(all_pos),
        'settled_po_count': len(settled_pos),
        'settled_po_pct': (round(len(settled_pos) * 100.0 / len(all_pos), 1) if all_pos else None),
        'total_so_count': len(all_sos),
        'total_settlement_amount': round(total_purchase + total_sales, 2),
        'total_purchase_amount': round(total_purchase, 2),
        'total_sales_amount': round(total_sales, 2),
        'gross_margin': round(total_sales - total_purchase, 2) if (total_sales > 0 and total_purchase > 0) else None,
        'purchasing_not_settled_count': len(pos_not),
        'purchasing_not_settled_rows': len(purch_not),
        'purchasing_not_settled_amount': round(sum(purchase_amount_idr_for_margin(s) for s in purch_not), 2),
        'sales_not_settled_count': len(sos_not),
        'sales_not_settled_rows': len(sales_not),
        'sales_not_settled_amount': round(sum(float(s.sales_amount or 0) for s in sales_not), 2),
    }

# ── V63.27.5 PERF: baris Settlement via SQL + memo KPI lingkup dasar ────────
_SETTLEMENT_KPI_MEMO = {'key': None, 'kpis': None, 'expires': None}
_SETTLEMENT_KPI_LOCK = threading.Lock()

# V63.27.9 PERF: opsi dropdown Settlement tidak perlu dihitung ulang setiap
# checkbox Op Unit/Vendor/Delivery Month berubah. Seperti Excel, daftar pilihan
# tetap tersedia dalam scope aktif (global + View/KPI/Search/Type/Aging), lalu
# selection lokal diterapkan saat user menekan Apply. Cache 5 menit menghapus
# 3 DISTINCT scan yang dulu terjadi pada SETIAP perubahan filter.
_SETTLEMENT_FILTER_OPTIONS_MEMO = {}
_SETTLEMENT_FILTER_OPTIONS_LOCK = threading.Lock()
_SETTLEMENT_FILTER_OPTIONS_TTL = 300
_SETTLEMENT_FILTER_OPTIONS_MAX = 64

def _settlement_filter_options_cached(clients, pics, date_year, date_from, date_to,
                                      is_sqlite, view='all', kpi_filter='', terms=None,
                                      trade_type='', aging=None):
    key = repr((clients, pics, date_year, date_from, date_to, view, kpi_filter,
                tuple(terms or ()), trade_type, tuple(sorted(aging or ()))))
    now = datetime.utcnow()
    with _SETTLEMENT_FILTER_OPTIONS_LOCK:
        rec = _SETTLEMENT_FILTER_OPTIONS_MEMO.get(key)
        if rec and rec.get('expires') and rec['expires'] > now:
            return rec['value']

    q = _settlement_base_q(clients, pics, date_year, date_from, date_to,
                           is_sqlite=is_sqlite)
    # Sengaja tanpa op_unit/vendor/dc_month: pilihan tidak collapse saat user
    # mencentang item lain, dan request berikutnya dapat reuse cache yang sama.
    q = _settlement_sql_filters(q, view, kpi_filter, terms,
                                trade_type=trade_type, aging=aging)
    op_units = sorted({(u or '').strip() for (u,) in q.with_entities(
        SOData.operation_unit_name).distinct().all()} - {''})
    vendors = sorted({(v or '').strip() for (v,) in q.with_entities(
        SOData.vendor_name).distinct().all()} - {''})
    dc_map = {}
    for (d,) in q.with_entities(SOData.delivery_complete_date).distinct().all():
        if d:
            dc_map.setdefault(d.strftime('%Y-%m'), d.strftime('%b %y'))
    value = {
        'op_units': op_units,
        'vendors': vendors,
        'dc_months': [{'v': k, 't': dc_map[k]} for k in sorted(dc_map.keys(), reverse=True)],
    }
    with _SETTLEMENT_FILTER_OPTIONS_LOCK:
        # Buang expired + batasi ukuran agar search unik tidak menumpuk RAM.
        expired = [k for k, v in _SETTLEMENT_FILTER_OPTIONS_MEMO.items()
                   if not v.get('expires') or v['expires'] <= now]
        for k in expired:
            _SETTLEMENT_FILTER_OPTIONS_MEMO.pop(k, None)
        if len(_SETTLEMENT_FILTER_OPTIONS_MEMO) >= _SETTLEMENT_FILTER_OPTIONS_MAX:
            oldest = min(_SETTLEMENT_FILTER_OPTIONS_MEMO,
                         key=lambda k: _SETTLEMENT_FILTER_OPTIONS_MEMO[k].get('created', now))
            _SETTLEMENT_FILTER_OPTIONS_MEMO.pop(oldest, None)
        _SETTLEMENT_FILTER_OPTIONS_MEMO[key] = {
            'value': value,
            'created': now,
            'expires': now + timedelta(seconds=_SETTLEMENT_FILTER_OPTIONS_TTL),
        }
    return value

def _settlement_kpis_cached(clients, pics, date_year, date_from, date_to, is_sqlite):
    """KPI settlement hanya bergantung pada lingkup dasar (client/PIC/tanggal
    global) — dihitung SEKALI per kunci lalu di-memo 5 menit. Perubahan filter
    tabel (dropdown/search/aging/checklist) tidak menghitung ulang KPI, jadi
    filter terasa instan; KPI sendiri tetap dihitung dgn konversi kurs Python
    yang benar."""
    key = repr((clients, pics, date_year, date_from, date_to))
    now = datetime.utcnow()
    with _SETTLEMENT_KPI_LOCK:
        m = _SETTLEMENT_KPI_MEMO
        if m['kpis'] is not None and m['key'] == key and m['expires'] and m['expires'] > now:
            return m['kpis']
    base_rows = _settlement_base_q(clients, pics, date_year, date_from, date_to,
                                   is_sqlite=is_sqlite).options(load_only(*SETTLEMENT_LOAD_FIELDS)).all()
    prefetch_convertible_exchange_rates(base_rows, fetch_missing=False)
    kpis = _settlement_kpis(base_rows)
    with _SETTLEMENT_KPI_LOCK:
        _SETTLEMENT_KPI_MEMO.update({'key': key, 'kpis': kpis,
                                     'expires': now + timedelta(seconds=300)})
    return kpis

def _settlement_sql_filters(q, view='all', kpi_filter='', terms=None,
                            op_units=None, vendors=None, dc_months=None,
                            exclude=None, trade_type='', aging=None):
    """Padanan SQL dari _settlement_filter_rows — semantik baris per baris
    sama: checklist view, KPI-click, search multi-kolom, dropdown Op Unit/
    Vendor/bulan Delivery Complete, Aging, dan trade type."""
    if view == 'pending':
        q = q.filter(_sett_pend_sql(SOData.settlement_status))
    if kpi_filter == 'purchase':
        q = q.filter(_sett_pend_sql(SOData.purchasing_settlement_check))
    elif kpi_filter == 'sales':
        q = q.filter(_sett_pend_sql(SOData.sales_settlement_status))
    if trade_type == 'import':
        q = q.filter(func.upper(func.trim(func.coalesce(SOData.purchasing_currency, ''))).notin_(('', 'IDR')))
    elif trade_type == 'local':
        q = q.filter(func.upper(func.trim(func.coalesce(SOData.purchasing_currency, ''))).in_(('', 'IDR')))
    if terms:
        _fields = [SOData.so_item, SOData.so_number, SOData.customer_po_number,
                   SOData.matched_po_number, SOData.product_id, SOData.product_name,
                   SOData.specification, SOData.manufacturer_name, SOData.vendor_name,
                   SOData.vendor_id, SOData.operation_unit_name,
                   SOData.shipping_trade_statement_number]
        for t in terms:
            t = t.lower()
            q = q.filter(db.or_(*[func.instr(func.lower(func.coalesce(f, '')), t) > 0 for f in _fields]))
    if exclude != 'op_unit' and op_units:
        wanted = [str(u).strip() for u in op_units]
        q = q.filter(db.or_(SOData.operation_unit_name.is_(None),
                            func.trim(SOData.operation_unit_name, _WS).in_(wanted)))
    if exclude != 'vendor' and vendors:
        wanted = [str(v).strip() for v in vendors]
        q = q.filter(db.or_(SOData.vendor_name.is_(None),
                            func.trim(SOData.vendor_name, _WS).in_(wanted)))
    if exclude != 'dc_month' and dc_months:
        wanted = [str(m).strip() for m in dc_months]
        q = q.filter(db.or_(SOData.delivery_complete_date.is_(None),
                            func.strftime('%Y-%m', SOData.delivery_complete_date).in_(wanted)))
    _aw = {str(a).strip() for a in (aging or []) if a and str(a).strip()}
    if _aw:
        # V63.15: filter Aging (bucket hari kalender sejak Delivery Complete;
        # baris settlement-complete / tanpa tanggal dianggap tanpa aging).
        _cond = _aging_sql_clause(_age_expr(SOData.delivery_complete_date), _aw)
        if _cond is None:
            q = q.filter(db.text('1 = 0'))
        else:
            q = q.filter(SOData.delivery_complete_date.isnot(None),
                         _sett_pend_sql(SOData.settlement_status),
                         _cond)
    return q

def _settlement_order_sql(sort_key):
    """Urutan SQL — sama dgn _sort_settlement_rows(): key Python asc =
    (field is None, field or 1970) -> NULL PALING AKHIR; desc = reverse
    (field or 1970) -> NULL tetap paling akhir; tiebreak so_item dengan arah
    yang mengikuti sort utama (stabil-sort Python direverse utk desc)."""
    field, desc = SETTLEMENT_SORTS.get(sort_key, SETTLEMENT_SORTS['so_create_date_asc'])
    col = getattr(SOData, field)
    _null = col.is_(None)
    # reverse=True Python STABIL — tie so_item tetap ASC (tidak dibalik).
    if desc:
        return (_null.asc(), col.desc(), SOData.so_item.asc())
    return (_null.asc(), col.asc(), SOData.so_item.asc())

@app.route('/api/settlement/data', methods=['GET'])
def get_settlement_data():
    try:
        cache_key = runtime_cache_key('settlement_data')
        cached = runtime_cache_get_swr(cache_key, request.full_path)
        if cached is not None: return jsonify(cached)
        page = max(1, int(request.args.get('page', 1)))
        per_page = min(500, max(1, int(request.args.get('per_page', 25))))
        view = (request.args.get('view') or 'all').strip().lower()      # all | pending
        kpi_filter = (request.args.get('kpi') or '').strip().lower()    # '' | purchase | sales
        terms = [t for t in request.args.getlist('search') if t and t.strip()]
        is_sqlite = 'sqlite' in app.config['SQLALCHEMY_DATABASE_URI']
        date_year, date_from, date_to = parse_so_date_args()
        clients = selected_clients()
        pics = selected_pics()

        # Lingkup dasar (KPI): global filter saja.
        base_q = _settlement_base_q(clients, pics, date_year, date_from, date_to, is_sqlite=is_sqlite)

        # Baris tabel: base + checklist + KPI-click + search + dropdown (V62.1).
        op_units = [u for u in request.args.getlist('op_unit') if u and u.strip()]
        vendors = [v for v in request.args.getlist('vendor') if v and v.strip()]
        dc_months = [m for m in request.args.getlist('dc_month') if m and m.strip()]
        sort_key = (request.args.get('sort') or 'so_create_date_asc').strip().lower()
        if sort_key not in SETTLEMENT_SORTS: sort_key = 'so_create_date_asc'
        trade_type = (request.args.get('trade_type') or '').strip().lower()
        aging = [a for a in request.args.getlist('aging') if a and a.strip()]

        # V63.27.9: opsi dropdown dicache per scope; selection lokal tidak
        # memicu ulang tiga DISTINCT scan sehingga Apply terasa seperti Excel.
        filter_opts = _settlement_filter_options_cached(
            clients, pics, date_year, date_from, date_to, is_sqlite,
            view=view, kpi_filter=kpi_filter, terms=terms,
            trade_type=trade_type, aging=aging)

        # V63.27.5: baris tabel = COUNT + ORDER BY + LIMIT/OFFSET di SQL —
        # dulu SEMUA baris lingkup dasar dimuat ORM lalu difilter/disortir di
        # Python (puluhan ribu baris per request).
        q = _settlement_sql_filters(base_q, view, kpi_filter, terms,
                                    op_units, vendors, dc_months,
                                    trade_type=trade_type, aging=aging)
        total = q.with_entities(func.count(SOData.id)).scalar() or 0
        _o1, _o2, _o3 = _settlement_order_sql(sort_key)
        paged = q.order_by(_o1, _o2, _o3).offset((page - 1) * per_page).limit(per_page).all()
        prefetch_convertible_exchange_rates(paged, fetch_missing=False)
        kpis = _settlement_kpis_cached(clients, pics, date_year, date_from, date_to, is_sqlite)
        payload = {
            'data': [settlement_row_dict(s) for s in paged],
            'total': total, 'page': page, 'per_page': per_page,
            'view': view, 'kpi_filter': kpi_filter, 'kpis': kpis,
            'filters': filter_opts,
            'sort': sort_key,
        }
        runtime_cache_set(cache_key, payload, ttl_seconds=600)
        return jsonify(payload)
    except Exception as e:
        import traceback; traceback.print_exc()
        return jsonify({'error': str(e)}), 500

