def load_similarity_cache():
    global _SIMILARITY_CACHE
    try:
        if os.path.exists(_SIMILARITY_CACHE_FILE):
            with open(_SIMILARITY_CACHE_FILE, 'r', encoding='utf-8') as f:
                loaded = json.load(f)
            # V63.27.47: Item Registration now uses four independent field
            # thresholds. Discard prior Item Registration similarity cache keys
            # so average-score false positives cannot survive this deployment.
            if isinstance(loaded, dict):
                _SIMILARITY_CACHE = {
                    k: v for k, v in loaded.items()
                    if not str(k).startswith(('similar_v4|', 'similar_v5_50|'))
                }
            else:
                _SIMILARITY_CACHE = {}
    except Exception as e:
        print(f"Error loading similarity cache: {e}"); _SIMILARITY_CACHE = {}

def save_similarity_cache():
    try:
        os.makedirs(os.path.dirname(_SIMILARITY_CACHE_FILE), exist_ok=True)
        with open(_SIMILARITY_CACHE_FILE, 'w', encoding='utf-8') as f: json.dump(_SIMILARITY_CACHE, f, ensure_ascii=False, separators=(',', ':'))
    except Exception as e:
        print(f"Error saving similarity cache: {e}")

# V61 PERF: debounce penyimpanan cache similarity — dulu save_similarity_cache()
# dipanggil langsung di dalam request GET /api/rfq/data (blocking I/O menulis
# file JSON besar di request path). Sekarang ditulis di background thread
# dengan delay 10 detik; jika ada request baru selama menunggu, satu penulisan
# digabung (dirty-flag).
_SIMILARITY_SAVE_STATE_V61 = {'scheduled': False, 'dirty': False}
_SIMILARITY_SAVE_LOCK_V61 = threading.Lock()

def _schedule_similarity_cache_save(delay_seconds=10.0):
    with _SIMILARITY_SAVE_LOCK_V61:
        _SIMILARITY_SAVE_STATE_V61['dirty'] = True
        if _SIMILARITY_SAVE_STATE_V61['scheduled']:
            return
        _SIMILARITY_SAVE_STATE_V61['scheduled'] = True
    def _worker():
        while True:
            try:
                time.sleep(delay_seconds)
                with _SIMILARITY_SAVE_LOCK_V61:
                    if not _SIMILARITY_SAVE_STATE_V61['dirty']:
                        _SIMILARITY_SAVE_STATE_V61['scheduled'] = False
                        return
                    _SIMILARITY_SAVE_STATE_V61['dirty'] = False
                save_similarity_cache()
            except Exception as exc:
                with _SIMILARITY_SAVE_LOCK_V61:
                    _SIMILARITY_SAVE_STATE_V61['scheduled'] = False
                print(f'[similarity] Background save failed: {exc}')
                return
    threading.Thread(target=_worker, daemon=True, name='similarity-cache-saver').start()

@app.route('/api/item-registration/data', methods=['GET'])
def get_item_registration_data():
    try:
        # V60z57: Smart caching — cache key based on base filter only (date+clients+global_pics+show_terminated+similarity)
        # NOT based on full query string. This means filter changes (proc_status, pic, mfr, etc)
        # will HIT the cache instead of miss. The cached payload contains ALL rows;
        # we filter in-memory below.
        # Fallback: if smart cache miss, build full dataset + cache it.
        page = int(request.args.get('page', 1))
        per_page = int(request.args.get('per_page', 25))
        search = request.args.get('search', '').strip()
        req_numbers = [n.strip() for n in request.args.getlist('req_no') if n.strip()]
        date_year, date_from, date_to = parse_so_date_args()
        clients = selected_clients()
        global_pics = [p.strip() for p in request.args.getlist('global_pic') if p.strip()]
        item_clients = [c.strip() for c in request.args.getlist('item_client') if c.strip()]
        categories = [c.strip() for c in request.args.getlist('category') if c.strip()]
        pics = [p.strip() for p in request.args.getlist('pic') if p.strip()]
        kpi_pic = (request.args.get('kpi_pic') or '').strip()
        proc_statuses = [s.strip() for s in request.args.getlist('proc_status') if s.strip()]
        mfr_names = [s.strip() for s in request.args.getlist('mfr_name') if s.strip()]
        op_units = [s.strip() for s in request.args.getlist('op_unit') if s.strip()]
        bid_types = [s.strip() for s in request.args.getlist('bid_except_type') if s.strip()]
        show_terminated = str(request.args.get('show_terminated', '0')).lower() in ('1', 'true', 'yes')
        req_date_sort = str(request.args.get('req_date_sort', 'oldest')).lower().strip()
        if req_date_sort not in ('oldest', 'newest'): req_date_sort = 'oldest'
        include_similarity = str(request.args.get('similarity', '')).lower() in ('1', 'true', 'yes')
        similar_only = str(request.args.get('similar_only', '0')).lower() in ('1', 'true', 'yes')
        # V61.2 FIX: filter "Similar Items Only" membutuhkan data similarity
        # (similar_prod_ids) untuk menyaring SEMUA baris. Jika toggle Similarity
        # (kolom) belum aktif di frontend, data itu tidak dihitung sehingga
        # filter menghasilkan kosong / tidak konsisten. Paksa aktif — cache
        # key sama dengan similarity=1 jadi tidak ada recompute ekstra.
        if similar_only:
            include_similarity = True
        # V61 PERF FIX: `similar_only` DIKELUARKAN dari base cache key.
        # Sebelumnya, men-klik toggle "Similarity Items Only" mengubah cache
        # key → cache MISS → seluruh dataset (termasuk similarity per baris)
        # dihitung ulang dari nol → terasa "lama sekali". Padahal similar_only
        # hanyalah filter pasca-data (lihat blok filter di bawah). Sekarang
        # toggling filter instan karena dataset similarity=1 sudah ter-cache.
        base_cache_key = ('item_reg_smart', date_year or '', date_from or '', date_to or '',
                          tuple(sorted(clients)) if clients else '',
                          tuple(sorted(global_pics)) if global_pics else '',
                          show_terminated, include_similarity)
        full_dataset = runtime_cache_get_swr(base_cache_key, request.full_path)

        if full_dataset is None:
            # Build full dataset (expensive — runs once per base filter change)
            q = apply_item_registration_date_filter(ItemRegistration.query, date_year, date_from, date_to)
            q = q.filter(~item_registration_kpi_status_expr().in_(list(ITEM_REG_HIDDEN_STATUSES)))
            if not show_terminated:
                q = q.filter(~item_registration_kpi_status_expr().in_(list(ITEM_REG_TERMINATED_STATUSES)))
            if clients: q = q.filter(ItemRegistration.client_name.in_(clients))
            q = apply_item_registration_pic_filter(q, global_pics)
            all_rows = q.all()

            _client_pic_cache = {normalize_client_id(m.client_id): clean(m.pic_name) for m in db.session.query(MasterClientPIC).all() if clean(m.pic_name)}
            _bid_type_pic_cache = {clean(m.bid_type): clean(m.pic_name) for m in db.session.query(MasterBidTypePIC).all() if clean(m.pic_name)}
            _cat_by_id, _cat_by_name = master_pic_maps()
            # V61 PERF: map lookup untuk resolusi PIC per baris tanpa query DB.
            _pic_maps = {'client': _client_pic_cache, 'bid_type': _bid_type_pic_cache, 'cat_by_id': _cat_by_id, 'cat_by_name': _cat_by_name}
            all_known_pics = set()
            all_known_pics.update(_cat_by_id.values())
            all_known_pics.update(_cat_by_name.values())
            all_known_pics.update(_client_pic_cache.values())
            all_known_pics.update(_bid_type_pic_cache.values())
            all_known_pics.discard(''); all_known_pics.discard(None)
            all_known_pics.add('SARINA')

            row_dicts = []
            sales_count = 0
            db_count_kpi = 0
            missing_by_pic = {pic: 0 for pic in all_known_pics}
            excluded_statuses_lower = {s.lower() for s in ITEM_REG_KPI_EXCLUDED_STATUSES}
            all_clients_set, all_op_units_set, all_bid_types_set = set(), set(), set()
            all_categories_set, all_proc_statuses_set, all_mfr_names_set = set(), set(), set()
            all_pics_set = set(all_known_pics)

            for row in all_rows:
                # V61 PERF: resolve PIC via map yang sudah di-preload (dulu:
                # 3 query DB per baris — pola N+1 yang membuat build dataset
                # Item Registration lambat).
                pic = resolve_item_registration_pic(row, maps=_pic_maps)
                skip_sim = (pic == 'SALES') or (pic == 'DB')
                similar_items = find_similar_registered_items(row) if (include_similarity and not skip_sim) else None
                d = item_registration_dict(row, include_similarity=False, pic=pic)
                d['pic'] = pic
                if include_similarity:
                    d['similar_items'] = similar_items
                    d['similar_prod_ids'] = (similar_items or {}).get('product_ids', '')
                    d['similar_prod_name'] = (similar_items or {}).get('product_name', '')
                    d['similar_spec'] = (similar_items or {}).get('specification', '')
                    d['similar_mfr_name'] = (similar_items or {}).get('manufacturer_name', '')
                    d['similar_odr_unit'] = (similar_items or {}).get('order_unit', '')
                    d['similar_score'] = (similar_items or {}).get('similarity', None)
                    d['similar_count'] = (similar_items or {}).get('count', 0)

                owner_lower = (d.get('existing_owner') or '').strip().lower()
                stock_no_str = str(d.get('stock_no') or '').strip()
                ps_lower = (d.get('proc_status') or '').strip().lower()
                is_excluded = ps_lower in excluded_statuses_lower
                is_stock_b = stock_no_str.upper().startswith('B') if stock_no_str else False
                is_terminated = 'terminate' in owner_lower or 'terminate' in ps_lower
                has_empty_prod_id = not clean(d.get('prod_id'))

                if 'sales pic' in owner_lower and not is_terminated and not is_excluded and not is_stock_b:
                    sales_count += 1
                if 'db part' in owner_lower and not is_excluded and not is_stock_b and not is_terminated:
                    db_count_kpi += 1
                if is_stock_b and not is_excluded and not is_terminated:
                    if pic == 'SARINA': missing_by_pic['SARINA'] = missing_by_pic.get('SARINA', 0) + 1
                elif not is_excluded and not is_terminated:
                    if 'sales pic' not in owner_lower and 'db part' not in owner_lower and has_empty_prod_id:
                        if pic and pic != 'Unassigned': missing_by_pic[pic] = missing_by_pic.get(pic, 0) + 1

                if clean(d.get('client_name')): all_clients_set.add(clean(d['client_name']))
                if clean(d.get('operation_unit_name')): all_op_units_set.add(clean(d['operation_unit_name']))
                if clean(d.get('bid_except_type')): all_bid_types_set.add(clean(d['bid_except_type']))
                if clean(d.get('category')): all_categories_set.add(clean(d['category']))
                if clean(d.get('proc_status')): all_proc_statuses_set.add(clean(d['proc_status']))
                if clean(d.get('mfr_name')): all_mfr_names_set.add(clean(d['mfr_name']))
                if pic and pic != 'Unassigned': all_pics_set.add(pic)
                row_dicts.append(d)

            missing_prod_id_by_pic = [{'pic': p, 'count': c} for p, c in sorted(missing_by_pic.items(), key=lambda x: (-x[1], x[0]))]
            last_upload = db.session.query(func.max(UploadLog.uploaded_at)).filter(UploadLog.file_type == 'ITEM_REG').scalar()
            full_dataset = {
                'rows': row_dicts, 'sales_count': sales_count, 'db_count': db_count_kpi,
                'missing_prod_id_by_pic': missing_prod_id_by_pic,
                'client_options': sorted(all_clients_set), 'op_unit_options': sorted(all_op_units_set),
                'bid_except_type_options': sorted(all_bid_types_set), 'category_options': sorted(all_categories_set),
                'proc_status_options': sorted(all_proc_statuses_set), 'mfr_name_options': sorted(all_mfr_names_set),
                'pic_options': sorted(all_pics_set),
                'last_updated': utc_isoformat(last_upload),
                'similarity_columns': [{'field': 'similar_prod_ids', 'label': 'Similar Product ID'}, {'field': 'similar_prod_name', 'label': 'Similar Product Name'}, {'field': 'similar_spec', 'label': 'Similar Spec'}, {'field': 'similar_mfr_name', 'label': 'Similar Mfr. Nm.'}, {'field': 'similar_odr_unit', 'label': 'Similar Odr. Unit'}, {'field': 'similar_score', 'label': '%Similarity'}] if include_similarity else [],
            }
            runtime_cache_set(base_cache_key, full_dataset, ttl_seconds=600)

        # ── V61.6 FILTER INTERDEPENDENCY (Item Registration) ─────────────
        # Refactor: seluruh filter halaman dipindah ke apply_page_filters()
        # dengan parameter exclude. Opsi tiap dropdown (payload di bawah)
        # dihitung dari baris yang lolos SEMUA filter kecuali filter
        # miliknya sendiri — konsisten dengan pola All SO / Import / RFQ.
        # Dulu opsi selalu berasal dari dataset dasar (date + global client/pic)
        # sehingga filter kolom tidak pernah saling menyempitkan.
        # search & similar_only bukan dropdown → di-pre-apply SEKALI ke
        # _source_rows (biaya pencarian string hanya dibayar 1x, bukan 8x).
        _source_rows = full_dataset['rows']
        if similar_only:
            _source_rows = [d for d in _source_rows if clean(d.get('similar_prod_ids')) and clean(d.get('similar_prod_ids')) not in ('-', 'No Similar Item')]
        if search:
            # V61.6: bug laten lama ikut diperbaiki — clean('') mengembalikan
            # None sehingga konkatenasi field kosong (prod_id/remarks/stock_no/
            # req_by yang memang sering kosong di data produksi) melempar
            # TypeError 500 pada setiap search. Gunakan blob aman-None.
            sl = search.lower()
            _IR_SEARCH_FIELDS = ('req_no', 'prod_id', 'prod_name', 'mfr_name', 'remarks',
                                 'stock_no', 'req_owner', 'req_by', 'existing_owner')
            _source_rows = [d for d in _source_rows
                            if sl in ' '.join(str(d.get(fld) or '') for fld in _IR_SEARCH_FIELDS).lower()]

        def apply_page_filters(rows, exclude=''):
            """Terapkan semua filter halaman, kecuali field bernama <exclude>."""
            def on(name): return name != exclude
            r = rows
            if item_clients and on('item_clients'):
                s = {c.lower() for c in item_clients}; r = [d for d in r if clean(d.get('client_name')).lower() in s]
            if categories and on('categories'):
                s = {c.lower() for c in categories}; r = [d for d in r if clean(d.get('category')).lower() in s]
            if proc_statuses and on('proc_statuses'):
                s = {p.lower() for p in proc_statuses}; r = [d for d in r if clean(d.get('proc_status')).lower() in s]
            if mfr_names and on('mfr_names'):
                s = {m.lower() for m in mfr_names}; r = [d for d in r if clean(d.get('mfr_name')).lower() in s]
            if op_units and on('op_units'):
                s = {o.lower() for o in op_units}; r = [d for d in r if clean(d.get('operation_unit_name')).lower() in s]
            if bid_types and on('bid_types'):
                s = {b.lower() for b in bid_types}; r = [d for d in r if clean(d.get('bid_except_type')).lower() in s]
            if req_numbers and on('req_numbers'):
                s = {n.lower() for n in req_numbers}; r = [d for d in r if clean(d.get('req_no')).lower() in s]
            if pics and on('pics'):
                s = set(pics); r = [d for d in r if d.get('pic') in s]
            if kpi_pic:
                excluded_sl = {s.lower() for s in ITEM_REG_KPI_EXCLUDED_STATUSES}
                if kpi_pic == 'SALES':
                    r = [d for d in r if d.get('pic') == 'SALES'
                        and 'terminate' not in (d.get('existing_owner') or '').lower()
                        and (d.get('proc_status') or '').lower() not in excluded_sl
                        and not str(d.get('stock_no') or '').strip().upper().startswith('B')]
                elif kpi_pic == 'DB':
                    r = [d for d in r if d.get('pic') == 'DB']
                elif kpi_pic == 'SARINA':
                    r = [d for d in r if d.get('pic') == 'SARINA']
                elif kpi_pic == 'PURCHASE':
                    # V60z58: PURCHASE = all individual PICs (not SALES, not DB, not SARINA)
                    # + exclude excluded statuses + only empty prod_id
                    r = [d for d in r
                        if d.get('pic') not in ('SALES', 'DB', 'SARINA', 'Unassigned', '')
                        and (d.get('proc_status') or '').lower() not in excluded_sl
                        and not clean(d.get('prod_id'))]
                else:
                    # Individual PIC KPI click
                    r = [d for d in r if d.get('pic') == kpi_pic
                        and (d.get('proc_status') or '').lower() not in excluded_sl
                        and not clean(d.get('prod_id'))]
            return r

        filtered = apply_page_filters(_source_rows)

        # Opsi interdependent — masing-masing mengecualikan filter miliknya
        client_options = sorted({clean(d.get('client_name')) for d in apply_page_filters(_source_rows, 'item_clients') if clean(d.get('client_name'))})
        op_unit_options = sorted({clean(d.get('operation_unit_name')) for d in apply_page_filters(_source_rows, 'op_units') if clean(d.get('operation_unit_name'))})
        bid_except_type_options = sorted({clean(d.get('bid_except_type')) for d in apply_page_filters(_source_rows, 'bid_types') if clean(d.get('bid_except_type'))})
        category_options = sorted({clean(d.get('category')) for d in apply_page_filters(_source_rows, 'categories') if clean(d.get('category'))})
        proc_status_options = sorted({clean(d.get('proc_status')) for d in apply_page_filters(_source_rows, 'proc_statuses') if clean(d.get('proc_status'))})
        mfr_name_options = sorted({clean(d.get('mfr_name')) for d in apply_page_filters(_source_rows, 'mfr_names') if clean(d.get('mfr_name'))})
        pic_options = sorted({d.get('pic') for d in apply_page_filters(_source_rows, 'pics') if d.get('pic') and d.get('pic') not in ('Unassigned', '')})

        total = len(filtered)
        # Sort in-memory
        if req_date_sort == 'newest':
            filtered.sort(key=lambda d: (1 if not d.get('req_date') else 0, d.get('req_date') or '0'), reverse=True)
        else:
            filtered.sort(key=lambda d: (1 if not d.get('req_date') else 0, d.get('req_date') or '9999', d.get('id') or 0))
        # Paginate
        start = (page - 1) * per_page
        page_rows = filtered[start:start + per_page]

        payload = {
            'data': page_rows, 'total': total, 'page': page, 'per_page': per_page,
            # V61.6: opsi interdependent (lihat apply_page_filters di atas)
            'client_options': client_options, 'op_unit_options': op_unit_options,
            'bid_except_type_options': bid_except_type_options, 'category_options': category_options,
            'pic_options': pic_options, 'proc_status_options': proc_status_options,
            'mfr_name_options': mfr_name_options,
            'missing_prod_id_by_pic': full_dataset['missing_prod_id_by_pic'],
            'last_updated': full_dataset['last_updated'],
            'sales_count': full_dataset['sales_count'], 'db_count': full_dataset['db_count'],
            'similarity_columns': full_dataset['similarity_columns'],
        }
        return jsonify(payload)
    except Exception as e:
        import traceback; traceback.print_exc()
        return jsonify({'error': str(e)}), 500
@app.route('/api/upload/item-registration-json', methods=['POST'])
@app.route('/api/upload/item-registration', methods=['POST'])
def upload_item_registration():
    try:
        deferred = try_defer_upload_job('item_registration')
        if deferred is not None: return deferred
        uploads, upload_mode = request_upload_dataframes('item_registration')
        if not uploads: return jsonify({'error': 'No file uploaded or JSON rows supplied'}), 400

        # V60z36: UPSERT mode — tidak hapus req_no lama yang tidak ada di upload baru.
        # Sebelumnya (FIX V8): pakai replace mode yang hapus semua req_no lama yang
        # tidak ada di upload terbaru. Ini menyebabkan data loss untuk:
        #   1. Item yang sedang diproses tapi belum selesai (req_no hilang dari source sheet)
        #   2. User-edit (remarks) yang sudah disimpan
        # Sekarang: pure UPSERT berdasarkan Req. No, mirip Pending Delivery (upload_smro).
        # Cleanup hanya hapus duplicates dan blank rows (valid_keys=None).
        replace_existing = False  # V60z36: changed from True to False

        summary = {'processed': 0, 'added': 0, 'updated': 0, 'removed_duplicates': 0, 'removed_stale': 0, 'removed_blank': 0}
        latest_req_numbers = set()
        for upload in uploads:
            df = upload['df']
            result = import_item_registration_dataframe(df, upload['filename'])
            latest_req_numbers.update(result.get('keys', []))
            for key in summary: summary[key] += result.get(key, 0)

        db.session.flush()
        # V60z36: Cleanup dengan valid_keys=None → hanya hapus duplicates + blank rows.
        # TIDAK hapus req_no lama yang tidak ada di upload baru (stale rows dipertahankan).
        # manual_fields=('remarks',) supaya saat ada duplicate, remarks value dipindahkan
        # ke winner row (tidak hilang).
        cleanup = cleanup_source_table_snapshot(ItemRegistration, 'req_no', None, timestamp_fields=('uploaded_at', 'updated_at'), delete_blank=True, manual_fields=('remarks',), preserve_stale_with_manual=False)
        for key, value in cleanup.items(): summary[key] = summary.get(key, 0) + value

        db.session.commit()
        clear_runtime_caches()
        # V60z33: Pre-compute all page caches in background after upload
        try:
            warmup_caches()
        except Exception as warmup_exc:
            print(f'[upload_item_registration] warmup spawn failed: {warmup_exc}')
        return jsonify({
            'message': f'Successfully uploaded {len(uploads)} Item Registration file(s) (UPSERT): +{summary["added"]} added, {summary["updated"]} updated, {summary["removed_duplicates"]} duplicates removed. Existing data preserved.',
            'uploaded': summary['processed'], 'files': len(uploads), 'mode': upload_mode, 'replace': replace_existing, **summary,
        })
    except ValueError as e:
        db.session.rollback()
        return jsonify({'error': str(e)}), 400
    except Exception as e:
        db.session.rollback()
        import traceback; traceback.print_exc()
        return jsonify({'error': str(e)}), 500

@app.route('/api/item-registration/<int:item_id>', methods=['PUT'])
def update_item_registration(item_id):
    try:
        data = request.json or {}
        item = db.session.get(ItemRegistration, item_id)
        if not item: return jsonify({'error': 'Not found'}), 404
        # V60d: Only remarks is user-editable. vendor_name, vendor_id, prod_price
        # are system-provided values from upload — read-only on the frontend.
        if 'remarks' in data: item.remarks = data['remarks'] or ''
        # FIX: bump updated_at supaya bisa dipakai untuk optimistic-concurrency
        # check di masa depan dan untuk mendeteksi stale write saat replay
        # offline queue (edit lama dari user A vs edit baru dari user B).
        item.updated_at = datetime.utcnow()
        db.session.commit()
        return jsonify({'success': True, 'updated_at': item.updated_at.isoformat() if item.updated_at else None})
    except Exception as e:
        db.session.rollback()
        return jsonify({'error': str(e)}), 500

def apply_item_registration_request_filters(query):
    search = request.args.get('search', '').strip()
    req_numbers = [n.strip() for n in request.args.getlist('req_no') if n.strip()]
    date_year, date_from, date_to = parse_so_date_args()
    clients = selected_clients()
    global_pics = [p.strip() for p in request.args.getlist('global_pic') if p.strip()]
    item_clients = [c.strip() for c in request.args.getlist('item_client') if c.strip()]
    categories = [c.strip() for c in request.args.getlist('category') if c.strip()]
    pics = [p.strip() for p in request.args.getlist('pic') if p.strip()]
    kpi_pic = (request.args.get('kpi_pic') or '').strip()
    proc_statuses = [s.strip() for s in request.args.getlist('proc_status') if s.strip()]
    mfr_names = [s.strip() for s in request.args.getlist('mfr_name') if s.strip()]
    op_units = [s.strip() for s in request.args.getlist('op_unit') if s.strip()]
    bid_types = [s.strip() for s in request.args.getlist('bid_except_type') if s.strip()]
    query = apply_item_registration_date_filter(query, date_year, date_from, date_to)
    if clients: query = query.filter(ItemRegistration.client_name.in_(clients))
    query = apply_item_registration_pic_filter(query, global_pics)
    if item_clients: query = query.filter(ItemRegistration.client_name.in_(item_clients))
    if op_units: query = query.filter(ItemRegistration.operation_unit_name.in_(op_units))
    if bid_types: query = query.filter(ItemRegistration.bid_except_type.in_(bid_types))
    if categories: query = query.filter(ItemRegistration.category.in_(categories))
    query = apply_item_registration_pic_filter(query, pics)
    if proc_statuses: query = query.filter(ItemRegistration.proc_status.in_(proc_statuses))
    if mfr_names: query = query.filter(ItemRegistration.mfr_name.in_(mfr_names))
    if req_numbers: query = query.filter(ItemRegistration.req_no.in_(req_numbers))
    if search:
        pattern = f'%{search}%'
        # V60z37: Removed vendor_name (field deleted). Added stock_no + req_owner.
        query = query.filter(db.or_(ItemRegistration.req_no.ilike(pattern), ItemRegistration.prod_id.ilike(pattern), ItemRegistration.prod_name.ilike(pattern), ItemRegistration.mfr_name.ilike(pattern), ItemRegistration.remarks.ilike(pattern), ItemRegistration.stock_no.ilike(pattern), ItemRegistration.req_owner.ilike(pattern), ItemRegistration.req_by.ilike(pattern), ItemRegistration.existing_owner.ilike(pattern)))
    if kpi_pic:
        query = apply_item_registration_pic_filter(query, [kpi_pic])
        query = apply_item_registration_kpi_status_filter(query)
        query = query.filter(db.or_(ItemRegistration.prod_id.is_(None), ItemRegistration.prod_id == '', ItemRegistration.prod_id == '-'))
    return query


@app.route('/api/item-registration/vendor-auto-approve', methods=['POST'])
def item_registration_vendor_auto_approve():
    """Vendor Auto Approve endpoint.

    FIX V41: Instead of server-side HTTP (which PythonAnywhere free tier blocks),
    generate an HTML page with auto-submit forms that execute in the USER'S
    BROWSER. This bypasses PythonAnywhere's proxy restriction — same approach
    as the Vendor Control login endpoint.

    The HTML page contains:
      1. Hidden iframes for form submits
      2. For each vendor: login form (auto-submit to iframe)
      3. For each req number: approval form (auto-submit to iframe after login)
      4. JavaScript to sequence submits with delays
      5. Visual progress log

    Limitations (due to CORS — browser cannot read cross-origin iframe content):
      - Cannot confirm if login succeeded
      - Cannot confirm if approval was processed
      - User must manually verify on Serveone Mall
    """
    try:
        data = request.get_json(silent=True) or {}
        req_numbers = data.get('req_numbers', [])
        if not req_numbers or not isinstance(req_numbers, list):
            return jsonify({'error': 'req_numbers (list) is required'}), 400

        # ── Step 1: Look up vendor info for each req_no ──────────────────
        # Get ItemRegistration rows matching the req_numbers
        req_set = {str(r).strip() for r in req_numbers if str(r).strip()}
        items = ItemRegistration.query.filter(ItemRegistration.req_no.in_(list(req_set))).all()

        # Build req_no → vendor_name map
        req_to_vendor_name = {}
        for item in items:
            vn = clean(item.vendor_name)
            if vn:
                req_to_vendor_name[str(item.req_no).strip()] = vn

        # Get Vendor Control rows (vendor_name → vendor_id + password)
        try:
            vc_rows, _ = vendor_control_rows(force=True)
        except Exception as vc_exc:
            return jsonify({'error': f'Failed to load Vendor Control data: {vc_exc}'}), 500

        # Build vendor_name_lower → {vendor_id, password, vendor_name} map
        vc_by_name = {}
        for vc in vc_rows:
            vname = clean(vc.get('vendor_name'))
            if vname:
                vc_by_name[vname.strip().lower()] = {
                    'vendor_id': clean(vc.get('vendor_id')) or '',
                    'password': clean(vc.get('password')) or '',
                    'vendor_name': vname,
                }

        # Group req_numbers by vendor_id
        # vendor_groups = {vendor_id: {'password': ..., 'vendor_name': ..., 'req_numbers': [...]}}
        vendor_groups = {}
        req_without_vendor = []
        req_without_credentials = []

        for req_no in req_set:
            vendor_name = req_to_vendor_name.get(req_no)
            if not vendor_name:
                req_without_vendor.append(req_no)
                continue
            vc_info = vc_by_name.get(vendor_name.strip().lower())
            if not vc_info or not vc_info.get('vendor_id') or not vc_info.get('password'):
                req_without_credentials.append(req_no)
                continue
            vid = vc_info['vendor_id']
            if vid not in vendor_groups:
                vendor_groups[vid] = {
                    'password': vc_info['password'],
                    'vendor_name': vc_info['vendor_name'],
                    'req_numbers': [],
                }
            vendor_groups[vid]['req_numbers'].append(req_no)

        # ── Step 2: Process each vendor SEQUENTIALLY ─────────────────────
        # Early exit if no vendors to process (all req without vendor/credentials)
        if not vendor_groups:
            return jsonify({
                'status': 'ok',
                'total_req_numbers': len(req_set),
                'vendors_processed': 0,
                'processed': [],
                'not_found': [],
                'without_vendor': req_without_vendor,
                'without_credentials': req_without_credentials,
                'vendor_results': [],
                'errors': [],
                'summary': {
                    'total': len(req_set),
                    'processed': 0,
                    'not_found': 0,
                    'without_vendor': len(req_without_vendor),
                    'without_credentials': len(req_without_credentials),
                    'errors': 0,
                },
                'error': 'No vendors to process. Check that selected req numbers have vendor_name matching Vendor Control list, and that vendor has vendor_id + password set.',
            })

        # FIX V41: Generate HTML page with auto-submit forms that execute in
        # the USER'S BROWSER. This bypasses PythonAnywhere's proxy restriction
        # — same approach as Vendor Control login endpoint.
        #
        # The HTML page contains:
        #   1. Hidden iframes for form submits
        #   2. For each vendor: login form (auto-submit to iframe)
        #   3. For each req number: approval form (auto-submit after login)
        #   4. JavaScript to sequence submits with delays
        #   5. Visual progress log
        #
        # Limitations (CORS — browser cannot read cross-origin iframe content):
        #   - Cannot confirm if login succeeded
        #   - Cannot confirm if approval was processed
        #   - User must manually verify on Serveone Mall

        # Build vendor groups data for the HTML page (exclude passwords from
        # the JSON response — they're embedded in hidden form fields only)
        vendor_groups_for_page = []
        for vid, info in vendor_groups.items():
            is_forwarder = vid.upper().startswith('FW')
            login_action = 'https://mall.serveone.id/vendor/fwdr/fwdr/doChkFirstLogin.dev?mallType=FORWARDER' if is_forwarder else 'https://mall.serveone.id/vendor/cmm/doLogin.dev?signData=noSign'
            vendor_groups_for_page.append({
                'vendor_id': vid,
                'vendor_name': info['vendor_name'],
                'password': info['password'],
                'req_numbers': info['req_numbers'],
                'login_action': login_action,
            })

        # Return JSON with page data — frontend will generate HTML and open it
        return jsonify({
            'status': 'ok',
            'total_req_numbers': len(req_set),
            'vendors_processed': len(vendor_groups),
            'without_vendor': req_without_vendor,
            'without_credentials': req_without_credentials,
            'vendor_groups': vendor_groups_for_page,
            'summary': {
                'total': len(req_set),
                'vendors': len(vendor_groups),
                'without_vendor': len(req_without_vendor),
                'without_credentials': len(req_without_credentials),
            },
            'method': 'browser-iframe',
            'note': 'Auto-approve page will open in a new tab. Forms will auto-submit in your browser. Check Serveone Mall to verify results.',
        })
    except Exception as e:
        import traceback; traceback.print_exc()
        return jsonify({'error': str(e)}), 500


