@app.route('/api/vendor-control/renew-brand-data', methods=['POST'])
def renew_brand_data():
    try:
        # Compute brand_handling from SO data
        bh_data = _compute_brand_handling()
        
        # Update all ImportVendor rows
        vendors = ImportVendor.query.all()
        updated = 0
        for v in vendors:
            vn_lower = (v.vendor_name or '').strip().lower()
            bh = bh_data.get(vn_lower, {'cheapest': [], 'all': []})
            v.brand_handling = json.dumps(bh, ensure_ascii=False)
            updated += 1
        
        db.session.commit()
        clear_runtime_caches()
        
        # Collect all unique brands for filter options
        all_brands = set()
        for bh in bh_data.values():
            all_brands.update(bh.get('all', []))
        
        return jsonify({
            'success': True,
            'vendors_updated': updated,
            'brands_found': sorted(all_brands),
            'message': f'Renewed brand data for {updated} vendors. Found {len(all_brands)} unique brands.'
        })
    except Exception as e:
        db.session.rollback()
        import traceback; traceback.print_exc()
        return jsonify({'error': str(e)}), 500

