def _style_rfq_export_sheet(ws, export_columns):
    """V62 (Task-1) — styling quotation Vendor:
    * Header POLOS (bold hitam, tanpa fill warna)          [poin 3 user]
    * Nilai kolom referensi TANPA abu-abu                  [poin 2 user]
    * Tulisan instruksional baris-1 DIHAPUS                [poin 4 user]
    * Kolom isian vendor tetap fill biru muda (panduan)."""
    last_col = len(export_columns)
    last_col_letter = get_column_letter(last_col)

    ws.freeze_panes = 'A2'
    ws.auto_filter.ref = f'A2:{last_col_letter}{ws.max_row}'

    header_font = Font(bold=True, color='000000')
    input_body_fill = PatternFill(start_color='DBEAFE', end_color='DBEAFE', fill_type='solid')
    thin_border = Border(
        left=Side(style='thin', color='D9E2EF'),
        right=Side(style='thin', color='D9E2EF'),
        top=Side(style='thin', color='D9E2EF'),
        bottom=Side(style='thin', color='D9E2EF'),
    )

    for ci, (field, label) in enumerate(export_columns, 1):
        cell = ws.cell(row=2, column=ci)
        cell.alignment = Alignment(horizontal='center', vertical='center', wrap_text=True)
        cell.border = thin_border
        cell.font = header_font

    for row in ws.iter_rows(min_row=3, max_row=ws.max_row, min_col=1, max_col=last_col):
        for ci, cell in enumerate(row, 1):
            field = export_columns[ci - 1][0]
            cell.alignment = Alignment(vertical='center', wrap_text=True)
            cell.border = thin_border
            if field in RFQ_EXPORT_INPUT_FIELDS:
                cell.fill = input_body_fill

    for ci, (field, label) in enumerate(export_columns, 1):
        ws.column_dimensions[get_column_letter(ci)].width = RFQ_EXPORT_WIDTHS.get(field, 16)

    for row_idx in range(3, ws.max_row + 1):
        ws.row_dimensions[row_idx].height = 30
    ws.row_dimensions[2].height = 26

