def import_layout_target_candidate_keys(data):
    data = data or {}
    po_sementara = clean(data.get('po_sementara'))
    so = clean(data.get('so'))
    item_yupi = clean(data.get('item_yupi'))
    po_yupi = clean(data.get('po_yupi')) or clean(data.get('yupi_po'))
    keys = []
    def add(prefix, *parts):
        parts = [clean(p) for p in parts]
        if all(parts):
            keys.append(prefix + ':' + '|'.join(p.strip().lower() for p in parts))
    add('po_sem_item_so', po_sementara, item_yupi, so)
    add('po_sem_item', po_sementara, item_yupi)
    add('po_yupi_item_so', po_yupi, item_yupi, so)
    add('po_yupi_item', po_yupi, item_yupi)
    add('so_item', so, item_yupi)
    add('po_sem', po_sementara)
    out = []
    for key in keys:
        if key not in out:
            out.append(key)
    return out

def import_layout_target_lookup(sheet_title):
    resp = google_sheets_values_get(
        IMPORT_LAYOUT_SHEET_ID,
        f"'{sheet_title}'!A2:S",
        value_render_option='FORMATTED_VALUE',
    )
    values = resp.get('values') or []
    by_key = {}
    max_row = 1
    def cell(row, one_based_idx):
        idx = one_based_idx - 1
        return row[idx] if idx < len(row) else ''
    for row_no, row_values in enumerate(values, start=2):
        if any(clean(v) for v in row_values):
            max_row = row_no
        row_data = {
            'yupi_po': cell(row_values, 5),
            'so': cell(row_values, 12),
            'po_sementara': cell(row_values, 17),
            'po_yupi': cell(row_values, 18),
            'item_yupi': cell(row_values, 19),
        }
        for key in import_layout_target_candidate_keys(row_data):
            by_key.setdefault(key, row_no)
    return {'by_key': by_key, 'max_row': max_row}

def sync_import_cells_to_layout_sheet(items):
    if not items:
        return {'synced': False, 'reason': 'No Import cells to sync'}

    field_columns = import_layout_target_field_columns()
    if not field_columns:
        return {'synced': False, 'reason': 'No Import tracker columns are mapped'}

    sheet_title = import_layout_target_sheet_title()
    lookup = import_layout_target_lookup(sheet_title)
    by_key = lookup['by_key']
    next_row = lookup['max_row'] + 1

    grouped = {}
    for item in items:
        row = item.get('row')
        field = clean(item.get('field'))
        if not row or not field:
            continue
        grouped.setdefault(row.row_key, {'row': row, 'fields': set()})['fields'].add(field)

    ranges = []
    skipped = 0
    appended = 0
    updated_rows = set()

    for group in grouped.values():
        row = group['row']
        try:
            data = json.loads(row.data_json or '{}')
        except (TypeError, json.JSONDecodeError):
            data = {}
        data = apply_import_formula_columns(dict(data))

        target_row = None
        is_new_target_row = False
        for key in import_layout_target_candidate_keys(data):
            if key in by_key:
                target_row = by_key[key]
                break
        if not target_row:
            target_row = next_row
            next_row += 1
            appended += 1
            is_new_target_row = True
            for key in import_layout_target_candidate_keys(data):
                by_key.setdefault(key, target_row)

        candidate_fields = set(data.keys()) if is_new_target_row else set(group['fields'])

        expanded_fields = set()
        for field in candidate_fields:
            mapped = import_layout_target_field_for_dashboard_field(field)
            expanded_fields.add(mapped)
            if field in ('yupi_po', 'po_yupi'):
                expanded_fields.add('po_yupi')
            if field in ('req_dlv_date', 'source_req_dlv_date'):
                expanded_fields.add('source_req_dlv_date')
            if field == 'po_send_date':
                expanded_fields.add('status')

        for field in sorted(expanded_fields):
            if field in IMPORT_LAYOUT_TARGET_FORMULA_FIELDS:
                continue
            col_letter = field_columns.get(field)
            if not col_letter:
                skipped += 1
                continue
            value = data.get(field, '')
            if field == 'po_yupi':
                value = clean(data.get('po_yupi')) or clean(data.get('yupi_po'))
            elif field == 'source_req_dlv_date':
                value = clean(data.get('source_req_dlv_date')) or clean(data.get('req_dlv_date'))
            ranges.append({
                'range': f"'{sheet_title}'!{col_letter}{target_row}",
                'values': [['' if value is None else str(value)]],
            })
            updated_rows.add(target_row)

    if not ranges:
        return {'synced': False, 'reason': 'No mapped Import tracker cells to sync', 'skipped': skipped}

    google_sheets_values_batch_update(IMPORT_LAYOUT_SHEET_ID, ranges)
    return {
        'synced': True,
        'ranges': len(ranges),
        'rows': len(updated_rows),
        'appended_rows': appended,
        'skipped': skipped,
        'spreadsheet_id': IMPORT_LAYOUT_SHEET_ID,
    }


def sync_import_cells_to_google_sheet(items):
    if os.environ.get('SERVEONE_DESKTOP_MODE') == '1':return {'synced': False, 'local_only': True, 'sheet_written': False}
    return {
        'synced': False,
        'source': {'synced': False, 'reason': 'Dashboard Import edits are local only'},
        'import_tracker': {'synced': False, 'reason': 'Dashboard Import edits are local only'},
    }

def sync_import_cell_to_google_sheet(row, field, value):
    if os.environ.get('SERVEONE_DESKTOP_MODE') == '1':return {'synced': False, 'local_only': True, 'sheet_written': False}
    result = sync_import_cells_to_google_sheet([{'row': row, 'field': field, 'value': value}])
    return result


def import_sort_date_value(value):
    raw = import_nonblank(value)
    if not raw:
        return None
    d = import_date_from_value(raw)
    if d:
        return d
    s = str(raw).strip().replace('.', '')
    for fmt in ('%d %b %Y', '%d-%b-%Y', '%d %B %Y', '%d-%B-%Y', '%Y/%m/%d', '%Y-%m-%d', '%d/%m/%Y', '%d-%m-%Y'):
        try:
            return datetime.strptime(s, fmt).date()
        except ValueError:
            pass
    for fmt in ('%d %b', '%d-%b', '%d %B', '%d-%B'):
        try:
            parsed = datetime.strptime(s, fmt)
            return date(date.today().year, parsed.month, parsed.day)
        except ValueError:
            pass
    return None

# ══════════════════════════════════════════════════════════════════════
# V61.3 — BASE CACHE IMPORT DATA (query-INdependent)
#
# AKAR MASALAH (user: "buka page import butuh >10 detik padahal tidak ada
# perubahan data"): /api/import/data lama mencache response PER QUERY-STRING
# (page/per_page/search/filter/sort) dengan TTL 300 detik. Akibatnya:
#   1. Setiap kombinasi query BARU (pindah halaman, ganti filter) = recompute
#      penuh: fetch semua row + apply_import_formula_columns per row + KPI.
#   2. Setelah 5 menit idle, query yang SAMA pun harus recompute penuh.
#   3. Worker start (WSGI reload) tidak pernah warm endpoint ini.
#   Di produksi (ribuan row + CPU PythonAnywhere yang jauh lebih lambat dari
#   dev machine) tiap cache-miss mudah melewati 10 detik.
#
# SOLUSI: pisahkan bagian MAHAL yang TIDAK tergantung query (base) dari
# bagian murah yang tergantung query (filter/sort/pagination/KPI):
#   - _build_import_base(): fetch + parse + formula + vendor-filter SEKALI,
#     simpan di runtime cache key tunggal ('import_data_base_v613'), TTL 600s,
#     di-invalidate oleh clear_runtime_caches() (dipanggil semua endpoint
#     yang mengubah data: upload, cell edit, cleanup, copy-sheet, dst).
#   - Semua request (halaman/filter/search apapun) membaca base yang sama
#     lalu memfilter di Python — belasan milidetik.
#   - Stale-while-revalidate: kalau base baru saja kedaluwarsa, request tetap
#     dilayani instan dari salinan lama sementara rebuild jalan di background.
#   - Startup warmup: warm_import_data_cache_async() + warm_all_pages_async().
# ══════════════════════════════════════════════════════════════════════

_IMPORT_BASE_REFRESH_LOCK = threading.Lock()
_IMPORT_BASE_REFRESHING = False
_IMPORT_DATA_BASE_CACHE_KEY = ('import_data_base_v613',)

def _build_import_base(force=False):
    """V61.3: Bangun base data Import — bagian MAHAL yang tidak tergantung
    query: fetch semua row visible-source, parse data_json,
    apply_import_formula_columns, filter uploaded-vendor, precompute field
    untuk filter/sort/KPI/pagination. Satu cache dipakai SEMUA request."""
    if not force:
        cached = runtime_cache_get(_IMPORT_DATA_BASE_CACHE_KEY)
        if cached is not None:
            return cached
    columns = import_layout_columns()
    _uploaded_vendor_names_cached = import_uploaded_vendor_names()
    vendor_count = len(_uploaded_vendor_names_cached)
    # Vendor Import filter di level parse — row yang vendor-nya tidak cocok
    # (fuzzy match, sama seperti sinkronisasi) tidak pernah masuk base, jadi
    # tidak tampil di table / opsi filter / KPI.
    uploaded_vendor_set_for_display = {v.strip().lower() for v in _uploaded_vendor_names_cached if v and v.strip()}
    candidate_rows = ImportDashboardRow.query.filter(
        ImportDashboardRow.source_key.in_(_IMPORT_VISIBLE_SOURCE_KEYS)
    ).order_by(
        ImportDashboardRow.first_seen_at.desc(),
        ImportDashboardRow.id.desc(),
    ).all()
    parsed = []
    for row in candidate_rows:
        try:
            data = json.loads(row.data_json or '{}')
        except (TypeError, json.JSONDecodeError):
            data = {}
        data = apply_import_formula_columns(dict(data))
        yupi = import_nonblank(data.get('yupi_po')) or import_nonblank(data.get('po_yupi'))
        vendor = import_nonblank(data.get('vendor_name')) or import_nonblank(data.get('vendor')) or import_nonblank(row.vendor_name)
        if uploaded_vendor_set_for_display:
            if not vendor or not import_vendor_match(vendor, uploaded_vendor_set_for_display):
                continue
        # ── Precompute per-item (query-independent) ──────────────────
        req_dlv_raw = import_nonblank(data.get('req_dlv_date')) or import_nonblank(data.get('source_req_dlv_date'))
        req_dlv_date = import_date_from_value(req_dlv_raw)
        eta_date = import_date_from_value(data.get('eta'))
        status_upper = str(data.get('status') or '').strip().upper()
        # Search blob — replikasi perilaku SQL ilike '%term%' lama atas
        # (row_key | source_label | vendor_name | data_json), lowercase.
        try:
            raw_json_l = (row.data_json or '').lower()
        except Exception:
            raw_json_l = ''
        search_blob = ' '.join((
            (row.row_key or '').lower(), (row.source_label or '').lower(),
            (row.vendor_name or '').lower(), raw_json_l,
        ))
        yupi_s = str(yupi or '').strip()
        # Group key pagination (raw-case — sama dengan _import_group_key lama)
        group_key = f"{yupi_s}|{str(req_dlv_raw or '').strip()}"
        # Group key KPI This-Week (lowercase — sama dengan KPI lama)
        delivery_group_key = f"{yupi_s.lower()}|{str(req_dlv_raw or '(none)').strip().lower()}"
        parsed.append({
            'row_meta': {
                '_row_key': row.row_key or '',
                '_source_key': row.source_key or '',
                '_source_label': row.source_label or '',
                '_source_uid': row.source_uid or '',
                '_sheet_row': row.sheet_row,
                '_vendor_name': row.vendor_name or '',
                '_dashboard_id': row.id,
                '_first_seen_at': utc_isoformat(row.first_seen_at) if row.first_seen_at else '',
                '_last_seen_at': utc_isoformat(row.last_seen_at) if row.last_seen_at else '',
                '_updated_at': utc_isoformat(row.updated_at) if row.updated_at else '',
            },
            'data': data,
            'yupi_po': yupi,
            'vendor': vendor,
            'yupi_po_l': yupi_s.lower(),
            'search_blob': search_blob,
            'group_key': group_key,
            'delivery_group_key': delivery_group_key,
            'req_dlv_date': req_dlv_date,
            'eta_date': eta_date,
            'status_upper': status_upper,
            'is_new_like': status_upper in ('', 'NEW'),
            'amount_f': import_float_value(data.get('amount')),
            'purchase_amount_f': import_float_value(data.get('purchase_amount')),
            'purchase_price_f': import_float_value(data.get('purchase_price')),
            'ord_qty_f': import_float_value(data.get('ord_qty')),
            'currency': (clean(data.get('currency')) or 'IDR').strip().upper(),
            'sap_input': import_normalize_checkbox(import_nonblank(data.get('sap_input'))),
        })
    base = {'columns': columns, 'vendor_count': vendor_count, 'parsed': parsed}
    runtime_cache_set(_IMPORT_DATA_BASE_CACHE_KEY, base, ttl_seconds=600)
    return base

def _import_base_get(force=False):
    """V61.3: Ambil base Import — satu cache untuk SEMUA query. Kalau base
    baru saja kedaluwarsa (TTL 600s lewat tanpa perubahan data), layani
    salinan lama secara instan (stale-while-revalidate) sementara rebuild
    berjalan sekali di background — user tidak pernah menunggu rebuild."""
    global _IMPORT_BASE_REFRESHING
    if force:
        return _build_import_base(force=True)
    # V61.5: thread rebuild/warmup (SWR replay) WAJIB menghitung ulang base —
    # bukan menyajikan stale lalu men-spawn rebuild lain (dulu: warmup pasca
    # invalidasi lembut menulis response dari base LAMA).
    if getattr(_SWR_FORCE_LOCAL, 'on', False):
        return _build_import_base(force=True)
    with _READ_CACHE_LOCK:
        item = _READ_RESPONSE_CACHE.get(_IMPORT_DATA_BASE_CACHE_KEY)
    if item is not None:
        expires_at, payload = item
        if expires_at > datetime.utcnow():
            return payload
        # Kedaluwarsa tapi salinan masih ada → instan + rebuild background.
        with _IMPORT_BASE_REFRESH_LOCK:
            already_refreshing = _IMPORT_BASE_REFRESHING
            if not already_refreshing:
                _IMPORT_BASE_REFRESHING = True
        if not already_refreshing:
            def _bg_rebuild():
                global _IMPORT_BASE_REFRESHING
                try:
                    with app.app_context():
                        _build_import_base(force=True)
                except Exception as exc:
                    print(f'[import/base] background rebuild failed: {exc}', flush=True)
                finally:
                    with _IMPORT_BASE_REFRESH_LOCK:
                        _IMPORT_BASE_REFRESHING = False
            threading.Thread(target=_bg_rebuild, daemon=True, name='import-base-rebuild').start()
        return payload
    return _build_import_base(force=True)

@app.route('/api/import/data', methods=['GET'])
def get_import_data():
    try:
        force = str(request.args.get('refresh', '')).lower() in ('1', 'true', 'yes')
        # V61.3: response cache per query-string kini hanya bonus untuk repeat
        # identik — semua kerja berat sudah pindah ke base cache, jadi cache
        # miss pun hanya belasan milidetik.
        cache_key = runtime_cache_key('import_data')
        if not force:
            cached = runtime_cache_get_swr(cache_key, request.full_path)
            if cached is not None:
                return jsonify(cached)
        page = max(int(request.args.get('page', 1)), 1)
        per_page = min(max(int(request.args.get('per_page', 25)), 1), 500)
        search = clean(request.args.get('search')) or ''
        selected_yupi_po = [clean(v) for v in request.args.getlist('yupi_po') if clean(v)]
        selected_vendors = [clean(v) for v in request.args.getlist('vendor_name') if clean(v)]
        # NEW: status filter (NEW / ON PROCESS / ON DELIVERY / DELIVERED / CANCELED)
        selected_statuses = [clean(v) for v in request.args.getlist('status') if clean(v)]
        # NEW: days_left color filter (red / yellow / green / today) — supports
        # multiple values via getlist so the user can filter by 2+ zones.
        selected_days_left = [clean(v).lower() for v in request.args.getlist('days_left') if clean(v)]
        # NEW: "This Week Arrival" filter — when '1', only show rows whose ETA
        # falls within the current ISO week (Mon–Sun, WIB timezone). Triggered
        # by clicking the "This Week Arrival" KPI card on the Import page.
        this_week_arrival_filter = str(request.args.get('this_week_arrival', '')).lower() in ('1', 'true', 'yes')
        req_dlv_sort = str(clean(request.args.get('req_dlv_sort')) or '').lower() or 'oldest'
        if req_dlv_sort not in ('oldest', 'newest'):
            req_dlv_sort = 'oldest'
        yupi_po_sort_val = clean(request.args.get('yupi_po_sort'))
        yupi_po_sort = str(yupi_po_sort_val).lower() if yupi_po_sort_val else ''
        if yupi_po_sort not in ('asc', 'desc'):
            yupi_po_sort = ''
        none_yupi_po = any(v == '__NONE_PLACEHOLDER__' for v in selected_yupi_po)
        none_vendor = any(v == '__NONE_PLACEHOLDER__' for v in selected_vendors)
        selected_yupi_po = {v.strip().lower() for v in selected_yupi_po if v != '__NONE_PLACEHOLDER__'}
        selected_vendors = {v.strip().lower() for v in selected_vendors if v != '__NONE_PLACEHOLDER__'}
        # Normalize selected statuses (uppercase) for case-insensitive comparison.
        selected_status_set = {str(v).strip().upper() for v in selected_statuses if v}
        # Pre-compute the current ISO week (Mon–Sun) in WIB timezone. Used by
        # BOTH the "This Week Arrival" filter (in passes()) and the KPI counter
        # below. Computed once here so the filter and KPI use the SAME window.
        _today_wib_for_week = (datetime.utcnow() + timedelta(hours=7)).date()
        week_start = _today_wib_for_week - timedelta(days=_today_wib_for_week.weekday())  # Monday
        week_end = week_start + timedelta(days=6)  # Sunday
        sync_info = None

        if force and os.environ.get('SERVEONE_DESKTOP_MODE') == '1':
            # Refresh only local SQLite response cache; never contact Google Sheets.
            clear_runtime_caches()
            force = False
        elif force:
            sync_info = sync_import_sheet_to_dashboard()
            # V60z33: After Manual Update (sync), pre-compute all page caches
            # in background so user doesn't wait when navigating to other pages.
            try:
                warmup_caches()
            except Exception as warmup_exc:
                print(f'[import/data] warmup spawn failed: {warmup_exc}')

        # ── V61.3: BASE CACHE — semua kerja berat (fetch+parse+formula) ──
        # Satu cache query-independent dipakai SEMUA kombinasi halaman /
        # filter / search. Data berubah → clear_runtime_caches() menghapus
        # base → request berikutnya rebuild sekali (paling lama ~1x penuh),
        # sisanya instan.
        base = _import_base_get(force=force)
        columns = sync_info['columns'] if sync_info else base['columns']
        vendor_count = sync_info.get('vendor_count') if sync_info else base['vendor_count']
        parsed_all = base['parsed']

        # Search — dulu SQL ilike per query (bagian dari penyebab lambat);
        # sekarang Python-side di atas search_blob yang sudah precomputed.
        # Multi-term: AND (semua term harus ada), sama seperti SQL lama.
        if search:
            terms = [t.strip().lower() for t in re.split(r'[\n,]+', search) if t.strip()]
            if terms:
                parsed_all = [it for it in parsed_all if all(t in it['search_blob'] for t in terms)]
        parsed = parsed_all

        def passes(item, ignore=None):
            if none_yupi_po or none_vendor:
                return False
            if ignore != 'yupi_po' and selected_yupi_po and str(item.get('yupi_po') or '').strip().lower() not in selected_yupi_po:
                return False
            if ignore != 'vendor' and selected_vendors and str(item.get('vendor') or '').strip().lower() not in selected_vendors:
                return False
            # NEW: "This Week Arrival" filter — only show rows whose ETA falls
            # within the current ISO week (Mon–Sun, WIB timezone). Same week
            # boundaries as the KPI counter in this endpoint. V61.3: pakai
            # eta_date precomputed di base (tanpa parse ulang per request).
            if ignore != 'this_week_arrival' and this_week_arrival_filter:
                eta_date = item.get('eta_date')
                if not eta_date or not (week_start <= eta_date <= week_end):
                    return False
            # NEW: status filter. Status is computed by apply_import_formula_columns
            # and stored at item['status_upper'] (precomputed di base).
            if ignore != 'status' and selected_status_set:
                row_status = item.get('status_upper')
                if row_status not in selected_status_set:
                    return False
            # NEW: days_left color filter. days_left is computed by
            # apply_import_formula_columns. Values: '✅', '❌', '', or a number
            # string (can be negative). Color zones match the frontend:
            #   red    → <= 7 or negative
            #   yellow → 8–29
            #   green  → >= 30
            #   today  → exactly 0
            # Supports MULTIPLE zones — row passes if it matches ANY selected
            # zone. empty selected_days_left → no filter.
            if ignore != 'days_left' and selected_days_left:
                raw = str((item.get('data') or {}).get('days_left') or '').strip()
                if raw in ('✅', '❌', '', '-'):
                    return False  # icon/empty rows don't match any color zone
                try:
                    dl = int(float(raw))
                except (ValueError, TypeError):
                    return False
                matched = False
                for zone in selected_days_left:
                    if zone == 'red' and (dl < 0 or dl <= 7):
                        matched = True; break
                    if zone == 'yellow' and 8 <= dl <= 29:
                        matched = True; break
                    if zone == 'green' and dl >= 30:
                        matched = True; break
                    if zone == 'today' and dl == 0:
                        matched = True; break
                if not matched:
                    return False
            return True

        filtered_items = [item for item in parsed if passes(item)]

        # FIX V10 (tetap): cache hasil passes() per item — options loop
        # memanggil passes 4x per item dengan varian ignore berbeda.
        _passes_cache = {}
        def passes_cached(item, ignore=None):
            cache_key = (id(item), ignore)
            if cache_key not in _passes_cache:
                _passes_cache[cache_key] = passes(item, ignore=ignore)
            return _passes_cache[cache_key]

        # ── Interdependent filter options ────────────────────────────────
        # Each filter's option list is built from rows that pass ALL OTHER
        # filters (but not itself). This matches the user's expectation:
        # "jika tidak ada status yang new maka di drop down filternya tidak
        # ada pilihan new".
        yupi_options = sorted({str(item.get('yupi_po') or '').strip() for item in parsed if str(item.get('yupi_po') or '').strip() and passes_cached(item, ignore='yupi_po')}, key=lambda s: s.lower())
        vendor_options = sorted({str(item.get('vendor') or '').strip() for item in parsed if str(item.get('vendor') or '').strip() and passes_cached(item, ignore='vendor')}, key=lambda s: s.lower())
        # Status options — built from rows that pass all filters EXCEPT status.
        # Only statuses that actually appear in the (otherwise-filtered) data
        # are listed. NEW is included only if a row's status computed to NEW.
        status_options = sorted({item.get('status_upper') for item in parsed if item.get('status_upper') and passes_cached(item, ignore='status')}, key=lambda s: s.lower())
        # Days Left color options — built from rows that pass all filters
        # EXCEPT days_left. Only color zones that actually appear are listed.
        days_left_zone_options = []
        _dl_zones_seen = set()
        for item in parsed:
            if not passes_cached(item, ignore='days_left'): continue
            raw = str((item.get('data') or {}).get('days_left') or '').strip()
            if raw in ('✅', '❌', '', '-'): continue
            try: dl = int(float(raw))
            except (ValueError, TypeError): continue
            if dl < 0 or dl <= 7: zone = 'red'
            elif 8 <= dl <= 29: zone = 'yellow'
            elif dl >= 30: zone = 'green'
            elif dl == 0: zone = 'today'
            else: continue
            if zone not in _dl_zones_seen:
                _dl_zones_seen.add(zone)
                days_left_zone_options.append(zone)
        # Sort: red, yellow, green, today (consistent order)
        _zone_order = {'red': 0, 'yellow': 1, 'green': 2, 'today': 3}
        days_left_zone_options.sort(key=lambda z: _zone_order.get(z, 99))

        # ── Sort (V61.3: pakai field precomputed di base — tanpa parse
        # tanggal ulang tiap request) ─────────────────────────────────
        # V60k: NEW status = TOP PRIORITY. PO belum di-create (no po_send_date)
        # → top of list, ignore req_dlv_date. Once user fills PO Send Date
        # and status becomes ON PROCESS → sort normally by req_dlv_date.
        # FIX V53: Empty dates sort FIRST (top of list), not last.
        def _import_req_date_key(item):
            status_priority = 0 if item.get('status_upper') == 'NEW' else 1
            d = item.get('req_dlv_date')
            if d is None:
                date_ord = -1
            else:
                date_ord = d.toordinal() if req_dlv_sort == 'oldest' else -d.toordinal()
            return (status_priority, 0, date_ord, item.get('yupi_po_l') or '')

        if yupi_po_sort:
            filtered_items.sort(key=_import_req_date_key)
            # FIX V53: If yupi_po_sort is 'desc', re-sort by yupi_po descending
            # but ONLY within same (status_priority + date) group, preserving
            # the main ordering.
            if yupi_po_sort == 'desc':
                _groups = {}
                for item in filtered_items:
                    k = _import_req_date_key(item)[:3]
                    _groups.setdefault(k, []).append(item)
                filtered_items = []
                for k in sorted(_groups.keys()):
                    group = _groups[k]
                    group.sort(key=lambda item: item.get('yupi_po_l') or '', reverse=True)
                    filtered_items.extend(group)
        else:
            filtered_items.sort(key=_import_req_date_key)

        # ── FIX V16: Paginate by YUPI PO GROUP, not by raw row ──────────
        # User spec: "1 Yupi PO (termasuk yang di-merge) itu dihitung 1 data,
        # artinya kalau dipilih 10 maka harusnya ada 10 yupi PO."
        # Frontend merges adjacent rows sharing (yupi_po + req_dlv_date) via
        # rowSpan. Group key precomputed di base ('group_key'), item dengan
        # yupi_po kosong diperlakukan sebagai 1-item group.
        sorted_items = filtered_items

        # Build groups of consecutive same-key items.
        groups = []
        current_group = []
        current_key = None
        for item in sorted_items:
            yupi = str(item.get('yupi_po') or '').strip()
            if not yupi:
                # Blank yupi_po → standalone 1-row group (tidak di-merge).
                if current_group:
                    groups.append(current_group)
                groups.append([item])
                current_group = []
                current_key = None
                continue
            key = item.get('group_key')
            if current_key is None or key != current_key:
                if current_group:
                    groups.append(current_group)
                current_group = [item]
                current_key = key
            else:
                current_group.append(item)
        if current_group:
            groups.append(current_group)

        # FIX V16: total = jumlah Yupi PO group, BUKAN jumlah raw row.
        total = len(groups)
        # Slice by group, lalu flatten ke rows. per_page=10 → 10 Yupi PO groups.
        page_groups = groups[(page - 1) * per_page : page * per_page]
        page_items = [item for group in page_groups for item in group]
        # V61.3: bangun output row dari snapshot precomputed di base
        # (row_meta + data) — tanpa query ORM & tanpa apply formula ulang.
        vendor_attrs_map = import_vendor_attrs_map()
        rows = []
        for item in page_items:
            data = item['data']
            out = {}
            for col in columns:
                f = col.get('field')
                v = data.get(f)
                out[f] = '' if v is None else v
            # Suntik atribut vendor (Origin/TOP/Non SKI) dari ImportVendor —
            # perilaku identik dengan import_dashboard_row_to_dict versi lama.
            if vendor_attrs_map:
                row_vendor = item.get('vendor')
                if row_vendor:
                    attrs = vendor_attrs_map.get(str(row_vendor).strip().lower())
                    if attrs:
                        if not import_nonblank(data.get('origin')):
                            out['origin'] = attrs.get('origin') or ''
                        if not import_nonblank(data.get('top')):
                            out['top'] = attrs.get('top') or ''
                        if not import_nonblank(data.get('non_ski')):
                            out['non_ski'] = attrs.get('non_ski') or ''
            out.update(item['row_meta'])
            out['_req_dlv_date_manual'] = clean(data.get('_req_dlv_date_manual'))
            rows.append(out)

        # ── FIX V24: Inject "total_purchase_amount" (sum of purchase_amount
        # per YUPI PO group) into each row's data dict. Computed across ALL
        # filtered_items (not just this page) supaya angka total stabil walau
        # user pindah halaman. FIX V37: group by YUPI PO ONLY.
        try:
            _group_totals = {}
            for item in filtered_items:
                yupi = str(item.get('yupi_po') or '').strip()
                if not yupi:
                    continue
                group_key = yupi.lower()
                # FIX V36: purchase_amount mungkin kosong di parsed data karena
                # apply_import_formula_columns hanya compute jika purchase_price
                # DAN ord_qty keduanya non-empty. Kalau tidak, recompute dari
                # purchase_price * ord_qty (semuanya sudah precomputed di base).
                pa = item.get('purchase_amount_f')
                if pa is None:
                    price = item.get('purchase_price_f')
                    qty = item.get('ord_qty_f')
                    if price is not None and qty is not None:
                        pa = price * qty
                if pa is not None:
                    _group_totals[group_key] = _group_totals.get(group_key, 0.0) + pa
            # Inject into rows
            for row in rows:
                yupi = str(row.get('yupi_po') or '').strip()
                if not yupi:
                    row['total_purchase_amount'] = ''
                    continue
                group_key = yupi.lower()
                if group_key in _group_totals:
                    row['total_purchase_amount'] = import_format_number(_group_totals[group_key])
                else:
                    # FIX V36: Group tidak ada di _group_totals = tidak ada item
                    # dengan purchase_amount/price*qty. Coba recompute dari row
                    # ini sendiri (mungkin ini satu-satunya item di group).
                    pa = import_float_value(row.get('purchase_amount'))
                    if pa is None:
                        price = import_float_value(row.get('purchase_price'))
                        qty = import_float_value(row.get('ord_qty'))
                        if price is not None and qty is not None:
                            pa = price * qty
                    row['total_purchase_amount'] = import_format_number(pa) if pa is not None else ''
        except Exception as _tota_exc:
            import traceback; traceback.print_exc()
            for row in rows:
                row['total_purchase_amount'] = ''

        # ── KPIs ───────────────────────────────────────────────────────
        # Computed across ALL filtered rows (not just the current page), semua
        # dari field precomputed di base (float & date sudah di-parse):
        #  - Total PO           : count of distinct YUPI POs
        #  - This Week Arrival  : unique delivery group (yupi_po + req_dlv_date)
        #    arriving this week; sub-KPI: without SAP INPUT.
        #  - Sales Amount       : sum of AMOUNT column across filtered rows.
        #  - PO Amount (IDR)    : sum of PURCHASE AMOUNT converted to IDR using
        #    the exchange rate for the row's ETA date.
        #  - Gross Margin       : Sales Amount − PO Amount (IDR).
        # V63.12: dulu SEMUA di atas dibungkus SATU try — cukup SATU baris
        # EUR dengan kurs None (tabel exchange_rate_fx kosong pasca-recovery)
        # -> TypeError `pa * None` -> SEMUA kartu KPI 0 padahal tabel berisi
        # data ("ada data harga EUR dan USD tapi kpi 0"). Kini dipecah 3 try:
        # (A) hitungan baris, (B) prefetch+konversi FX, (C) margin+payload —
        # masalah kurs tidak lagi bisa menolkan KPI hitungan.
        _kpi_error = None
        _fx_missing = 0
        total_po = 0
        this_week_arrival = 0
        this_week_no_sap = 0
        sales_amount_total = 0.0
        po_amount_idr_total = 0.0
        seen_yupi_pos = set()
        this_week_arrival_groups = set()
        this_week_groups_with_sap = set()
        eta_dates_usd_eur = set()
        try:  # (A) hitungan — tanpa konversi kurs
            for item in filtered_items:
                yupi = item.get('yupi_po')
                if yupi:
                    seen_yupi_pos.add(item.get('yupi_po_l') or str(yupi).strip().lower())
                eta_date = item.get('eta_date')
                if eta_date and week_start <= eta_date <= week_end:
                    if yupi:
                        # FIX V34: counting key = (yupi_po + req_dlv_date).
                        this_week_arrival_groups.add(item.get('delivery_group_key'))
                        # SAP INPUT checkbox — 'TRUE' = checked.
                        if item.get('sap_input') == 'TRUE':
                            this_week_groups_with_sap.add(item.get('delivery_group_key'))
                # Sales Amount = AMOUNT column
                amt = item.get('amount_f')
                if amt is not None:
                    sales_amount_total += amt
                # PO Amount (IDR) = PURCHASE AMOUNT converted using ETA-date FX rate
                pa = item.get('purchase_amount_f')
                if pa is not None and pa > 0:
                    cur = item.get('currency') or 'IDR'
                    if cur in ('', 'IDR'):
                        po_amount_idr_total += pa
                    elif cur in ('USD', 'EUR') and eta_date:
                        eta_dates_usd_eur.add((cur, eta_date))
            total_po = len(seen_yupi_pos)
            this_week_arrival = len(this_week_arrival_groups)
            this_week_no_sap = len(this_week_arrival_groups - this_week_groups_with_sap)
        except Exception as kpi_exc:
            import traceback; traceback.print_exc()
            _kpi_error = f'count: {kpi_exc}'
        try:  # (B) prefetch + konversi FX — gagal di sini TIDAK menolkan (A)
            for cur in ('USD', 'EUR'):
                dates_for_cur = sorted({d for c, d in eta_dates_usd_eur if c == cur})
                if dates_for_cur:
                    # V63.11: fetch kurs yang hilang (capped 40 tanggal/call, 8
                    # worker, hanya tanggal <= hari ini, hasil disimpan ke DB).
                    # Dulu fetch_missing=False — setelah recovery mengosongkan
                    # tabel exchange_rate_fx, PO Amount (IDR) & Gross Margin
                    # selamanya 0 karena cache_only tidak pernah mengisi ulang.
                    prefetch_exchange_rates(dates_for_cur, fetch_missing=True, currency=cur)
            # Now compute PO Amount (IDR) per row using cached rates.
            for item in filtered_items:
                pa = item.get('purchase_amount_f')
                if pa is None or pa <= 0: continue
                cur = item.get('currency') or 'IDR'
                if cur in ('', 'IDR'):
                    continue  # already added above
                eta_date = item.get('eta_date')
                if cur in ('USD', 'EUR') and eta_date:
                    rate = get_currency_to_idr(cur, eta_date, cache_only=True)
                    # V63.12: rate BISA None (kontrak get_currency_to_idr) —
                    # dulu `pa * rate` tanpa guard = TypeError = SEMUA KPI 0.
                    if rate:
                        po_amount_idr_total += pa * rate
                    else:
                        _fx_missing += 1
        except Exception as fx_exc:
            import traceback; traceback.print_exc()
            _kpi_error = (_kpi_error + ' | ' if _kpi_error else '') + f'fx: {fx_exc}'
        # (C) margin + payload — selalu punya angka (A) walau (B) gagal.
        if po_amount_idr_total > 0:
            gross_margin = sales_amount_total - po_amount_idr_total
        else:
            gross_margin = 0.0
        kpis = {
            'total_po': total_po,
            'this_week_arrival': this_week_arrival,
            'this_week_no_sap': this_week_no_sap,
            'sales_amount': round(sales_amount_total, 2),
            'po_amount_idr': round(po_amount_idr_total, 2),
            'gross_margin': round(gross_margin, 2),
            'fx_missing_rows': _fx_missing,
        }
        if _kpi_error:
            kpis['error'] = _kpi_error

        last_copy_at = import_meta_get('last_copy_at') or ''

        payload = {
            'data': rows,
            'columns': columns,
            'total': total,
            'page': page,
            'per_page': per_page,
            'vendor_count': vendor_count,
            'last_copy_at': last_copy_at,
            'filters': {
                'yupi_po': yupi_options,
                'vendors': vendor_options,
                # Interdependent filter options — only show values that
                # actually exist in the (otherwise-filtered) data.
                'statuses': status_options,
                'days_left_zones': days_left_zone_options,
            },
            'req_dlv_sort': req_dlv_sort,
            'yupi_po_sort': yupi_po_sort,
            'sources': [{'key': s['key'], 'label': s['label']} for s in IMPORT_SOURCE_SHEETS],
            'sync': sync_info,
            'kpis': kpis,
        }
        # V61.3: response cache hanya bonus repeat-identik (build kini murah).
        runtime_cache_set(cache_key, payload, ttl_seconds=120)
        return jsonify(payload)
    except Exception as e:
        db.session.rollback()
        import traceback; traceback.print_exc()
        return jsonify({'error': str(e)}), 500

@app.route('/api/import/debug-source', methods=['GET'])
def import_debug_source():
    try:
        source_key = clean(request.args.get('source')) or 'source_1'
        vendor_filter = clean(request.args.get('vendor')) or ''
        source = next((s for s in IMPORT_SOURCE_SHEETS if s['key'] == source_key), None)
        if not source:
            return jsonify({
                'error': f"Unknown source key '{source_key}'",
                'available_sources': [s['key'] for s in IMPORT_SOURCE_SHEETS],
            }), 400

        columns = import_layout_columns()
        mapping_columns = import_all_mapping_columns(columns)
        sheet_title, header_df = import_source_header_preview(source, force=True)
        if header_df.empty:
            return jsonify({
                'error': 'Could not read a usable header preview for this source (empty result).',
                'sheet_title_tried': sheet_title,
                'spreadsheet_id': source['spreadsheet_id'],
            }), 500

        header_idx = import_detect_header_row(header_df)
        kind = import_source_kind_from_header(header_df, header_idx)
        source_map = import_source_column_map(header_df, mapping_columns)
        header_row_values = [clean(v) for v in header_df.iloc[header_idx].tolist()] if len(header_df) else []

        source_map_letters = {}
        for field, idx in source_map.items():
            try:
                source_map_letters[field] = column_letter_from_index(idx + 1)
            except Exception:
                source_map_letters[field] = f'(idx {idx})'

        if vendor_filter:
            vendor_set = {vendor_filter.strip().lower()}
        else:
            filter_vendors, _ = import_vendor_filter_names()
            vendor_set = {v.strip().lower() for v in filter_vendors}

        sample_rows = import_source_rows_fast(source, columns, vendor_set)[:5]
        sample_out = []
        for row in sample_rows:
            sample_out.append({
                'sheet_row': row.get('_sheet_row'),
                'vendor_name_detected': row.get('_vendor_name'),
                'po_yupi': row.get('po_yupi'),
                'yupi_po': row.get('yupi_po'),
                'po_sementara': row.get('po_sementara'),
                'req_dlv_date': row.get('req_dlv_date'),
                'po_date_by_email': row.get('po_date_by_email'),
                'etd': row.get('etd'),
                'eta': row.get('eta'),
                'so': row.get('so'),
                'group': row.get('group'),
                'item_name': row.get('item_name'),
            })

        return jsonify({
            'source_key': source['key'],
            'spreadsheet_id': source['spreadsheet_id'],
            'sheet_title_used': sheet_title,
            'detected_header_row_1based': header_idx + 1,
            'detected_kind': kind or '(none -> common fallback letters used)',
            'header_row_raw_values': header_row_values,
            'column_map_field_to_letter': source_map_letters,
            'vendor_fallback_letters': list(IMPORT_FALLBACK_SOURCE_VENDOR_LETTERS),
            'vendor_filter_used': sorted(vendor_set),
            'matched_row_count': len(sample_rows),
            'sample_rows': sample_out,
            # FIX V9: tambah hint troubleshooting kalau matched_row_count = 0
            'troubleshooting': (
                "Jika matched_row_count=0 padahal sheet ada data: "
                "(1) Cek vendor_filter_used — pastikan vendor yang diupload persis match "
                "atau jadi prefix dari vendor di sheet. "
                "(2) Cek header_row_raw_values — pastikan header row terdeteksi benar "
                "(mis. 'Vendor Name', 'PO YUPI', 'PO DATE By Email'). "
                "(3) Cek column_map_field_to_letter — vendor_name dan po_yupi harus terpetakan. "
                "(4) Fuzzy matching aktif: 'CURT GEORGI GMBH & CO' akan match dengan "
                "'CURT GEORGI GMBH & CO. KG' (prefix match)."
            ),
        })
    except Exception as e:
        import traceback; traceback.print_exc()
        return jsonify({'error': str(e)}), 500


@app.route('/api/admin/cleanup-import-duplicates', methods=['POST'])
def admin_cleanup_import_duplicates():
    """Auto-cleanup duplicate rows di Import Dashboard.

    FIX V10 (CORRECTED): HANYA hapus row yang 100% IDENTICAL (semua field bisnis
    sama, termasuk req_dlv_date, item_yupi, dll). JANGAN hapus row hanya karena
    po_yupi + item_yupi sama — 1 PO bisa punya multiple item dengan Req Dlv Date
    berbeda (reschedule history), itu entry valid yang harus dipertahankan.

    Logika:
    1. Build fingerprint dari semua field bisnis (IMPORT_LOCAL_EDIT_FIELDS) yang tidak kosong
    2. Group rows by fingerprint
    3. Kalau ada >1 row dengan fingerprint sama (100% identical):
       a. Keep row dengan id terkecil (paling lama, paling stabil)
       b. Hapus row lain
    4. Return summary

    Return:
    - total_rows_before: jumlah row sebelum cleanup
    - total_rows_after: jumlah row setelah cleanup
    - identical_duplicate_groups: jumlah group yang 100% identical
    - deleted_count: jumlah row yang dihapus
    """
    try:
        all_rows = ImportDashboardRow.query.filter(
            ImportDashboardRow.source_key.in_(_IMPORT_VISIBLE_SOURCE_KEYS)
        ).all()

        # Group by FULL data fingerprint (semua field bisnis sama = true identical duplicate)
        by_fingerprint = {}
        for row in all_rows:
            try: data = json.loads(row.data_json or '{}')
            except: data = {}
            # Build fingerprint dari semua field bisnis yang tidak kosong
            biz_fields = {k: v for k, v in data.items()
                          if k in IMPORT_LOCAL_EDIT_FIELDS and not import_blankish(v)}
            fingerprint = json.dumps(biz_fields, ensure_ascii=False, sort_keys=True, separators=(',', ':'))
            by_fingerprint.setdefault(fingerprint, []).append(row)

        # Find groups with identical duplicates
        duplicate_groups = 0
        deleted_count = 0
        details = []

        for fingerprint, rows in by_fingerprint.items():
            if len(rows) <= 1: continue  # no duplicate

            # Sort by id asc (keep paling lama = id terkecil)
            rows.sort(key=lambda x: x.id)
            winner = rows[0]
            losers = rows[1:]

            # Hapus losers (100% identical, tidak perlu merge karena datanya sama persis)
            deleted_row_keys = []
            for loser in losers:
                deleted_row_keys.append(loser.row_key)
                db.session.delete(loser)
                deleted_count += 1

            duplicate_groups += 1
            try: winner_data = json.loads(winner.data_json or '{}')
            except: winner_data = {}
            details.append({
                'po_yupi': clean(winner_data.get('po_yupi')) or clean(winner_data.get('yupi_po')) or '',
                'item_yupi': clean(winner_data.get('item_yupi')) or '',
                'req_dlv_date': clean(winner_data.get('req_dlv_date')) or '',
                'kept_row_key': winner.row_key,
                'deleted_row_keys': deleted_row_keys,
                'note': '100% identical — semua field bisnis sama',
            })

        # Commit changes
        if deleted_count > 0:
            db.session.commit()
            _checkpoint_and_backup_db('delete_rows')
            db.session.commit()
            clear_runtime_caches()

        total_rows_after = ImportDashboardRow.query.filter(
            ImportDashboardRow.source_key.in_(_IMPORT_VISIBLE_SOURCE_KEYS)
        ).count()

        return jsonify({
            'success': True,
            'total_rows_before': len(all_rows),
            'total_rows_after': total_rows_after,
            'identical_duplicate_groups': duplicate_groups,
            'deleted_count': deleted_count,
            'details': details[:50],
            'message': f'Cleanup selesai: {deleted_count} identical duplicate row dihapus (hanya row dengan 100% field sama). Sisa: {total_rows_after} rows.',
            'note': 'HANYA row yang 100% identical (semua field bisnis sama) yang dihapus. Row dengan po_yupi sama tapi req_dlv_date/item_yupi berbeda DIPERTAHANKAN.',
        })
    except Exception as e:
        db.session.rollback()
        import traceback; traceback.print_exc()
        return jsonify({'error': str(e)}), 500


@app.route('/api/admin/force-cleanup-import-duplicates', methods=['POST'])
def admin_force_cleanup_import_duplicates():
    """Force cleanup SEMUA jenis duplikat di Import Dashboard.

    Endpoint ini menjalankan FASE -1, FASE 0, FASE 1, dan FASE 2 secara BERURUTAN
    dengan output detail (row id, source_uid, fields yang di-merge) supaya user
    bisa lihat persis apa yang dihapus. Berbeda dengan cleanup-import-duplicates
    (hanya 100% identical), endpoint ini juga tangkap:
      - Duplikat dengan source_uid sama (qty/price drift)
      - Duplikat dengan identity sama (po_yupi + item_yupi + po_sementara)
      - Excess rows (lebih banyak dari sheet)
      - Stale leftovers (row dengan last_seen_at lama yang tidak di-touch sync terbaru)

    Query params:
    - po_yupi (optional): filter hanya PO tertentu, mis. ?po_yupi=410100147

    Returns:
    - total_before, total_after
    - phase_-1_purged (biz-identity dup)
    - phase_0_purged (source_uid dup)
    - phase_1_purged (src_fingerprint dup)
    - phase_2_purged (excess count)
    - phase_3_purged (stale leftovers)
    - details: list of {phase, loser_id, winner_id, key, fields_merged}
    """
    try:
        target_po = clean(request.args.get('po_yupi')) or ''
        target_po_upper = target_po.strip().upper() if target_po else ''

        all_rows = ImportDashboardRow.query.filter(
            ImportDashboardRow.source_key.in_(_IMPORT_VISIBLE_SOURCE_KEYS)
        ).order_by(ImportDashboardRow.id.asc()).all()

        # Cache parsed data
        db_row_data = {}
        for row in all_rows:
            try: db_row_data[row.id] = json.loads(row.data_json or '{}')
            except: db_row_data[row.id] = {}

        # Filter by target PO jika ada
        if target_po_upper:
            filtered_rows = []
            for r in all_rows:
                d = db_row_data.get(r.id, {})
                po = (import_nonblank(d.get('po_yupi')) or import_nonblank(d.get('yupi_po')) or '').strip().upper()
                if po == target_po_upper:
                    filtered_rows.append(r)
            all_rows = filtered_rows

        def _user_richness(data):
            return sum(1 for f in IMPORT_USER_LOCAL_ONLY_FIELDS if not import_blankish(data.get(f)))

        _SRC_FP_EXCLUDE_FIELDS = {'so'}
        def _src_fingerprint(data):
            src = {k: (data.get(k) or '').strip().upper()
                   for k in IMPORT_SOURCE_MANAGED_FIELDS
                   if k not in _SRC_FP_EXCLUDE_FIELDS and not import_blankish(data.get(k))}
            return json.dumps(src, ensure_ascii=False, sort_keys=True, separators=(',', ':'))

        def _biz_identity(data):
            po = (import_nonblank(data.get('po_yupi')) or import_nonblank(data.get('yupi_po')) or '').strip().upper()
            item = (import_nonblank(data.get('item_yupi')) or '').strip().upper()
            pos = (import_nonblank(data.get('po_sementara')) or '').strip().upper()
            if po and item and pos:
                return (po, item, pos)
            return None

        def _biz_group_key(data):
            po = (import_nonblank(data.get('po_yupi')) or import_nonblank(data.get('yupi_po')) or '').strip().upper()
            item = (import_nonblank(data.get('item_yupi')) or '').strip().upper()
            pos = (import_nonblank(data.get('po_sementara')) or '').strip().upper()
            if po: return (po, item)
            if pos: return (pos, item)
            return None

        details = []
        to_delete = set()
        now = datetime.utcnow()

        # ── FASE -1: Biz identity (po_yupi + item_yupi + po_sementara)
        db_by_biz = {}
        for r in all_rows:
            bk = _biz_identity(db_row_data.get(r.id, {}))
            if bk:
                db_by_biz.setdefault(bk, []).append(r)
        phase_minus1 = 0
        for bk, rows in db_by_biz.items():
            if len(rows) <= 1: continue
            rows.sort(key=lambda r: (r.last_seen_at or datetime.min, r.id), reverse=True)
            winner = rows[0]
            winner_data = dict(db_row_data.get(winner.id, {}))
            fields_merged = []
            for loser in rows[1:]:
                if loser.id in to_delete: continue
                loser_data = db_row_data.get(loser.id, {})
                for field in IMPORT_LOCAL_EDIT_FIELDS:
                    lv = loser_data.get(field)
                    if import_blankish(lv): continue
                    if import_blankish(winner_data.get(field)):
                        winner_data[field] = lv
                        fields_merged.append(field)
                if winner_data != db_row_data.get(winner.id, {}):
                    winner.data_json = json.dumps(winner_data, ensure_ascii=False)
                    winner.updated_at = now
                    db_row_data[winner.id] = winner_data
                    try:
                        fresh_uid = import_row_source_uid(winner_data, [])
                        if fresh_uid and fresh_uid != winner.source_uid:
                            winner.source_uid = fresh_uid
                    except: pass
                to_delete.add(loser.id)
                phase_minus1 += 1
                details.append({
                    'phase': 'FASE_-1_biz_identity',
                    'loser_id': loser.id, 'loser_row_key': loser.row_key,
                    'winner_id': winner.id, 'winner_row_key': winner.row_key,
                    'key': f'po={bk[0]}, item={bk[1]}, pos={bk[2]}',
                    'loser_qty': clean(db_row_data.get(loser.id, {}).get('ord_qty')),
                    'winner_qty': clean(db_row_data.get(winner.id, {}).get('ord_qty')),
                    'loser_last_seen': str(loser.last_seen_at) if loser.last_seen_at else None,
                    'winner_last_seen': str(winner.last_seen_at) if winner.last_seen_at else None,
                    'fields_merged': fields_merged[:20],
                })

        # ── FASE 0: Recomputed source_uid
        db_by_uid = {}
        for r in all_rows:
            if r.id in to_delete: continue
            data = db_row_data.get(r.id, {})
            try: uid = import_row_source_uid(data, [])
            except: uid = (r.source_uid or '').strip()
            if uid:
                db_by_uid.setdefault(uid, []).append(r)
        phase_0 = 0
        for uid, rows in db_by_uid.items():
            if len(rows) <= 1: continue
            rows.sort(key=lambda r: (r.last_seen_at or datetime.min, r.id), reverse=True)
            winner = rows[0]
            winner_data = dict(db_row_data.get(winner.id, {}))
            fields_merged = []
            for loser in rows[1:]:
                if loser.id in to_delete: continue
                loser_data = db_row_data.get(loser.id, {})
                for field in IMPORT_LOCAL_EDIT_FIELDS:
                    lv = loser_data.get(field)
                    if import_blankish(lv): continue
                    if import_blankish(winner_data.get(field)):
                        winner_data[field] = lv
                        fields_merged.append(field)
                if winner_data != db_row_data.get(winner.id, {}):
                    winner.data_json = json.dumps(winner_data, ensure_ascii=False)
                    winner.updated_at = now
                    db_row_data[winner.id] = winner_data
                if uid != winner.source_uid:
                    winner.source_uid = uid
                to_delete.add(loser.id)
                phase_0 += 1
                details.append({
                    'phase': 'FASE_0_source_uid',
                    'loser_id': loser.id, 'loser_row_key': loser.row_key,
                    'winner_id': winner.id, 'winner_row_key': winner.row_key,
                    'key': f'uid={uid[:16]}...',
                    'loser_qty': clean(db_row_data.get(loser.id, {}).get('ord_qty')),
                    'winner_qty': clean(db_row_data.get(winner.id, {}).get('ord_qty')),
                    'loser_last_seen': str(loser.last_seen_at) if loser.last_seen_at else None,
                    'winner_last_seen': str(winner.last_seen_at) if winner.last_seen_at else None,
                    'fields_merged': fields_merged[:20],
                })

        # ── FASE 1: src_fingerprint (exclude `so`)
        db_by_fp = {}
        for r in all_rows:
            if r.id in to_delete: continue
            fp = _src_fingerprint(db_row_data.get(r.id, {}))
            db_by_fp.setdefault(fp, []).append(r)
        phase_1 = 0
        for fp, rows in db_by_fp.items():
            if len(rows) <= 1: continue
            rows.sort(key=lambda r: (-_user_richness(db_row_data.get(r.id, {})), r.id))
            winner = rows[0]
            for loser in rows[1:]:
                if loser.id in to_delete: continue
                to_delete.add(loser.id)
                phase_1 += 1
                details.append({
                    'phase': 'FASE_1_src_fingerprint',
                    'loser_id': loser.id, 'loser_row_key': loser.row_key,
                    'winner_id': winner.id, 'winner_row_key': winner.row_key,
                    'key': f'fp={fp[:16]}...',
                    'loser_qty': clean(db_row_data.get(loser.id, {}).get('ord_qty')),
                    'winner_qty': clean(db_row_data.get(winner.id, {}).get('ord_qty')),
                })

        # ── Eksekusi delete
        deleted_count = 0
        if to_delete:
            rows_to_del = [r for r in all_rows if r.id in to_delete]
            for r in rows_to_del:
                db.session.delete(r)
                deleted_count += 1
            db.session.commit()
            _checkpoint_and_backup_db('bulk_delete')
            clear_runtime_caches()

        total_after = ImportDashboardRow.query.filter(
            ImportDashboardRow.source_key.in_(_IMPORT_VISIBLE_SOURCE_KEYS)
        ).count()

        return jsonify({
            'success': True,
            'target_po_filter': target_po_upper or '(all POs)',
            'total_before_in_scope': len(all_rows),
            'total_after_in_db': total_after,
            'phase_-1_biz_identity_purged': phase_minus1,
            'phase_0_source_uid_purged': phase_0,
            'phase_1_src_fingerprint_purged': phase_1,
            'total_purged': deleted_count,
            'details': details[:200],
            'message': (f'Force cleanup selesai: {deleted_count} row dihapus '
                        f'(FASE -1: {phase_minus1}, FASE 0: {phase_0}, FASE 1: {phase_1}). '
                        f'Sisa total di DB: {total_after} rows.'),
            'note': ('Endpoint ini menjalankan FASE -1 (biz identity: po_yupi+item_yupi+po_sementara), '
                     'FASE 0 (recomputed source_uid), FASE 1 (src fingerprint exclude `so`). '
                     'Setiap loser di-merge field user-edit-nya ke winner supaya data user tidak hilang.'),
        })
    except Exception as e:
        db.session.rollback()
        import traceback; traceback.print_exc()
        return jsonify({'error': str(e), 'traceback': traceback.format_exc()}), 500


@app.route('/api/import/debug-duplicates', methods=['GET'])
def import_debug_duplicates():
    """Cari row di dashboard yang punya po_yupi sama tapi row_key berbeda (duplicate).

    FIX V10: Endpoint ini untuk diagnose kenapa item yang di-reschedule muncul
    sebagai 2 baris terpisah di dashboard, padahal seharusnya 1 baris (update).

    Return:
    - duplicates: list of {po_yupi, rows: [{row_key, item_yupi, req_dlv_date, ...}]}
    - summary: total duplicates found
    """
    try:
        all_rows = ImportDashboardRow.query.filter(
            ImportDashboardRow.source_key.in_(_IMPORT_VISIBLE_SOURCE_KEYS)
        ).all()
        # Group by po_yupi (case-insensitive)
        by_po_yupi = {}
        for row in all_rows:
            try: data = json.loads(row.data_json or '{}')
            except: data = {}
            po_yupi = clean(data.get('po_yupi')) or clean(data.get('yupi_po')) or ''
            if not po_yupi: continue
            key = po_yupi.strip().lower()
            by_po_yupi.setdefault(key, []).append({
                'row_key': row.row_key,
                'po_yupi': po_yupi,
                'item_yupi': clean(data.get('item_yupi')) or '',
                'po_sementara': clean(data.get('po_sementara')) or '',
                'req_dlv_date': clean(data.get('req_dlv_date')) or '',
                'source_req_dlv_date': clean(data.get('source_req_dlv_date')) or '',
                'reschedule': clean(data.get('reschedule')) or '',
                'vendor_name': clean(data.get('vendor_name')) or row.vendor_name or '',
                'item_name': clean(data.get('item_name')) or '',
                'source_uid': row.source_uid or '',
                'sheet_row': row.sheet_row,
            })
        # Find duplicates (po_yupi with more than 1 row)
        duplicates = []
        for po_yupi_key, rows in by_po_yupi.items():
            if len(rows) > 1:
                duplicates.append({
                    'po_yupi': rows[0]['po_yupi'],
                    'row_count': len(rows),
                    'rows': rows,
                })
        duplicates.sort(key=lambda x: x['row_count'], reverse=True)
        return jsonify({
            'total_rows': len(all_rows),
            'unique_po_yupi_count': len(by_po_yupi),
            'duplicate_po_yupi_count': len(duplicates),
            'duplicates': duplicates[:20],  # top 20
            'troubleshooting': (
                "Kalau ada duplicate (po_yupi sama, row berbeda): "
                "(1) Cek item_yupi — kalau beda, UID akan beda → dianggap row berbeda. "
                "(2) Cek source_uid — kalau beda, berarti identity payload berbeda. "
                "(3) Cek req_dlv_date — kalau beda, kemungkinan item di-reschedule. "
                "Solusi: pastikan item_yupi konsisten di sheet source, atau update identity logic."
            ),
        })
    except Exception as e:
        import traceback; traceback.print_exc()
        return jsonify({'error': str(e)}), 500


@app.route('/api/import/debug-find', methods=['GET'])
def import_debug_find():
    """Cari row di source sheet by PO Yupi number — tampilkan semua row yang cocok.

    FIX V9: Endpoint ini untuk diagnose kenapa PO tertentu (mis. 410100301)
    tidak tercopy. User bisa lihat persis di row berapa PO itu ada, dan apa
    vendor yang terbaca di row tersebut.

    Query params:
    - source: source_1 atau source_2
    - po: PO Yupi number (mis. 410100301)
    """
    try:
        source_key = clean(request.args.get('source')) or 'source_1'
        po_search = clean(request.args.get('po')) or ''
        source = next((s for s in IMPORT_SOURCE_SHEETS if s['key'] == source_key), None)
        if not source:
            return jsonify({'error': f"Unknown source '{source_key}'"}), 400
        if not po_search:
            return jsonify({'error': 'Param ?po= is required (PO Yupi number, e.g. 410100301)'}), 400

        columns = import_layout_columns()
        mapping_columns = import_all_mapping_columns(columns)
        sheet_title, header_df = import_source_header_preview(source, force=True)
        if header_df.empty:
            return jsonify({'error': 'Could not read header preview'}), 500

        header_idx = import_detect_header_row(header_df)
        source_map = import_source_column_map(header_df, mapping_columns)

        # Get uploaded vendor list
        uploaded_vendor_names = import_uploaded_vendor_names()
        uploaded_vendor_set = {v.strip().lower() for v in uploaded_vendor_names if v and v.strip()}

        # Scan ALL rows (empty set = ambil semua, tanpa filter vendor)
        all_rows = import_source_rows_fast(source, columns, set())

        # Cari row yang po_yupi-nya match
        po_search_norm = po_search.strip().lower()
        matching_rows = []
        for row in all_rows:
            row_po = clean(row.get('po_yupi')) or clean(row.get('yupi_po')) or ''
            if row_po and row_po.strip().lower() == po_search_norm:
                row_vendor = row.get('_vendor_name') or ''
                is_match = import_vendor_match(row_vendor, uploaded_vendor_set) if row_vendor else False
                matching_rows.append({
                    'sheet_row': row.get('_sheet_row'),
                    'po_yupi': row_po,
                    'po_sementara': row.get('po_sementara'),
                    'item_name': row.get('item_name'),
                    'vendor_name_detected': row_vendor,
                    'is_vendor_match': is_match,
                    'all_fields': {k: v for k, v in row.items() if not k.startswith('_') and v},
                })

        return jsonify({
            'source_key': source_key,
            'po_searched': po_search,
            'total_rows_scanned': len(all_rows),
            'matching_rows_found': len(matching_rows),
            'matched_rows_detail': matching_rows,
            'vendor_filter_used': sorted(uploaded_vendor_set),
            'troubleshooting': (
                "Jika matching_rows_found = 0: PO tidak ada di sheet source (cek sheet langsung). "
                "Jika matching_rows_found > 0 tapi is_vendor_match = false: "
                "(1) Cek vendor_name_detected — apakah persis sama atau prefix dari vendor di vendor_filter_used? "
                "(2) Kalau vendor_name_detected kosong, berika carry-over tidak aktif "
                "(mungkin row tidak punya po_yupi/item_name yang terbaca). "
                "(3) Kalau vendor_name_detected terisi tapi beda penulisan, "
                "update vendor di ImportVendor table atau tambahkan variant nama. "
                "Jika is_vendor_match = true tapi row belum tercopy di dashboard: "
                "trigger sync via POST /api/import/copy-sheet."
            ),
        })
    except Exception as e:
        import traceback; traceback.print_exc()
        return jsonify({'error': str(e)}), 500


@app.route('/api/import/debug-row', methods=['GET'])
def import_debug_row():
    """Cek row spesifik di source sheet — tampilkan SEMUA kolom yang terbaca.

    FIX V9: Endpoint ini untuk diagnose kenapa row tertentu (mis. row 144 dengan
    PO 410100301) tidak tercopy. User bisa lihat persis nilai dari setiap kolom.

    Query params:
    - source: source_1 atau source_2
    - row: nomor row (1-indexed, sesuai tampilan Google Sheet)
    """
    try:
        source_key = clean(request.args.get('source')) or 'source_1'
        row_num = int(clean(request.args.get('row')) or 0)
        source = next((s for s in IMPORT_SOURCE_SHEETS if s['key'] == source_key), None)
        if not source:
            return jsonify({'error': f"Unknown source '{source_key}'"}), 400
        if not row_num or row_num < 1:
            return jsonify({'error': 'Param ?row= is required (1-indexed row number)'}), 400

        columns = import_layout_columns()
        mapping_columns = import_all_mapping_columns(columns)
        sheet_title, header_df = import_source_header_preview(source, force=True)
        if header_df.empty:
            return jsonify({'error': 'Could not read header preview'}), 500

        header_idx = import_detect_header_row(header_df)
        source_map = import_source_column_map(header_df, mapping_columns)

        # Baca row spesifik langsung dari sheet
        # row_num adalah 1-indexed (sesuai Google Sheet)
        result = google_sheets_values_get(
            source['spreadsheet_id'],
            f"'{sheet_title}'!A{row_num}:ZZ{row_num}",
            value_render_option='FORMATTED_VALUE'
        )
        values = result.get('values', [])
        if not values or not values[0]:
            return jsonify({
                'source_key': source_key,
                'row_requested': row_num,
                'error': f'Row {row_num} kosong atau tidak terbaca',
            }), 404

        row_values = values[0]
        # Petakan ke field name berdasarkan source_map
        field_values = {}
        for field, col_idx in source_map.items():
            if col_idx is not None and col_idx < len(row_values):
                field_values[field] = row_values[col_idx]
            else:
                field_values[field] = ''

        # Header row untuk referensi
        header_row = [clean(v) for v in header_df.iloc[header_idx].tolist()] if len(header_df) else []

        return jsonify({
            'source_key': source_key,
            'sheet_title_used': sheet_title,
            'row_requested': row_num,
            'header_row_1based': header_idx + 1,
            'header_row_values': header_row[:25],
            'column_map_field_to_letter': {f: column_letter_from_index(idx + 1) for f, idx in source_map.items() if idx is not None},
            'raw_row_values': row_values[:25],  # 25 kolom pertama
            'field_values_detected': field_values,
            'vendor_value_at_Q': row_values[16] if len(row_values) > 16 else '(empty)',  # Q = index 16
            'amount_value_at_P': row_values[15] if len(row_values) > 15 else '(empty)',  # P = index 15
            'troubleshooting': (
                "Cek field_values_detected.vendor_name — kalau kosong padahal di sheet ada, "
                "kemungkinan: (1) vendor di-merge cell, (2) header detection salah kolom. "
                "Cek raw_row_values untuk lihat semua kolom. "
                "Kalau vendor ada di kolom lain (mis. R, S), berarti header detection salah — "
                "kirim screenshot ke developer untuk fix."
            ),
        })
    except Exception as e:
        import traceback; traceback.print_exc()
        return jsonify({'error': str(e)}), 500


@app.route('/api/import/debug-scan', methods=['GET'])
def import_debug_scan():
    """Scan SEMUA rows di source sheet, return statistic match/no-match + sample row yang gagal.

    FIX V9: Endpoint ini untuk diagnose kenapa PO tertentu tidak tercopy.
    Return:
    - total_rows_scanned: jumlah row dengan data di sheet
    - matched_rows: row yang vendor-nya match dengan uploaded vendor list
    - unmatched_rows: row yang vendor-nya TIDAK match (dengan detail vendor yang terbaca)
    - matched_sample: 5 row pertama yang match
    - unmatched_sample: 5 row pertama yang tidak match (supaya user bisa lihat vendor apa yang tidak match)
    - vendor_filter_used: daftar vendor yang di-upload ke ImportVendor table
    """
    try:
        source_key = clean(request.args.get('source')) or 'source_1'
        source = next((s for s in IMPORT_SOURCE_SHEETS if s['key'] == source_key), None)
        if not source:
            return jsonify({
                'error': f"Unknown source key '{source_key}'",
                'available_sources': [s['key'] for s in IMPORT_SOURCE_SHEETS],
            }), 400

        columns = import_layout_columns()
        mapping_columns = import_all_mapping_columns(columns)
        sheet_title, header_df = import_source_header_preview(source, force=True)
        if header_df.empty:
            return jsonify({'error': 'Could not read header preview', 'source': source_key}), 500

        header_idx = import_detect_header_row(header_df)
        source_map = import_source_column_map(header_df, mapping_columns)
        header_row_values = [clean(v) for v in header_df.iloc[header_idx].tolist()] if len(header_df) else []

        source_map_letters = {}
        for field, idx in source_map.items():
            try: source_map_letters[field] = column_letter_from_index(idx + 1)
            except: source_map_letters[field] = f'(idx {idx})'

        # Get uploaded vendor list
        uploaded_vendor_names = import_uploaded_vendor_names()
        uploaded_vendor_set = {v.strip().lower() for v in uploaded_vendor_names if v and v.strip()}

        if not uploaded_vendor_set:
            return jsonify({
                'source_key': source_key,
                'error': 'No uploaded vendor list! Source sheet sync di-skip entirely ketika vendor list kosong.',
                'vendor_filter_used': [],
                'fix': 'Upload vendor list dulu via tombol Upload Vendor di dashboard, atau via /api/import/vendors/upload.',
            }), 200

        # Scan ALL rows (tidak hanya 5 sample) dengan vendor_set = kosong (ambil semua)
        # Lalu manual check match untuk setiap row
        all_rows = import_source_rows_fast(source, columns, set())  # empty set = ambil semua
        # Tunggu — empty set akan skip filter, tapi code cek `if vendor_set and not any(...)`.
        # Kalau vendor_set kosong, `if vendor_set` False → tidak filter → ambil semua. ✓

        matched_rows = []
        unmatched_rows = []
        for row in all_rows:
            row_vendor = row.get('_vendor_name') or ''
            is_match = import_vendor_match(row_vendor, uploaded_vendor_set) if row_vendor else False
            row_info = {
                'sheet_row': row.get('_sheet_row'),
                'vendor_name_detected': row_vendor,
                'po_yupi': row.get('po_yupi'),
                'po_sementara': row.get('po_sementara'),
                'item_name': row.get('item_name'),
                'is_match': is_match,
            }
            if is_match:
                matched_rows.append(row_info)
            else:
                unmatched_rows.append(row_info)

        # Statistic vendor yang tidak match (group by vendor name)
        unmatched_vendors = {}
        for r in unmatched_rows:
            v = r['vendor_name_detected'] or '(empty)'
            unmatched_vendors[v] = unmatched_vendors.get(v, 0) + 1

        return jsonify({
            'source_key': source_key,
            'sheet_title_used': sheet_title,
            'detected_header_row_1based': header_idx + 1,
            'column_map_field_to_letter': source_map_letters,
            'header_row_raw_values': header_row_values[:25],
            'vendor_fallback_letters': list(IMPORT_FALLBACK_SOURCE_VENDOR_LETTERS),
            'vendor_filter_used': sorted(uploaded_vendor_set),
            'vendor_filter_count': len(uploaded_vendor_set),
            'total_rows_scanned': len(all_rows),
            'matched_rows': len(matched_rows),
            'unmatched_rows': len(unmatched_rows),
            'unmatched_vendors_breakdown': unmatched_vendors,
            'matched_sample': matched_rows[:5],
            'unmatched_sample': unmatched_rows[:10],
            'troubleshooting': (
                "Jika PO yang dicari ada di unmatched_sample: "
                "(1) Cek vendor_name_detected — apakah persis sama atau prefix dari vendor di vendor_filter_used? "
                "(2) Kalau vendor belum di-upload, tambahkan via /api/import/vendors/upload. "
                "(3) Fuzzy match aktif: prefix match (min 5 char) atau contains match (min 8 char). "
                "Jika PO tidak ada di matched_sample DAN tidak ada di unmatched_sample: "
                "(a) Cek total_rows_scanned — kalau 0, berarti header detection gagal. "
                "(b) Cek header_row_raw_values — pastikan header terdeteksi benar. "
                "(c) Cek column_map_field_to_letter — vendor_name dan po_yupi harus terpetakan."
            ),
        })
    except Exception as e:
        import traceback; traceback.print_exc()
        return jsonify({'error': str(e)}), 500


@app.route('/api/import/cell', methods=['PUT'])
def update_import_cell():
    try:
        payload = request.get_json(silent=True) or {}
        row_key = clean(payload.get('row_key'))
        field = clean(payload.get('field'))
        value = '' if payload.get('value') is None else str(payload.get('value'))
        if not row_key or not field:
            return jsonify({'error': 'row_key and field are required'}), 400
        columns = import_layout_columns()
        column = next((col for col in columns if col['field'] == field), None)
        if not column:
            return jsonify({'error': 'Unknown import column'}), 400
        row = ImportDashboardRow.query.filter_by(row_key=row_key).first()
        fuzzy_matched = False
        # FIX V14: kalau row_key tidak ketemu (kemungkinan karena daily sync
        # identity drift mengubah row_key), coba fuzzy match by biz key.
        if not row:
            po_yupi_p = clean(payload.get('po_yupi'))
            item_yupi_p = clean(payload.get('item_yupi'))
            po_sementara_p = clean(payload.get('po_sementara'))
            if po_yupi_p or item_yupi_p or po_sementara_p:
                biz_key_from_payload = import_row_business_uid({
                    'po_yupi': po_yupi_p, 'yupi_po': po_yupi_p,
                    'item_yupi': item_yupi_p, 'po_sementara': po_sementara_p,
                })
                if biz_key_from_payload:
                    all_import_rows = ImportDashboardRow.query.filter(
                        ImportDashboardRow.source_key.in_(_IMPORT_VISIBLE_SOURCE_KEYS)
                    ).all()
                    for _r in all_import_rows:
                        try: _d = json.loads(_r.data_json or '{}')
                        except: _d = {}
                        try: _bk = import_row_business_uid(_d)
                        except: _bk = None
                        if _bk == biz_key_from_payload:
                            row = _r
                            fuzzy_matched = True
                            print(f"[import/cell] FUZZY MATCH row_key={row_key} → {row.row_key} (biz key match)")
                            break
        if not row:
            return jsonify({'error': 'Import dashboard row not found'}), 404
        # FIX V28: Untuk group-level fields, propagate edit ke SEMUA row dengan
        # YUPI PO yang sama (sama dengan logic di /api/import/cells). Ini
        # menyelesaikan bug "PO yang sama menampilkan 2 data berbeda" untuk
        # single-cell edits (klik cell → edit → blur).
        # FIX V30: req_dlv_date dihapus — adalah merge key, propagating akan
        # break delivery group identity. Lihat komentar di /api/import/cells.
        GROUP_LEVEL_FIELDS = {
            'po_send_date', 'status', 'etd', 'eta',
            'import_remarks', 'incoterm', 'forwarder', 'bl_number', 'inv_no',
            'sap_input', 'payment', 'payment_date', 'soft_copy_doc', 'non_ski',
        }
        target_rows = [row]
        if field in GROUP_LEVEL_FIELDS:
            try: row_data_for_yupi = json.loads(row.data_json or '{}')
            except: row_data_for_yupi = {}
            row_yupi = import_nonblank(row_data_for_yupi.get('yupi_po')) or import_nonblank(row_data_for_yupi.get('po_yupi'))
            # FIX V57: Group by (yupi_po + req_dlv_date) — NOT yupi_po only.
            row_req = import_nonblank(row_data_for_yupi.get('req_dlv_date')) or import_nonblank(row_data_for_yupi.get('source_req_dlv_date')) or ''
            if row_yupi:
                _yupi_key = row_yupi.strip().lower()
                _req_key = str(row_req).strip().lower()
                _po_rows = ImportDashboardRow.query.filter(
                    ImportDashboardRow.source_key.in_(_IMPORT_VISIBLE_SOURCE_KEYS)
                ).all()
                target_rows = []
                for _r in _po_rows:
                    try: _d = json.loads(_r.data_json or '{}')
                    except: _d = {}
                    _yp = import_nonblank(_d.get('yupi_po')) or import_nonblank(_d.get('po_yupi'))
                    _rp = import_nonblank(_d.get('req_dlv_date')) or import_nonblank(_d.get('source_req_dlv_date')) or ''
                    # FIX V57: Match BOTH yupi_po AND req_dlv_date
                    if _yp and _yp.strip().lower() == _yupi_key and str(_rp).strip().lower() == _req_key:
                        target_rows.append(_r)
                if not target_rows:
                    target_rows = [row]
                print(f"[import/cell] FIX V28: propagating field={field} to {len(target_rows)} rows with YUPI PO={row_yupi}", file=__import__('sys').stderr)
        sync_items = []
        for target_row in target_rows:
            try:
                data = json.loads(target_row.data_json or '{}')
            except (TypeError, json.JSONDecodeError):
                data = {}
            data = set_import_payload_field_aliases(data, field, value)
            data = apply_import_formula_columns(data)
            target_row.data_json = json.dumps(data, ensure_ascii=False)
            target_row.updated_at = datetime.utcnow()
            sync_items.append({'row': target_row, 'field': field, 'value': value})
            if field in ('purchase_price', 'ord_qty') and clean(data.get('purchase_amount')):
                sync_items.append({'row': target_row, 'field': 'purchase_amount', 'value': data.get('purchase_amount')})
        sheet_sync = {'synced': False, 'reason': 'Not attempted'}
        try:
            sheet_sync = sync_import_cells_to_google_sheet(sync_items)
        except Exception as sync_exc:
            sheet_sync = {'synced': False, 'reason': str(sync_exc)}
        db.session.commit()
        clear_runtime_caches()
        columns = import_layout_columns()
        updated_row = import_dashboard_row_to_dict(row, columns, vendor_attrs_map=import_vendor_attrs_map())
        # FIX V38: Re-inject total_purchase_amount ke response row. Cell update
        # (mis. toggle BL/AWB checkbox) menyebabkan frontend replace row dengan
        # response dari backend. Tapi total_purchase_amount TIDAK disimpan di
        # data_json — di-compute on-the-fly di /api/import/data. Tanpa re-inject,
        # cell TOTAL PUR AMT jadi kosong setelah toggle checkbox.
        try:
            _row_yupi = import_nonblank(updated_row.get('yupi_po')) or import_nonblank(updated_row.get('po_yupi'))
            if _row_yupi:
                _yp_key = _row_yupi.strip().lower()
                # Compute total across ALL rows with same YUPI PO
                _all_po_rows = ImportDashboardRow.query.filter(
                    ImportDashboardRow.source_key.in_(_IMPORT_VISIBLE_SOURCE_KEYS)
                ).all()
                _total = 0.0
                _has_amount = False
                for _r in _all_po_rows:
                    try: _d = json.loads(_r.data_json or '{}')
                    except: _d = {}
                    _d = apply_import_formula_columns(dict(_d))
                    _ryp = import_nonblank(_d.get('yupi_po')) or import_nonblank(_d.get('po_yupi'))
                    if not _ryp or _ryp.strip().lower() != _yp_key:
                        continue
                    _pa = import_float_value(_d.get('purchase_amount'))
                    if _pa is None:
                        _price = import_float_value(_d.get('purchase_price'))
                        _qty = import_float_value(_d.get('ord_qty'))
                        if _price is not None and _qty is not None:
                            _pa = _price * _qty
                    if _pa is not None:
                        _total += _pa
                        _has_amount = True
                updated_row['total_purchase_amount'] = import_format_number(_total) if _has_amount else ''
        except Exception:
            updated_row['total_purchase_amount'] = ''
        return jsonify({'success': True, 'row_key': row.row_key, 'original_row_key': row_key, 'field': field, 'value': value, 'row': updated_row, 'sheet_sync': sheet_sync, 'fuzzy_matched': fuzzy_matched, 'propagated_to': len(target_rows)})
    except Exception as e:
        db.session.rollback()
        import traceback; traceback.print_exc()
        return jsonify({'error': str(e), 'sheet_sync': {'synced': False, 'reason': str(e)}}), 500


@app.route('/api/import/export', methods=['GET'])
def export_import_data():
    try:
        search = clean(request.args.get('search')) or ''
        selected_yupi_po_raw = [clean(v) for v in request.args.getlist('yupi_po') if clean(v)]
        selected_vendors_raw = [clean(v) for v in request.args.getlist('vendor_name') if clean(v)]
        selected_statuses_raw = [clean(v) for v in request.args.getlist('status') if clean(v)]
        selected_days_left = [clean(v).lower() for v in request.args.getlist('days_left') if clean(v)]
        none_yupi_po = any(v == '__NONE_PLACEHOLDER__' for v in selected_yupi_po_raw)
        none_vendor = any(v == '__NONE_PLACEHOLDER__' for v in selected_vendors_raw)
        selected_yupi_po = {v.strip().lower() for v in selected_yupi_po_raw if v != '__NONE_PLACEHOLDER__'}
        selected_vendors = {v.strip().lower() for v in selected_vendors_raw if v != '__NONE_PLACEHOLDER__'}
        selected_status_set = {str(v).strip().upper() for v in selected_statuses_raw if v}

        columns = import_layout_columns()
        q = ImportDashboardRow.query.filter(
            ImportDashboardRow.source_key.in_(_IMPORT_VISIBLE_SOURCE_KEYS)
        )
        if search:
            terms = [t.strip().lower() for t in re.split(r'[\n,]+', search) if t.strip()]
            for term in terms:
                pattern = f'%{term}%'
                q = q.filter(db.or_(
                    ImportDashboardRow.row_key.ilike(pattern),
                    ImportDashboardRow.source_label.ilike(pattern),
                    ImportDashboardRow.vendor_name.ilike(pattern),
                    ImportDashboardRow.data_json.ilike(pattern),
                ))

        candidate_rows = q.order_by(
            ImportDashboardRow.first_seen_at.desc(),
            ImportDashboardRow.id.desc(),
        ).all()

        # Apply the uploaded-vendor filter to exports too — same safety net
        # as /api/import/data. When a Vendor Import list exists, only rows
        # with matching vendors are exported.
        uploaded_vendor_set_for_export = {v.strip().lower() for v in import_uploaded_vendor_names() if v and v.strip()}

        filtered = []
        for row in candidate_rows:
            try:
                data = json.loads(row.data_json or '{}')
            except (TypeError, json.JSONDecodeError):
                data = {}
            data = apply_import_formula_columns(dict(data))
            yupi = import_nonblank(data.get('yupi_po')) or import_nonblank(data.get('po_yupi'))
            vendor = import_nonblank(data.get('vendor_name')) or import_nonblank(data.get('vendor')) or import_nonblank(row.vendor_name)
            # Uploaded-vendor filter — skip rows whose vendor is not in the
            # uploaded list (or has no vendor at all). Uses fuzzy matching
            # (import_vendor_match) to stay consistent with sync + display.
            if uploaded_vendor_set_for_export:
                if not vendor or not import_vendor_match(vendor, uploaded_vendor_set_for_export):
                    continue
            if none_yupi_po or none_vendor:
                continue
            if selected_yupi_po and str(yupi or '').strip().lower() not in selected_yupi_po:
                continue
            if selected_vendors and str(vendor or '').strip().lower() not in selected_vendors:
                continue
            # Status filter (case-insensitive, exact match)
            if selected_status_set and str(data.get('status') or '').strip().upper() not in selected_status_set:
                continue
            # Days Left color filter (supports multiple zones — row passes if
            # it matches ANY selected zone)
            if selected_days_left:
                raw_dl = str(data.get('days_left') or '').strip()
                if raw_dl in ('✅', '❌', '', '-'):
                    continue
                try:
                    dl = int(float(raw_dl))
                except (ValueError, TypeError):
                    continue
                matched = False
                for zone in selected_days_left:
                    if zone == 'red' and (dl < 0 or dl <= 7):
                        matched = True; break
                    if zone == 'yellow' and 8 <= dl <= 29:
                        matched = True; break
                    if zone == 'green' and dl >= 30:
                        matched = True; break
                    if zone == 'today' and dl == 0:
                        matched = True; break
                if not matched:
                    continue
            filtered.append((row, data))

        wb = Workbook()
        ws = wb.active
        ws.title = 'Import Dashboard'

        visible_cols = [col for col in columns if not col.get('source_only')]
        header_labels = [col.get('label', col.get('field', '')).replace('\n', ' ') for col in visible_cols]
        ws.append(header_labels)

        header_fill = PatternFill(start_color='1E3A5F', end_color='1E3A5F', fill_type='solid')
        for cell in ws[1]:
            cell.fill = header_fill
            cell.font = Font(bold=True, color='FFFFFF')
            cell.alignment = Alignment(horizontal='center', wrap_text=True)
        ws.row_dimensions[1].height = 32

        for i, col in enumerate(visible_cols, 1):
            width = min(max((col.get('width', 120)) / 7, 8), 50)
            ws.column_dimensions[get_column_letter(i)].width = width

        alt_fill = PatternFill(start_color='F0F4FF', end_color='F0F4FF', fill_type='solid')
        # Build vendor-attr map once for the export so Origin/TOP/Non SKI can be
        # injected into each row by matching the row's vendor name.
        _export_vendor_attrs = import_vendor_attrs_map()
        # FIX V10: Carry-over field yang di-merge di dashboard supaya di Excel
        # semua row di group dapat nilai yang sama.
        #
        # Frontend merge berdasarkan yupi_po + req_dlv_date sama (IMPORT_MERGE_KEY_FIELDS).
        # Field yang di-merge (bukan group_per_item): status, days_left, vendor,
        # po_send_date, etd, eta, dll — semua field EXCEPT yang group_per_item=True.
        # Saat user edit cell di row pertama group, hanya row pertama yang di-update
        # di DB. Row lain di group tetap kosong. Saat export, kita harus fill-down
        # nilai dari row pertama ke semua row di group yang sama.
        #
        # Logika:
        # 1. Group rows by (yupi_po + req_dlv_date) — sama seperti frontend
        # 2. Untuk setiap group, cari nilai non-empty untuk setiap field dari row manapun
        # 3. Apply nilai tersebut ke semua row di group
        # Field yang TIDAK di-carry-over: yang group_per_item=True (item_name, ord_qty,
        # unit_price, amount, spec, dll — ini unique per item)
        GROUP_PER_ITEM_FIELDS = {'item_name', 'item_yupi', 'spec', 'remark_yupi', 'ord_qty',
                                 'unit', 'unit_price', 'amount', 'purchase_price', 'purchase_amount',
                                 'currency', 'lt_days', 'reschedule', 'req_dlv_date', 'source_req_dlv_date',
                                 'po_sementara', 'days_left', 'arrival_check', 'po_date_by_email',
                                 'so', 'soft_copy_doc', 'bl_number', 'inv_no', 'incoterm', 'forwarder',
                                 'sap_input', 'bl_awb', 'invoice', 'pl', 'hc', 'msds', 'coa', 'coo',
                                 'payment', 'payment_date', 'import_remarks', 'etd', 'eta'}
        CARRYOVER_FIELDS = [col.get('field') for col in visible_cols
                           if col.get('field') and col.get('field') not in GROUP_PER_ITEM_FIELDS]

        # Group rows by (yupi_po + req_dlv_date)
        groups = []
        current_group = []
        current_key = None
        for db_row, data in filtered:
            yupi = (clean(data.get('yupi_po')) or clean(data.get('po_yupi')) or '').strip()
            req_dlv = clean(data.get('req_dlv_date')).strip()
            group_key = f"{yupi}|{req_dlv}"
            # Hanya group kalau yupi_po tidak kosong
            if not yupi:
                # Row tanpa yupi_po = group sendiri
                if current_group:
                    groups.append(current_group)
                groups.append([(db_row, data)])
                current_group = []
                current_key = None
                continue
            if current_key is None or group_key != current_key:
                if current_group:
                    groups.append(current_group)
                current_group = [(db_row, data)]
                current_key = group_key
            else:
                current_group.append((db_row, data))
        if current_group:
            groups.append(current_group)

        # Untuk setiap group, collect nilai non-empty per field, lalu apply ke semua row
        processed_rows = []
        # FIX V37: Pre-compute total per YUPI PO (across ALL groups with same
        # YUPI PO), then inject to each row. Sebelumnya total di-compute per
        # (yupi_po + req_dlv_date) group, tapi ini bisa miss kalau req_dlv_date
        # beda antar item. Sekarang: total = sum semua item dengan YUPI PO sama.
        _yupi_po_totals = {}
        for db_row, data in filtered:
            _yp = import_nonblank(data.get('yupi_po')) or import_nonblank(data.get('po_yupi'))
            if not _yp:
                continue
            _yp_key = _yp.strip().lower()
            _pa = import_float_value(data.get('purchase_amount'))
            if _pa is None:
                _price = import_float_value(data.get('purchase_price'))
                _qty = import_float_value(data.get('ord_qty'))
                if _price is not None and _qty is not None:
                    _pa = _price * _qty
            if _pa is not None:
                _yupi_po_totals[_yp_key] = _yupi_po_totals.get(_yp_key, 0.0) + _pa
        for group in groups:
            # Inject total_purchase_amount berdasarkan YUPI PO (bukan per group).
            try:
                _db_row_sample, _data_sample = group[0]
                _yp_sample = import_nonblank(_data_sample.get('yupi_po')) or import_nonblank(_data_sample.get('po_yupi')) or ''
                _yp_key_sample = _yp_sample.strip().lower()
                _grp_total_str = import_format_number(_yupi_po_totals[_yp_key_sample]) if _yp_key_sample in _yupi_po_totals else ''
                for _db_row, _data in group:
                    _data['total_purchase_amount'] = _grp_total_str
            except Exception:
                for _db_row, _data in group:
                    _data['total_purchase_amount'] = ''

            if len(group) == 1:
                # Single row group, tidak perlu carry-over
                processed_rows.append(group[0])
                continue
            # Collect nilai non-empty per field dari semua row di group
            group_values = {}
            for db_row, data in group:
                for field in CARRYOVER_FIELDS:
                    val = data.get(field)
                    if not import_blankish(val) and field not in group_values:
                        group_values[field] = val
            # Apply nilai ke semua row di group
            for db_row, data in group:
                for field in CARRYOVER_FIELDS:
                    if import_blankish(data.get(field)) and field in group_values:
                        data[field] = group_values[field]
                processed_rows.append((db_row, data))

        for row_idx, (db_row, data) in enumerate(processed_rows, 2):
            # Inject vendor attributes (origin, top, non_ski) if missing in row data.
            row_vendor = import_nonblank(data.get('vendor')) or import_nonblank(data.get('vendor_name')) or import_nonblank(db_row.vendor_name)
            if row_vendor:
                attrs = _export_vendor_attrs.get(str(row_vendor).strip().lower())
                if attrs:
                    if not import_nonblank(data.get('origin')):
                        data['origin'] = attrs.get('origin') or ''
                    if not import_nonblank(data.get('top')):
                        data['top'] = attrs.get('top') or ''
                    if not import_nonblank(data.get('non_ski')):
                        data['non_ski'] = attrs.get('non_ski') or ''
            row_vals = []
            for col in visible_cols:
                field = col.get('field', '')
                val = data.get(field, '')
                if col.get('checkbox'):
                    val = 'YES' if import_truthy_checkbox_value(val) else ''
                row_vals.append(val if val is not None else '')
            ws.append(row_vals)
            if row_idx % 2 == 0:
                for cell in ws[row_idx]:
                    cell.fill = alt_fill

        ws.freeze_panes = 'A2'
        output = io.BytesIO()
        _apply_excel_number_display_formats_v632756(wb)
        wb.save(output)
        output.seek(0)
        filename = f"Import_Dashboard_{datetime.now().strftime('%Y%m%d_%H%M')}.xlsx"
        return send_file(
            output,
            mimetype='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
            as_attachment=True,
            download_name=filename,
        )
    except Exception as e:
        import traceback; traceback.print_exc()
        return jsonify({'error': str(e)}), 500


@app.route('/api/import/cells', methods=['PUT'])
def update_import_cells_batch():
    try:
        payload = request.get_json(silent=True) or {}
        updates = payload.get('updates') or []
        if not isinstance(updates, list) or not updates:
            return jsonify({'error': 'updates must be a non-empty list'}), 400
        columns = import_layout_columns()
        valid_fields = {col['field'] for col in import_all_mapping_columns(columns)}
        row_keys = [clean(item.get('row_key')) for item in updates if clean(item.get('row_key'))]
        rows = ImportDashboardRow.query.filter(ImportDashboardRow.row_key.in_(row_keys)).all() if row_keys else []
        row_by_key = {r.row_key: r for r in rows}
        # FIX V14: Pre-build biz-key index supaya bisa fuzzy re-match row_key yang
        # sudah berubah karena daily sync identity drift.
        all_import_rows = ImportDashboardRow.query.filter(
            ImportDashboardRow.source_key.in_(_IMPORT_VISIBLE_SOURCE_KEYS)
        ).all() if row_keys else []
        biz_key_to_row = {}
        for _r in all_import_rows:
            try: _d = json.loads(_r.data_json or '{}')
            except: _d = {}
            try: _bk = import_row_business_uid(_d)
            except: _bk = None
            if _bk and _bk not in biz_key_to_row:
                biz_key_to_row[_bk] = _r
        # FIX V28: Pre-build YUPI PO index supaya edit ke 1 row propagate ke
        # SEMUA row dengan YUPI PO yang sama (regardless of item_yupi /
        # po_sementara / req_dlv_date). Ini menyelesaikan bug "PO yang sama
        # menampilkan 2 data berbeda" — sekarang edit ke field group-level
        # (eta, sap_input, status, dll.) update semua duplikat row PO tersebut.
        yupi_po_to_rows = {}
        for _r in all_import_rows:
            try: _d = json.loads(_r.data_json or '{}')
            except: _d = {}
            _yp = import_nonblank(_d.get('yupi_po')) or import_nonblank(_d.get('po_yupi'))
            if _yp:
                yupi_po_to_rows.setdefault(_yp.strip().lower(), []).append(_r)
        # Group-level fields yang harus propagate ke semua row PO yang sama.
        # Per-item fields (item_yupi, item_name, spec, ord_qty, unit_price,
        # amount, purchase_price, currency, purchase_amount, dll) TIDAK di-
        # propagate karena mereka unique per line item.
        # FIX V30: req_dlv_date DIHAPUS dari GROUP_LEVEL_FIELDS. req_dlv_date
        # adalah merge key (yupi_po + req_dlv_date). Propagating req_dlv_date
        # ke semua row PO yang sama akan merge grup pengiriman berbeda →
        # break identity hash + dedup logic. User harus edit req_dlv_date
        # per-row (per delivery group).
        GROUP_LEVEL_FIELDS = {
            'po_send_date', 'status', 'etd', 'eta',
            'import_remarks', 'incoterm', 'forwarder', 'bl_number', 'inv_no',
            'sap_input', 'payment', 'payment_date', 'soft_copy_doc', 'non_ski',
        }
        sheet_items = []
        updated_keys = set()
        skipped_missing = 0
        fuzzy_matched_keys = set()
        for item in updates:
            row_key = clean(item.get('row_key'))
            field = clean(item.get('field'))
            value = '' if item.get('value') is None else str(item.get('value'))
            if not row_key or not field or field not in valid_fields:
                continue
            row = row_by_key.get(row_key)
            # FIX V14: kalau row_key tidak ketemu, coba fuzzy match by biz key.
            if not row:
                biz_key_from_payload = None
                po_yupi_p = clean(item.get('po_yupi'))
                item_yupi_p = clean(item.get('item_yupi'))
                po_sementara_p = clean(item.get('po_sementara'))
                if po_yupi_p or item_yupi_p or po_sementara_p:
                    biz_key_from_payload = import_row_business_uid({
                        'po_yupi': po_yupi_p, 'yupi_po': po_yupi_p,
                        'item_yupi': item_yupi_p, 'po_sementara': po_sementara_p,
                    })
                if biz_key_from_payload and biz_key_from_payload in biz_key_to_row:
                    row = biz_key_to_row[biz_key_from_payload]
                    fuzzy_matched_keys.add(row.row_key)
            if not row:
                skipped_missing += 1
                print(f"[import/cells] SKIP row_key={row_key} field={field} — not found (and no fuzzy match)")
                continue
            # FIX V57: Untuk group-level fields, collect SEMUA row dengan
            # YUPI PO + req_dlv_date yang sama (bukan yupi_po saja).
            # Rows with same PO but different req_dlv_date = separate delivery
            # groups → should NOT be linked.
            try: row_data_for_yupi = json.loads(row.data_json or '{}')
            except: row_data_for_yupi = {}
            row_yupi = import_nonblank(row_data_for_yupi.get('yupi_po')) or import_nonblank(row_data_for_yupi.get('po_yupi'))
            row_req = import_nonblank(row_data_for_yupi.get('req_dlv_date')) or import_nonblank(row_data_for_yupi.get('source_req_dlv_date')) or ''
            target_rows = [row]
            if field in GROUP_LEVEL_FIELDS and row_yupi:
                _yupi_key = row_yupi.strip().lower()
                _req_key = str(row_req).strip().lower()
                _po_rows = yupi_po_to_rows.get(_yupi_key, [])
                # FIX V57: Filter by req_dlv_date too
                target_rows = []
                for _pr in _po_rows:
                    try: _pd = json.loads(_pr.data_json or '{}')
                    except: _pd = {}
                    _pr_req = import_nonblank(_pd.get('req_dlv_date')) or import_nonblank(_pd.get('source_req_dlv_date')) or ''
                    if str(_pr_req).strip().lower() == _req_key:
                        target_rows.append(_pr)
                if not target_rows:
                    target_rows = [row]
                if len(target_rows) > 1:
                    print(f"[import/cells] FIX V57: propagating field={field} to {len(target_rows)} rows with YUPI PO={row_yupi} req_dlv={row_req}", file=__import__('sys').stderr)
            for target_row in target_rows:
                try:
                    data = json.loads(target_row.data_json or '{}')
                except (TypeError, json.JSONDecodeError):
                    data = {}
                data = set_import_payload_field_aliases(data, field, value)
                data = apply_import_formula_columns(data)
                target_row.data_json = json.dumps(data, ensure_ascii=False)
                target_row.updated_at = datetime.utcnow()
                sheet_items.append({'row': target_row, 'field': field, 'value': value})
                if field in ('purchase_price', 'ord_qty') and clean(data.get('purchase_amount')):
                    sheet_items.append({'row': target_row, 'field': 'purchase_amount', 'value': data.get('purchase_amount')})
                updated_keys.add(target_row.row_key)
        sheet_sync = {'synced': False, 'reason': 'No mapped Import sheet cells to sync'}
        if sheet_items:
            try:
                sheet_sync = sync_import_cells_to_google_sheet(sheet_items)
            except Exception as sync_exc:
                sheet_sync = {'synced': False, 'reason': str(sync_exc)}
        db.session.commit()
        clear_runtime_caches()
        _v_attrs_map = import_vendor_attrs_map()
        updated_rows = [import_dashboard_row_to_dict(row_by_key[k] if k in row_by_key else next((r for r in all_import_rows if r.row_key == k), None), columns, vendor_attrs_map=_v_attrs_map) for k in updated_keys]
        # FIX V38: Re-inject total_purchase_amount ke setiap updated row.
        # Same fix as /api/import/cell — total_purchase_amount tidak disimpan
        # di data_json, di-compute on-the-fly. Tanpa re-inject, cell TOTAL
        # PUR AMT jadi kosong setelah batch edit (mis. toggle checkbox).
        try:
            # Build YUPI PO → total map from ALL import rows
            _yupi_totals = {}
            for _r in all_import_rows:
                try: _d = json.loads(_r.data_json or '{}')
                except: _d = {}
                _d = apply_import_formula_columns(dict(_d))
                _yp = import_nonblank(_d.get('yupi_po')) or import_nonblank(_d.get('po_yupi'))
                if not _yp:
                    continue
                _yp_key = _yp.strip().lower()
                _pa = import_float_value(_d.get('purchase_amount'))
                if _pa is None:
                    _price = import_float_value(_d.get('purchase_price'))
                    _qty = import_float_value(_d.get('ord_qty'))
                    if _price is not None and _qty is not None:
                        _pa = _price * _qty
                if _pa is not None:
                    _yupi_totals[_yp_key] = _yupi_totals.get(_yp_key, 0.0) + _pa
            for _r in updated_rows:
                if not _r:
                    continue
                _ryp = import_nonblank(_r.get('yupi_po')) or import_nonblank(_r.get('po_yupi'))
                if _ryp:
                    _ryp_key = _ryp.strip().lower()
                    _r['total_purchase_amount'] = import_format_number(_yupi_totals[_ryp_key]) if _ryp_key in _yupi_totals else ''
                else:
                    _r['total_purchase_amount'] = ''
        except Exception:
            for _r in updated_rows:
                if _r:
                    _r['total_purchase_amount'] = _r.get('total_purchase_amount') or ''
        return jsonify({
            'success': True,
            'updated': len(sheet_items),
            'rows': [r for r in updated_rows if r is not None],
            'sheet_sync': sheet_sync,
            'skipped_missing': skipped_missing,
            'fuzzy_matched': len(fuzzy_matched_keys),
        })
    except Exception as e:
        db.session.rollback()
        import traceback; traceback.print_exc()
        return jsonify({'error': str(e), 'sheet_sync': {'synced': False, 'reason': str(e)}}), 500

# FIX V28: Admin endpoint untuk hard-purge SEMUA Import dashboard rows yang
# vendornya TIDAK match dengan uploaded Vendor Import list. Ini menyelesaikan
# masalah "52.140 Yupi POs" — setelah deploy fix V28 (layout sheet vendor
# filter), user perlu membersihkan 52k row lama yang sudah terlanjur masuk DB.
# Panggil endpoint ini SEKALI setelah deploy, lalu klik Copy Sheet untuk
# re-sync dengan vendor filter yang aktif.
@app.route('/api/admin/import-diagnostics', methods=['GET'])
def import_diagnostics():
    """Diagnostic endpoint untuk audit Import dashboard DB state.
    Returns: total row count, breakdown by source_key, vendor match analysis,
    sample row keys. Dipakai untuk debug "count masih 28k padahal purge 0"."""
    try:
        uploaded_vendor_names = import_uploaded_vendor_names()
        uploaded_vendor_set = {v.strip().lower() for v in uploaded_vendor_names if v and v.strip()}
        all_rows = ImportDashboardRow.query.all()
        by_source_key = {}
        vendor_match_count = 0
        vendor_no_match_count = 0
        no_vendor_count = 0
        sample_no_match_vendors = []
        sample_no_vendor_keys = []
        for row in all_rows:
            sk = row.source_key or '(empty)'
            by_source_key[sk] = by_source_key.get(sk, 0) + 1
            try: data = json.loads(row.data_json or '{}')
            except: data = {}
            vendor = import_nonblank(data.get('vendor')) or import_nonblank(data.get('vendor_name')) or import_nonblank(row.vendor_name)
            if not vendor:
                no_vendor_count += 1
                if len(sample_no_vendor_keys) < 5:
                    sample_no_vendor_keys.append(row.row_key)
            elif uploaded_vendor_set and import_vendor_match(vendor, uploaded_vendor_set):
                vendor_match_count += 1
            else:
                vendor_no_match_count += 1
                if len(sample_no_match_vendors) < 10:
                    sample_no_match_vendors.append({'row_key': row.row_key, 'vendor': vendor, 'source_key': sk})
        return jsonify({
            'success': True,
            'total_rows_in_db': len(all_rows),
            'breakdown_by_source_key': by_source_key,
            'uploaded_vendor_count': len(uploaded_vendor_set),
            'uploaded_vendor_names': list(uploaded_vendor_set)[:20],
            'vendor_match_count': vendor_match_count,
            'vendor_no_match_count': vendor_no_match_count,
            'no_vendor_count': no_vendor_count,
            'sample_no_match_vendors': sample_no_match_vendors,
            'sample_no_vendor_keys': sample_no_vendor_keys,
            '_IMPORT_VISIBLE_SOURCE_KEYS': list(_IMPORT_VISIBLE_SOURCE_KEYS),
            '_LEGACY_IMPORT_SOURCE_KEYS': list(_LEGACY_IMPORT_SOURCE_KEYS),
        })
    except Exception as e:
        import traceback; traceback.print_exc()
        return jsonify({'error': str(e)}), 500

@app.route('/api/admin/purge-non-vendor-import-rows', methods=['POST'])
def purge_non_vendor_import_rows():
    try:
        uploaded_vendor_names = import_uploaded_vendor_names()
        uploaded_vendor_set = {v.strip().lower() for v in uploaded_vendor_names if v and v.strip()}
        all_rows = ImportDashboardRow.query.filter(
            ImportDashboardRow.source_key.in_(_IMPORT_VISIBLE_SOURCE_KEYS)
        ).all()
        rows_to_purge = []
        for row in all_rows:
            try: data = json.loads(row.data_json or '{}')
            except: data = {}
            vendor = import_nonblank(data.get('vendor')) or import_nonblank(data.get('vendor_name')) or import_nonblank(row.vendor_name)
            if not vendor:
                # No vendor → purge (stale leftover)
                rows_to_purge.append(row)
                continue
            if uploaded_vendor_set and not import_vendor_match(vendor, uploaded_vendor_set):
                # Vendor doesn't match uploaded list → purge
                rows_to_purge.append(row)
            elif not uploaded_vendor_set:
                # No uploaded vendor list → purge ALL rows (user must upload
                # vendor list first before re-sync). This is intentional —
                # without a vendor list, the dashboard would re-import 52k
                # rows on next Copy Sheet.
                rows_to_purge.append(row)
        purged_count = len(rows_to_purge)
        for row in rows_to_purge:
            db.session.delete(row)
        db.session.commit()
        clear_runtime_caches()
        return jsonify({
            'success': True,
            'purged': purged_count,
            'remaining': len(all_rows) - purged_count,
            'uploaded_vendor_count': len(uploaded_vendor_set),
            'message': f'Purged {purged_count} non-vendor Import rows. {len(all_rows) - purged_count} rows remain.'
        })
    except Exception as e:
        db.session.rollback()
        import traceback; traceback.print_exc()
        return jsonify({'error': str(e)}), 500

# FIX V31: Diagnostic endpoint untuk inspect semua row dengan YUPI PO tertentu.
# Dipakai untuk debug "PO 410300121 ada double, filter hanya muncul 1 row".
# Return: semua row di DB dengan yupi_po tersebut, beserta data_json lengkap,
# source_key, source_uid, row_key, timestamps. Ini membantu identify kenapa
# 2 row untuk PO yang sama punya data berbeda.
@app.route('/api/admin/inspect-po/<yupi_po>', methods=['GET'])
def inspect_po(yupi_po):
    try:
        yupi_po_clean = clean(yupi_po).strip().lower()
        if not yupi_po_clean:
            return jsonify({'error': 'yupi_po is required'}), 400
        all_rows = ImportDashboardRow.query.filter(
            ImportDashboardRow.source_key.in_(_IMPORT_VISIBLE_SOURCE_KEYS)
        ).all()
        matching = []
        for row in all_rows:
            try: data = json.loads(row.data_json or '{}')
            except: data = {}
            data = apply_import_formula_columns(dict(data))
            row_yupi = import_nonblank(data.get('yupi_po')) or import_nonblank(data.get('po_yupi'))
            if row_yupi and row_yupi.strip().lower() == yupi_po_clean:
                matching.append({
                    'row_key': row.row_key,
                    'source_key': row.source_key,
                    'source_uid': row.source_uid,
                    'sheet_row': row.sheet_row,
                    'vendor_name': row.vendor_name,
                    'first_seen_at': row.first_seen_at.isoformat() if row.first_seen_at else None,
                    'last_seen_at': row.last_seen_at.isoformat() if row.last_seen_at else None,
                    'updated_at': row.updated_at.isoformat() if row.updated_at else None,
                    'data': {
                        'yupi_po': data.get('yupi_po'),
                        'po_yupi': data.get('po_yupi'),
                        'item_yupi': data.get('item_yupi'),
                        'po_sementara': data.get('po_sementara'),
                        'req_dlv_date': data.get('req_dlv_date'),
                        'source_req_dlv_date': data.get('source_req_dlv_date'),
                        'status': data.get('status'),
                        'po_send_date': data.get('po_send_date'),
                        'eta': data.get('eta'),
                        'etd': data.get('etd'),
                        'sap_input': data.get('sap_input'),
                        'vendor': data.get('vendor'),
                        'vendor_name': data.get('vendor_name'),
                        'item_name': data.get('item_name'),
                        'spec': data.get('spec'),
                        'ord_qty': data.get('ord_qty'),
                        'amount': data.get('amount'),
                        'purchase_amount': data.get('purchase_amount'),
                    },
                })
        return jsonify({
            'success': True,
            'yupi_po_searched': yupi_po,
            'total_matching_rows': len(matching),
            'rows': matching,
        })
    except Exception as e:
        import traceback; traceback.print_exc()
        return jsonify({'error': str(e)}), 500

# FIX V32: Propagate manual data across rows with same YUPI PO.
# TIDAK menghapus row apapun — hanya copy group-level manual fields
# (status, eta, sap_input, dll.) dari row terkaya ke semua row lain dengan
# yupi_po yang sama. Ini menyelesaikan bug "PO 410300121 ada 2 row, 1 kosong
# 1 ada data manual" TANPA menghapus line items yang legitimate.
#
# Group-level fields = field yang shared across all line items of same PO
# (lihat GROUP_LEVEL_FIELDS di /api/import/cells). Per-item fields
# (item_yupi, item_name, spec, ord_qty, dll.) TIDAK di-propagate — mereka
# unique per line item.
@app.route('/api/admin/propagate-manual-data', methods=['POST'])
def propagate_manual_data():
    try:
        all_rows = ImportDashboardRow.query.filter(
            ImportDashboardRow.source_key.in_(_IMPORT_VISIBLE_SOURCE_KEYS)
        ).order_by(ImportDashboardRow.id.asc()).all()
        # Group by yupi_po ONLY (regardless of req_dlv_date or item_yupi).
        # All line items of the same PO share the same group-level manual data.
        groups = {}
        for row in all_rows:
            try: data = json.loads(row.data_json or '{}')
            except: data = {}
            data = apply_import_formula_columns(dict(data))
            yupi = import_nonblank(data.get('yupi_po')) or import_nonblank(data.get('po_yupi'))
            if not yupi:
                continue
            groups.setdefault(yupi.strip().lower(), []).append((row, data))
        # Group-level manual fields yang harus konsisten across all line items
        GROUP_LEVEL_MANUAL_FIELDS = [
            'status', 'po_send_date',
            'etd', 'eta', 'import_remarks',
            'incoterm', 'forwarder', 'bl_number', 'inv_no',
            'sap_input', 'payment', 'payment_date', 'soft_copy_doc', 'non_ski',
            'bl_awb', 'invoice', 'pl', 'hc', 'msds', 'coa', 'coo',
        ]
        propagated_count = 0
        rows_updated = 0
        for yupi_key, items in groups.items():
            if len(items) <= 1:
                continue  # single line item, nothing to propagate
            # Find the "richest" row = row with most non-empty manual fields.
            # This row's manual data will be propagated to all others.
            def richness(item):
                data = item[1]
                return sum(1 for f in GROUP_LEVEL_MANUAL_FIELDS if import_nonblank(data.get(f)))
            items.sort(key=richness, reverse=True)
            master_row, master_data = items[0]
            # Propagate master's manual fields to all other rows in the group.
            # Per-item fields (item_yupi, spec, ord_qty, dll.) are LEFT UNTOUCHED.
            for target_row, target_data in items[1:]:
                changed = False
                for field in GROUP_LEVEL_MANUAL_FIELDS:
                    master_val = import_nonblank(master_data.get(field))
                    target_val = import_nonblank(target_data.get(field))
                    # Only propagate if master has a value AND target is empty/different.
                    # This ensures all line items show the same group-level data.
                    if master_val and target_val != master_val:
                        target_data[field] = master_val
                        changed = True
                if changed:
                    target_row.data_json = json.dumps(target_data, ensure_ascii=False)
                    target_row.updated_at = datetime.utcnow()
                    rows_updated += 1
            propagated_count += 1
        db.session.commit()
        clear_runtime_caches()
        return jsonify({
            'success': True,
            'groups_processed': propagated_count,
            'rows_updated': rows_updated,
            'message': f'Propagated manual data across {propagated_count} PO group(s), updated {rows_updated} row(s). NO rows deleted.'
        })
    except Exception as e:
        db.session.rollback()
        import traceback; traceback.print_exc()
        return jsonify({'error': str(e)}), 500

# FIX V31b: Merge TRUE duplicates only — rows with same (yupi_po + item_yupi
# + po_sementara + req_dlv_date). These are genuine duplicates (same item
# appearing twice), NOT different line items. Different line items have
# different item_yupi/po_sementara and are NEVER merged.
# WARNING: This endpoint is conservative. Only use if you're sure there are
# true duplicates. For "PO has 2 rows with different manual data", use
# /api/admin/propagate-manual-data instead (it doesn't delete anything).
@app.route('/api/admin/merge-import-duplicates', methods=['POST'])
def merge_import_duplicates():
    try:
        columns = import_layout_columns()
        all_rows = ImportDashboardRow.query.filter(
            ImportDashboardRow.source_key.in_(_IMPORT_VISIBLE_SOURCE_KEYS)
        ).order_by(ImportDashboardRow.id.asc()).all()
        # Group by FULL identity (yupi_po + item_yupi + po_sementara + req_dlv_date)
        # — same as import_row_source_uid. Only TRUE duplicates (same item twice)
        # are merged. Different line items (different item_yupi) are NEVER merged.
        groups = {}
        for row in all_rows:
            try: data = json.loads(row.data_json or '{}')
            except: data = {}
            data = apply_import_formula_columns(dict(data))
            yupi = import_nonblank(data.get('yupi_po')) or import_nonblank(data.get('po_yupi'))
            if not yupi:
                continue
            item_yupi = import_nonblank(data.get('item_yupi')) or '(none)'
            po_sementara = import_nonblank(data.get('po_sementara')) or '(none)'
            req_dlv = import_nonblank(data.get('req_dlv_date')) or import_nonblank(data.get('source_req_dlv_date')) or '(none)'
            group_key = f"{yupi.strip().lower()}|{item_yupi.strip().lower()}|{po_sementara.strip().lower()}|{str(req_dlv).strip().lower()}"
            groups.setdefault(group_key, []).append((row, data))
        merged_count = 0
        deleted_count = 0
        for group_key, items in groups.items():
            if len(items) <= 1:
                continue  # no true duplicates
            def richness(item):
                data = item[1]
                manual_fields = ['status', 'po_send_date', 'eta', 'etd', 'sap_input',
                                 'incoterm', 'forwarder', 'bl_number', 'inv_no',
                                 'import_remarks', 'payment', 'payment_date',
                                 'soft_copy_doc', 'non_ski', 'bl_awb', 'invoice',
                                 'pl', 'hc', 'msds', 'coa', 'coo']
                return sum(1 for f in manual_fields if import_nonblank(data.get(f)))
            items.sort(key=richness, reverse=True)
            master_row, master_data = items[0]
            for dup_row, dup_data in items[1:]:
                for field in IMPORT_LOCAL_EDIT_FIELDS:
                    master_val = import_nonblank(master_data.get(field))
                    dup_val = import_nonblank(dup_data.get(field))
                    if not master_val and dup_val:
                        master_data[field] = dup_val
                for field in IMPORT_SOURCE_MANAGED_FIELDS:
                    master_val = import_nonblank(master_data.get(field))
                    dup_val = import_nonblank(dup_data.get(field))
                    if not master_val and dup_val:
                        master_data[field] = dup_val
            master_row.data_json = json.dumps(master_data, ensure_ascii=False)
            master_row.updated_at = datetime.utcnow()
            for dup_row, dup_data in items[1:]:
                db.session.delete(dup_row)
                deleted_count += 1
            merged_count += 1
        db.session.commit()
        clear_runtime_caches()
        return jsonify({
            'success': True,
            'groups_merged': merged_count,
            'duplicates_deleted': deleted_count,
            'message': f'Merged {merged_count} TRUE duplicate group(s) (same item_yupi+po_sementara), deleted {deleted_count} duplicate row(s). Different line items NOT touched.'
        })
    except Exception as e:
        db.session.rollback()
        import traceback; traceback.print_exc()
        return jsonify({'error': str(e)}), 500

