# V60y6: Database integrity check + repair endpoint
@app.route('/api/db/repair', methods=['POST'])
def db_repair():
    """Check and repair SQLite database corruption ('database disk image is malformed').
    V61 SECURITY FIX: POST only + wajib header X-Admin-Key (guard before_request).
    Jika ?recreate=1 dikirim, semua tabel di-drop dan dibuat ulang (data hilang)."""
    try:
        results = {}

        # V60z3: If recreate=1, nuke everything and start fresh
        recreate = str(request.args.get('recreate', '')).lower() in ('1', 'true', 'yes')
        if recreate:
            try:
                db.drop_all()
                db.create_all()
                db.session.commit()
                clear_runtime_caches()
                results['recreate'] = 'done — all tables dropped and recreated'
                results['status'] = 'database recreated from scratch. Please re-upload all data.'
                return jsonify({'success': True, 'results': results})
            except Exception as rec_err:
                return jsonify({'success': False, 'error': f'Recreate failed: {rec_err}'}), 500

        # 1. Integrity check
        integrity = db.session.execute(text('PRAGMA integrity_check')).fetchall()
        results['integrity_check'] = [str(r[0]) for r in integrity]

        if results['integrity_check'] != ['ok']:
            # 2. Attempt recovery: reindex all tables
            try:
                db.session.execute(text('REINDEX'))
                db.session.commit()
                results['reindex'] = 'done'
            except Exception as re_err:
                results['reindex_error'] = str(re_err)

            # 3. Try VACUUM
            try:
                db.session.execute(text('VACUUM'))
                db.session.commit()
                results['vacuum'] = 'done'
            except Exception as v_err:
                results['vacuum_error'] = str(v_err)

            # 4. Re-check integrity
            try:
                integrity2 = db.session.execute(text('PRAGMA integrity_check')).fetchall()
                results['integrity_check_after'] = [str(r[0]) for r in integrity2]
            except Exception:
                results['integrity_check_after'] = ['check failed']

            # 4b. V63.8: pemulihan penuh (.recover / salvage Python) bila masih rusak
            if results.get('integrity_check_after', ['ok']) != ['ok']:
                try:
                    import db_recovery as _dbrec8
                    _dbf8 = app.config['SQLALCHEMY_DATABASE_URI'].replace('sqlite:///', '', 1)
                    try:
                        db.engine.dispose()
                    except Exception:
                        pass
                    _ok8, _dst8, _met8, _inf8 = _dbrec8.recover(_dbf8)
                    if _ok8:
                        _dbrec8.swap_in(_dbf8, _dst8)
                        _ic8 = db.session.execute(text('PRAGMA integrity_check')).fetchall()
                        results['integrity_check_after'] = [str(r[0]) for r in _ic8]
                        results['recover'] = f'berhasil via {_met8} ({_inf8})'
                    else:
                        results['recover'] = f'gagal via {_met8}: {_inf8}'
                except Exception as _e8:
                    results['recover_error'] = str(_e8)

            # 5. If still corrupted, suggest recreate
            if results.get('integrity_check_after', ['ok']) != ['ok']:
                results['suggestion'] = ('Database masih rusak. Kirim POST /api/db/repair?recreate=1 '
                                         'dengan header X-Admin-Key untuk membuat ulang semua tabel '
                                         '(data hilang — perlu upload ulang).')
        else:
            results['status'] = 'database is healthy'

        return jsonify({'success': True, 'results': results})
    except Exception as e:
        import traceback; traceback.print_exc()
        return jsonify({'success': False, 'error': str(e)}), 500


# ── V63.9: LAPORAN & PEMBERSIHAN KUOTA DISK (PythonAnywhere 512 MB) ─────────
@app.route('/api/disk/cleanup', methods=['POST'])
def disk_cleanup():
    """POST /api/disk/cleanup         -> laporan penggunaan disk (dry-run).
    POST /api/disk/cleanup?apply=1   -> jalankan pembersihan + byte dibebaskan.
    Wajib header X-Admin-Key (guard V61). Menangani: cache pip, backup DB rotasi
    (maks 2), arsip DB korup (maks 1), __pycache__, sisa salinan Excel
    upload_jobs, checkpoint WAL. Folder dist/ HANYA dilaporkan."""
    rep = {'dry_run': True, 'freed_bytes': 0, 'freed_human': '0 MB', 'actions': [], 'sizes': {}}
    try:
        apply = str(request.args.get('apply', '')).lower() in ('1', 'true', 'yes')
        rep['dry_run'] = not apply

        def _mb(n):
            return round(n / 1048576.0, 1)

        inst_dir = os.path.dirname(_UPLOAD_JOB_DIR)
        app_dir = os.path.dirname(inst_dir)
        home = _HOME_V639
        rep['sizes'] = {
            'instance_mb': _mb(_dir_size_bytes(inst_dir)),
            'instance_backups_mb': _mb(_dir_size_bytes(os.path.join(inst_dir, 'backups'))),
            'instance_upload_jobs_mb': _mb(_dir_size_bytes(_UPLOAD_JOB_DIR)),
            'pip_cache_mb': _mb(_dir_size_bytes(os.path.join(home, '.cache', 'pip'))),
            'pycache_mb': _mb(_dir_size_bytes(os.path.join(app_dir, '__pycache__'))),
            'dist_mb': _mb(_dir_size_bytes(os.path.join(app_dir, 'dist'))),
        }
        try:
            import glob as _g10
            _bdir10 = os.path.join(inst_dir, 'backups')
            rep['sizes']['instance_backups_raw_mb'] = _mb(sum(
                os.path.getsize(p) for p in _g10.glob(os.path.join(_bdir10, 'po_database_*.db')) if os.path.isfile(p)))
            rep['sizes']['instance_backups_gz_mb'] = _mb(sum(
                os.path.getsize(p) for p in _g10.glob(os.path.join(_bdir10, 'po_database_*.db.gz')) if os.path.isfile(p)))
        except Exception:
            pass
        try:
            import shutil as _sh10b
            rep['sizes']['home_free_mb'] = _mb(_sh10b.disk_usage(home).free)
        except Exception:
            pass
        try:
            top = []
            for name in os.listdir(home):
                p = os.path.join(home, name)
                try:
                    sz = _dir_size_bytes(p) if os.path.isdir(p) else os.path.getsize(p)
                except Exception:
                    sz = 0
                top.append((name + ('/' if os.path.isdir(p) else ''), sz))
            top.sort(key=lambda kv: kv[1], reverse=True)
            rep['sizes']['home_top'] = [{'name': n, 'mb': _mb(s)} for n, s in top[:12] if s > 0]
        except Exception:
            pass
        if apply:
            freed = 0
            _f, _did = _clean_pip_cache(force=True)
            if _did:
                rep['actions'].append('cache pip dibersihkan: %s MB' % _mb(_f)); freed += _f
            _f = _rotate_db_backups()
            if _f:
                rep['actions'].append('backup DB lama dihapus: %s MB' % _mb(_f)); freed += _f
            _f = _migrate_backups()
            if _f:
                rep['actions'].append('backup DB mentah dikompresi ke .db.gz: %s MB dibebaskan' % _mb(_f)); freed += _f
            _f = _rotate_corrupt_archives()
            if _f:
                rep['actions'].append('arsip DB korup lama dihapus: %s MB' % _mb(_f)); freed += _f
            _f = _clean_app_pycache()
            if _f:
                rep['actions'].append('__pycache__ dibersihkan: %s MB' % _mb(_f)); freed += _f
            try:
                _n9 = _upload_job_disk_sweep()
                if _n9: rep['actions'].append('janitor upload_jobs: %d file/direktori dihapus' % _n9)
            except Exception:
                pass
            rep['freed_bytes'] = freed
            rep['freed_human'] = '%s MB' % _mb(freed)
        rep['hint'] = ('dist/ hanya dilaporkan. Hapus manual dari Bash console bila yakin '
                       'tidak dipakai: rm -rf ~/mysite/dist (cek dulu isinya).')
        return jsonify({'success': True, 'report': rep})
    except Exception as e:
        import traceback; traceback.print_exc()
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/diagnostics/google-sheets', methods=['GET'])
def diagnostics_google_sheets():
    if os.environ.get('SERVEONE_DESKTOP_MODE') == '1':
        access=_desktop_google_access()
        return jsonify({'mode':'read_only','credentials':access.status(),'service_account_required':False})
    """Lightweight, secret-safe diagnostic for Google Sheets sync failures.
    Checks: service-account credential presence/parse, token refresh, proxy
    env vars, and one real metadata call against the RFQ sheet — without ever
    echoing the credential, token, or proxy URL contents back to the caller.
    """
    result = {'credential_configured': False, 'token_ok': False, 'proxy_env': {}, 'sheets_api_reachable': False}
    result['proxy_env'] = {
        'HTTPS_PROXY': bool(os.environ.get('HTTPS_PROXY')),
        'HTTP_PROXY': bool(os.environ.get('HTTP_PROXY')),
        'https_proxy': bool(os.environ.get('https_proxy')),
        'http_proxy': bool(os.environ.get('http_proxy')),
    }
    try:
        credentials_info = rfq_sheet_sync_credentials()
        result['credential_configured'] = bool(credentials_info)
        if not credentials_info:
            result['error'] = 'No GOOGLE_SERVICE_ACCOUNT_JSON / GOOGLE_SERVICE_ACCOUNT_FILE configured'
            return jsonify(result), 200
        result['service_account_email'] = credentials_info.get('client_email')
    except Exception as e:
        result['error'] = f'Failed to load/parse credential: {e}'
        return jsonify(result), 200
    try:
        google_sheets_access_token()
        result['token_ok'] = True
    except Exception as e:
        result['error'] = f'Failed to obtain access token: {e}'
        return jsonify(result), 200
    try:
        meta = google_sheets_metadata(RFQ_SHEET_ID)
        result['sheets_api_reachable'] = True
        result['rfq_sheet_title'] = (meta.get('properties') or {}).get('title')
    except Exception as e:
        result['error'] = f'Metadata call to RFQ sheet failed: {e}'
        return jsonify(result), 200
    return jsonify(result), 200


