# V63.27.73: bounded, RAM-only performance monitoring for administrators.
# No user IP or request query strings stored; helps identify actual slow pages.
from collections import deque as _perf_deque
_PERF_SLOW_REQUESTS_V632773 = _perf_deque(maxlen=60)
_PERF_LOCK_V632773 = threading.Lock()
_PERF_SLOW_MS_V632773 = max(250, int(os.environ.get('DASHBOARD_SLOW_REQUEST_MS', '1500')))

@app.before_request
def _perf_start_v632773():
    if (request.path or '').startswith('/api/'):
        g._perf_start_v632773 = time.perf_counter()

@app.after_request
def _perf_end_v632773(response):
    try:
        start = getattr(g, '_perf_start_v632773', None)
        if start is not None:
            duration_ms = round((time.perf_counter() - start) * 1000, 1)
            if duration_ms >= _PERF_SLOW_MS_V632773:
                row = {'at': datetime.utcnow().isoformat() + 'Z',
                       'path': request.path[:160], 'method': request.method,
                       'status': response.status_code, 'duration_ms': duration_ms,
                       'during_upload': _upload_proc_active()}
                with _PERF_LOCK_V632773:
                    _PERF_SLOW_REQUESTS_V632773.append(row)
                print('[slow-request] ' + json.dumps(row, separators=(',', ':')), flush=True)
    except Exception: pass
    return response

@app.route('/api/debug/performance', methods=['GET'])
def debug_performance_v632773():
    # /api/debug/* already requires ADMIN_PASSWORD / X-Admin-Key via guard.
    with _PERF_LOCK_V632773:
        slow = list(reversed(_PERF_SLOW_REQUESTS_V632773))
    with _UPLOAD_JOBS_LOCK:
        active = sum(1 for j in _UPLOAD_JOBS.values()
                     if j.get('status') in ('queued', 'processing', 'refreshing'))
    with _READ_CACHE_LOCK:
        cache_entries = len(_READ_RESPONSE_CACHE)
        cache_bytes = sum(_READ_CACHE_SIZES.values())
    return jsonify({'slow_requests': slow, 'slow_threshold_ms': _PERF_SLOW_MS_V632773,
                    'active_or_queued_uploads': active,
                    'response_cache_entries': cache_entries,
                    'response_cache_estimated_mb': round(cache_bytes / 1048576, 1),
                    'disk_cleaner_enabled': True,
                    'data_revision_checked_every_seconds': 3})

# ═══ V63.23: 500 JSON utk /api/* + petunjuk disk (widget & pill membaca) ════
@app.errorhandler(Exception)
def _v6323_json_error_handler(e):
    """Sebelumnya: exception tak tertangani -> HTML 500 (frontend hanya tahu
    'HTTP 500'). Kini: /api/* -> JSON {error, detail, disk_issue?, hint?}.
    HTTPException (404 dsb) diteruskan apa adanya. Saat error disk, guard
    pemulihan dipicu seketika."""
    from werkzeug.exceptions import HTTPException as _HTTPX6323
    if isinstance(e, _HTTPX6323):
        return e
    _msg = str(e)[:300]
    _low = _msg.lower()
    _disk_issue = (('disk i/o' in _low) or ('database is locked' in _low)
                   or ('disk is full' in _low) or ('database or disk is full' in _low)
                   or ('unable to open database file' in _low)
                   or ('malformed' in _low))
    if _disk_issue:
        try:
            _v6323_disk_guard('error-handler')
        except Exception:
            pass
    try:
        print(f'[v6323] 500 {request.path}: {_msg}', flush=True)
    except Exception:
        pass
    _payload = {'error': 'Internal server error', 'detail': _msg}
    if _disk_issue:
        _payload['disk_issue'] = True
        _payload['hint'] = ('Server storage is full or busy. The dashboard is '
                            'cleaning up automatically — click the red "Free space" '
                            'pill at the bottom-right, or open '
                            '/api/maintenance/disk-report for details. If the '
                            'error persists, run `python3 cleanup_disk.py --repair` '
                            'in the Bash console, then press Reload on the Web tab.')
    return jsonify(_payload), 500


# ── V63.27.4: laporan memori proses — verifikasi fix "RAM exceed limit 3GB" ──
@app.route('/api/maintenance/memory-report', methods=['GET'])
def maintenance_memory_report():
    """Snapshot RAM proses + pemakaian semua cache in-memory besar. Dipakai
    untuk memverifikasi efek byte-budget cache & ram-guard di PythonAnywhere:
    buka /api/maintenance/memory-report setelah deploy (admin key seperti
    disk-report bila diperlukan)."""
    try:
        rss = _v63_proc_rss_bytes()
        with _READ_CACHE_LOCK:
            n_entries = len(_READ_RESPONSE_CACHE)
            est_total = sum(_READ_CACHE_SIZES.get(k, 0) for k in _READ_RESPONSE_CACHE)
            _top = sorted(((k, _READ_CACHE_SIZES.get(k, 0)) for k in _READ_RESPONSE_CACHE),
                          key=lambda kv: -kv[1])[:8]
        top_list = [{'key': repr(k)[:120], 'est_mb': round(e / 1048576.0, 1)} for k, e in _top]
        with _SIMILARITY_LOCK:
            sim_n = len(_SIMILARITY_CACHE)
        out = {
            'generated_at': datetime.utcnow().isoformat() + 'Z',
            'version': 'V63.27.4',
            'rss_mb': round(rss / 1048576.0, 1),
            'soft_limit_mb': max(512, int(os.environ.get('PO_MONITOR_RAM_SOFT_MB', '2350'))),
            'guard': {
                'started': _RAM_GUARD_STATE.get('started', False),
                'clears': _RAM_GUARD_STATE.get('clears', 0),
                'last_rss_mb': round((_RAM_GUARD_STATE.get('last_rss') or 0) / 1048576.0, 1),
                'last_clear_ts': _RAM_GUARD_STATE.get('last_clear') or None,
            },
            'response_cache': {
                'entries': n_entries,
                'est_mb': round(est_total / 1048576.0, 1),
                'max_mb': int(_READ_CACHE_MAX_BYTES / 1048576.0),
                'entry_max_mb': int(_READ_CACHE_ENTRY_MAX_BYTES / 1048576.0),
                'top': top_list,
            },
            'similarity_cache': {'entries': sim_n, 'cap': _SIMILARITY_CACHE_MAX_ENTRIES},
            'gz_cache': len(_V67_GZ_CACHE),
            'threads': threading.active_count(),
            'gc': {'counts': list(_gc.get_count()), 'threshold': list(_gc.get_threshold())},
            'pandas_loaded': 'pandas' in _V67LazyModule._loaded,
        }
        return jsonify(out)
    except Exception as e:
        import traceback; traceback.print_exc()
        return jsonify({'error': str(e)}), 500

@app.route('/api/maintenance/disk-report', methods=['GET'])
def maintenance_disk_report():
    """V63.16: diagnosis kuota disk dari BROWSER (tanpa Bash console).
    Buka: /api/maintenance/disk-report
    Berisi: sisa kuota, ukuran folder aplikasi, isi instance/ (DB, WAL, backup,
    upload_jobs, arsip korup), statistik halaman SQLite (freelist = kandidat
    penyusutan VACUUM), 20 file terbesar di folder aplikasi, auto-vacuum state,
    dan 10 upload terakhir. Read-only; tidak mengubah apa pun."""
    import sqlite3 as _sq3
    out = {'generated_at': datetime.utcnow().isoformat() + 'Z', 'version': 'V63.27.11'}
    app_dir = os.environ.get('SERVEONE_DATA_DIR', os.path.dirname(os.path.abspath(__file__)))
    inst = os.path.join(app_dir, 'instance')
    dbp = os.path.join(inst, 'po_database.db')

    def _dsize(p):
        total = 0
        for r, _d, fs in os.walk(p):
            for fn in fs:
                try:
                    total += os.path.getsize(os.path.join(r, fn))
                except OSError:
                    pass
        return total

    try:
        du = _shutil.disk_usage(app_dir)
        out['disk'] = {
            'total_mb': round(du.total / 1048576.0, 1),
            'used_mb': round(du.used / 1048576.0, 1),
            'free_mb': round(du.free / 1048576.0, 1),
            'used_pct': round(du.used * 100.0 / du.total, 1) if du.total else None,
            'note': 'kuota PythonAnywhere mencakup SELURUH home directory; '
                    'jalankan python3 cleanup_disk.py di Bash console untuk '
                    'pemetaan di luar folder aplikasi (~/.cache/pip dll)',
        }
    except Exception as exc:
        out['disk'] = {'error': str(exc)[:200]}

    out['app_dir'] = {'path': app_dir, 'total_mb': round(_dsize(app_dir) / 1048576.0, 2)}

    # V63.27.11: /tmp dapat ikut terasa sebagai kuota di PythonAnywhere.
    # openpyxl write_only memakai /tmp/openpyxl.* sementara export berjalan.
    try:
        import glob as _glob_tmp
        _xltemps = []
        _xlbytes = 0
        for _fp in _glob_tmp.glob('/tmp/openpyxl.*'):
            try:
                if os.path.isfile(_fp):
                    _sz = os.path.getsize(_fp); _xlbytes += _sz
                    _xltemps.append({'name': os.path.basename(_fp),
                                     'mb': round(_sz / 1048576.0, 2),
                                     'age_min': round((time.time() - os.path.getmtime(_fp)) / 60.0, 1)})
            except Exception:
                pass
        _xltemps.sort(key=lambda x: x['mb'], reverse=True)
        out['openpyxl_temp'] = {
            'count': len(_xltemps),
            'mb': round(_xlbytes / 1048576.0, 2),
            'files': _xltemps[:20],
            'cleanup_rule': 'automatic janitor removes /tmp/openpyxl.* older than 60 minutes',
        }
    except Exception as _exc:
        out['openpyxl_temp'] = {'error': str(_exc)[:200]}

    biggest = []
    for r, _d, fs in os.walk(app_dir):
        for fn in fs:
            p = os.path.join(r, fn)
            try:
                biggest.append((os.path.getsize(p), os.path.relpath(p, app_dir)))
            except OSError:
                pass
    biggest.sort(reverse=True)
    out['biggest_files'] = [
        {'path': rel, 'mb': round(sz / 1048576.0, 2)} for sz, rel in biggest[:20]
    ]

    inst_info = {}
    try:
        inst_info['instance_mb'] = round(_dsize(inst) / 1048576.0, 2) if os.path.isdir(inst) else 0
        if os.path.isfile(dbp):
            inst_info['db_mb'] = round(os.path.getsize(dbp) / 1048576.0, 2)
        for suffix in ('-wal', '-shm'):
            p = dbp + suffix
            if os.path.isfile(p):
                inst_info[('wal' if suffix == '-wal' else 'shm') + '_mb'] = round(os.path.getsize(p) / 1048576.0, 2)
        bdir = os.path.join(inst, 'backups')
        if os.path.isdir(bdir):
            bks = []
            for fn in sorted(os.listdir(bdir)):
                p = os.path.join(bdir, fn)
                if os.path.isfile(p):
                    bks.append({'name': fn, 'mb': round(os.path.getsize(p) / 1048576.0, 2)})
            inst_info['backups'] = bks
            inst_info['backups_mb'] = round(sum(b['mb'] for b in bks), 2)
        jd = os.path.join(inst, 'upload_jobs')
        if os.path.isdir(jd):
            names = os.listdir(jd)
            inst_info['upload_jobs_count'] = len(names)
            inst_info['upload_jobs_mb'] = round(_dsize(jd) / 1048576.0, 2)
        corrupt = []
        if os.path.isdir(inst):
            for fn in os.listdir(inst):
                if '.corrupt_' in fn and os.path.isfile(os.path.join(inst, fn)):
                    corrupt.append({'name': fn, 'mb': round(os.path.getsize(os.path.join(inst, fn)) / 1048576.0, 2)})
        inst_info['corrupt_archives'] = corrupt
    except Exception as exc:
        inst_info['error'] = str(exc)[:200]
    out['instance'] = inst_info

    sql_info = {}
    try:
        if os.path.isfile(dbp):
            pc, fl, ps = _sqlite_page_stats(dbp)
            sql_info = {
                'page_count': pc,
                'freelist_pages': fl,
                'page_size': ps,
                'db_mb': round(pc * ps / 1048576.0, 2),
                'freelist_mb': round(fl * ps / 1048576.0, 2),
                'freelist_ratio': round(fl / float(pc), 3) if pc else 0,
                'vacuum_would_reclaim_mb': round(fl * ps / 1048576.0, 2),
            }
    except Exception as exc:
        sql_info = {'error': str(exc)[:200]}
    out['sqlite'] = sql_info
    # V63.27.11: tampilkan ukuran index sehingga pertumbuhan DB dapat
    # dibedakan dari data tabel/WAL/temp export.
    indexes_info = []
    try:
        if os.path.isfile(dbp):
            con_i = _sq3.connect(dbp, timeout=10)
            try:
                have_dbstat_i = True
                try: con_i.execute('SELECT 1 FROM dbstat LIMIT 1').fetchone()
                except Exception: have_dbstat_i = False
                idx_names = [r[0] for r in con_i.execute(
                    "SELECT name FROM sqlite_master WHERE type='index' AND name NOT LIKE 'sqlite_%' ORDER BY name"
                )]
                for name in idx_names:
                    mb = None
                    if have_dbstat_i:
                        try:
                            b = con_i.execute('SELECT COALESCE(SUM(pgsize),0) FROM dbstat WHERE name=?', (name,)).fetchone()[0] or 0
                            mb = round(float(b) / 1048576.0, 2)
                        except Exception:
                            pass
                    indexes_info.append({'name': name, 'mb': mb})
            finally:
                con_i.close()
            indexes_info.sort(key=lambda x: (x['mb'] is not None, x['mb'] or 0), reverse=True)
    except Exception as _exc:
        indexes_info = [{'error': str(_exc)[:200]}]
    out['indexes'] = indexes_info

    st = dict(_AUTO_VACUUM_STATE)
    st['running'] = bool(st.get('running'))
    out['auto_vacuum'] = st

    # V63.23: status self-healing guard + saran aksi (dipakai pill UI browser)
    try:
        with _V6323_GUARD_LOCK:
            _g6323 = json.loads(json.dumps(_V6323_GUARD))
        _g6323['threshold_mb'] = _V6323_DISK_GUARD_MB
        out['guard'] = _g6323
    except Exception:
        out['guard'] = {'error': 'unavailable'}
    _free_mb6323 = None
    try:
        _free_mb6323 = (out.get('disk') or {}).get('free_mb')
    except Exception:
        pass
    # V63.24: probe tulis — detektor kuota penuh yang SEJATI (disk host menipu
    # di PythonAnywhere: kuota 512MB bisa 100% penuh sementara disk host
    # melaporkan 1+ TB free; SQLite lalu gagal 'disk I/O error' di semua write,
    # bahkan SELECT yang menyentuh WAL).
    _probe_ok6324, _probe_err6324 = (True, '')
    try:
        if os.path.isfile(dbp):
            _probe_ok6324, _probe_err6324 = _v6324_write_probe(dbp)
    except Exception as _exc:
        _probe_ok6324, _probe_err6324 = False, str(_exc)[:200]
    out['probe'] = {'ok': bool(_probe_ok6324), 'error': _probe_err6324}
    _wal_mb6324 = 0.0
    try:
        _wal_mb6324 = float((out.get('instance') or {}).get('wal_mb') or 0.0)
    except Exception:
        pass
    out['action_required'] = _v6324_action_required(_free_mb6323, _probe_ok6324, _wal_mb6324)
    if out['action_required'] and not _probe_ok6324:
        out['advice'] = ('Storage quota is exhausted — SQLite writes are failing. '
                         'Fix (no deploy needed): in the Bash console run '
                         '`python3 cleanup_disk.py --repair` (backs the DB up to '
                         '/tmp, drops the lost_and_found recovery table, compacts '
                         'the DB via /tmp and restores it), then press Reload on '
                         'the Web tab. If cleanup_disk.py is still an old version, '
                         're-upload it from the latest package first.')
    elif out['action_required'] and _wal_mb6324 > 100:
        out['advice'] = ('The SQLite -wal file is very large (' + str(_wal_mb6324)
                         + ' MB). Run `python3 cleanup_disk.py --apply --vacuum` '
                         'in the Bash console, or --repair if writes keep failing.')
    elif out['action_required']:
        out['advice'] = ('Disk almost full. The dashboard drops the lost_and_found '
                         'recovery table automatically when free space is under '
                         '150 MB and trims DB backups. For a deeper clean run: '
                         'python3 cleanup_disk.py --apply --vacuum (Bash console).')
    else:
        out['advice'] = ''

    # V63.17: breakdown ukuran PER TABEL — terlihat jelas tabel apa yang
    # memakan ruang (mis. lost_and_found sisa pemulihan DB korup).
    tables_info = []
    try:
        if os.path.isfile(dbp):
            con_t = _sq3.connect(dbp, timeout=10)
            try:
                tnames = [r[0] for r in con_t.execute(
                    "SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name")]
                have_dbstat = True
                try:
                    con_t.execute('SELECT 1 FROM dbstat LIMIT 1').fetchone()
                except Exception:
                    have_dbstat = False
                for tn in tnames:
                    cnt = None
                    mb = None
                    try:
                        cnt = con_t.execute('SELECT COUNT(*) FROM "%s"' % tn.replace('"', '""')).fetchone()[0]
                    except Exception:
                        pass
                    if have_dbstat:
                        try:
                            mb = round(con_t.execute('SELECT SUM(pgsize) FROM dbstat WHERE name=?', (tn,)).fetchone()[0] / 1048576.0, 2)
                        except Exception:
                            mb = None
                    tables_info.append({'name': tn, 'rows': cnt, 'mb': mb})
            finally:
                con_t.close()
    except Exception as exc:
        tables_info = [{'error': str(exc)[:200]}]
    out['tables'] = tables_info

    try:
        rows = UploadLog.query.order_by(UploadLog.id.desc()).limit(10).all()
        out['recent_uploads'] = [
            {'file_type': r.file_type, 'filename': r.filename,
             'records_count': r.records_count,
             'uploaded_at': r.uploaded_at.isoformat() if r.uploaded_at else None}
            for r in rows
        ]
    except Exception as exc:
        out['recent_uploads'] = {'error': str(exc)[:200]}

    return jsonify(out)


@app.route('/api/maintenance/lost-and-found', methods=['GET', 'POST'])
def maintenance_lost_and_found():
    """V63.17: tabel lost_and_found = sisa pemulihan `sqlite3 .recover` ketika
    DB pernah korup (db_recovery.autoheal). Baris DB korup yang tak bisa
    dipetakan ke tabel asli ditampung di situ — bukan data aktif.

    GET                -> info: exists, rows, mb, kolom, 5 baris contoh.
    GET ?export=csv    -> unduh seluruh isi tabel sebagai CSV (pengaman sebelum drop).
    POST               -> DROP tabel + VACUUM (force, tunggu selesai) +
                          ukuran DB sebelum/sesudah. Nama tabel HARDCODED —
                          endpoint ini tidak bisa menghapus tabel lain."""
    import sqlite3 as _sq3
    app_dir = os.environ.get('SERVEONE_DATA_DIR', os.path.dirname(os.path.abspath(__file__)))
    dbp = os.path.join(app_dir, 'instance', 'po_database.db')
    explanation = ('lost_and_found dibuat oleh sqlite3 .recover saat DB pernah korup dan '
                   'dipulihkan (insiden "database disk image is malformed"). Isinya baris '
                   'bekas DB korup yang tidak bisa dipetakan ke tabel asli - BUKAN data '
                   'aktif dashboard. Aman dihapus; sumber kebenaran data tetap file '
                   'Excel/Google Sheet yang dapat di-upload ulang kapan pun.')
    if not os.path.isfile(dbp):
        return jsonify({'exists': False, 'error': 'DB tidak ditemukan', 'explanation': explanation})

    if request.method == 'GET' and str(request.args.get('export', '')).lower() in ('1', 'true', 'csv', 'yes'):
        con = _sq3.connect(dbp, timeout=15)
        exists = con.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name='lost_and_found'").fetchone()
        if not exists:
            con.close()
            return jsonify({'exists': False, 'explanation': explanation})
        cur = con.execute('SELECT * FROM lost_and_found')
        cols = [d[0] for d in cur.description]

        def _gen():
            import csv as _csv
            try:
                buf = io.StringIO()
                w = _csv.writer(buf)
                w.writerow(cols)
                buf.seek(0)
                yield buf.read()
                n = 0
                while True:
                    rows = cur.fetchmany(2000)
                    if not rows or n > 2_000_000:
                        break
                    buf.seek(0)
                    buf.truncate(0)
                    for r in rows:
                        w.writerow(['' if v is None else str(v) for v in r])
                        n += 1
                    buf.seek(0)
                    yield buf.read()
            finally:
                try:
                    con.close()
                except Exception:
                    pass
        from flask import Response as _Resp, stream_with_context as _swc
        return _Resp(_swc(_gen()), mimetype='text/csv',
                     headers={'Content-Disposition': 'attachment; filename=lost_and_found_export.csv'})

    con = _sq3.connect(dbp, timeout=15)
    try:
        exists = con.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name='lost_and_found'").fetchone()
        out = {'exists': bool(exists), 'explanation': explanation, 'version': 'V63.27'}
        if not exists:
            out['message'] = 'Tabel lost_and_found tidak ada — DB bersih.'
            return jsonify(out)
        out['rows'] = con.execute('SELECT COUNT(*) FROM lost_and_found').fetchone()[0]
        try:
            out['columns'] = [r[1] for r in con.execute('PRAGMA table_info(lost_and_found)')]
        except Exception:
            pass
        try:
            out['sample'] = [[('' if v is None else str(v))[:60] for v in r]
                             for r in con.execute('SELECT * FROM lost_and_found LIMIT 5')]
        except Exception:
            pass
        try:
            out['mb'] = round(con.execute('SELECT SUM(pgsize) FROM dbstat WHERE name=?', ('lost_and_found',)).fetchone()[0] / 1048576.0, 2)
        except Exception:
            pass
    finally:
        con.close()

    if request.method == 'POST':
        size_before = os.path.getsize(dbp)
        con = _sq3.connect(dbp, timeout=30, isolation_level=None)
        try:
            con.execute('PRAGMA busy_timeout=30000')
            con.execute('DROP TABLE lost_and_found')
        finally:
            con.close()
        size_after_drop = os.path.getsize(dbp)
        try:
            maybe_auto_vacuum('drop-lost-and-found', force=True)
            t0 = time.time()
            while _AUTO_VACUUM_STATE.get('running') and time.time() - t0 < 300:
                time.sleep(0.5)
        except Exception as exc:
            out['vacuum_error'] = str(exc)[:200]
        # V63.17: di mode WAL penyusutan FISIK file baru final setelah
        # checkpoint TRUNCATE — jalankan sebelum mengukur.
        try:
            con_ck = _sq3.connect(dbp, timeout=15, isolation_level=None)
            try:
                con_ck.execute('PRAGMA wal_checkpoint(TRUNCATE)')
            finally:
                con_ck.close()
        except Exception:
            pass
        try:
            _pcv, _flv, _psv = _sqlite_page_stats(dbp)
            out['db_mb_after_vacuum'] = round(_pcv * _psv / 1048576.0, 2)
        except Exception:
            pass
        size_after_vacuum = os.path.getsize(dbp)
        out.update({
            'dropped': True,
            'db_mb_before': round(size_before / 1048576.0, 2),
            'db_mb_after_drop': round(size_after_drop / 1048576.0, 2),
            'db_mb_after_vacuum_physical': round(size_after_vacuum / 1048576.0, 2),
            'vacuum_state': dict(_AUTO_VACUUM_STATE),
            'note': 'Tabel dihapus & file DB disusutkan. Reload halaman dashboard untuk memastikan data normal.',
        })
    return jsonify(out)


