@app.route('/api/access/me', methods=['GET'])
def access_me_v632740():
    # Satisfy any legacy access-status client without registering a fake device.
    # The desktop session has already been checked before this endpoint.
    if os.environ.get('SERVEONE_DESKTOP_MODE') == '1':
        return jsonify({'registered': True, 'blocked': False, 'nickname': 'Local User',
                        'device_id': 'desktop-local', 'browser': 'Desktop App', 'os_name': 'Windows'})
    _access_purge_old_v632740()
    ip = _request_ip_v632740()
    if _access_is_ip_blocked_v632740(ip):
        return jsonify({'registered': False, 'blocked': True, 'blocked_scope': 'ip', 'error': 'Access blocked by administrator.'}), 403
    device = _access_get_device_v632740()
    if device is None:
        return jsonify({'registered': False})
    if device.blocked:
        return jsonify({'registered': True, 'blocked': True, 'blocked_scope': 'device', 'nickname': device.nickname,
                        'error': 'This device has been blocked by administrator.'}), 403
    _access_touch_v632740(device, ip)
    return jsonify({'registered': True, 'blocked': False, 'nickname': device.nickname,
                    'device_id': device.device_id, 'browser': device.browser, 'os_name': device.os_name})


@app.route('/api/access/register', methods=['POST'])
def access_register_v632740():
    _access_purge_old_v632740()
    ip = _request_ip_v632740()
    if _access_is_ip_blocked_v632740(ip):
        return jsonify({'error': 'Access blocked by administrator.', 'blocked': True, 'blocked_scope': 'ip'}), 403
    existing = _access_get_device_v632740()
    if existing is not None:
        if existing.blocked:
            return jsonify({'error': 'This device has been blocked by administrator.', 'blocked': True, 'blocked_scope': 'device'}), 403
        _access_touch_v632740(existing, ip)
        # If this is an old registration that predates browser recovery, issue
        # one now so cookie + localStorage can protect the identity together.
        recovery_raw = None
        if _access_ensure_recovery_schema_v632770() and not _access_recovery_hash_for_device_v632770(existing.device_id):
            recovery_raw, recovery_hash = _access_new_recovery_token_v632765()
            try:
                if _access_set_recovery_hash_v632770(existing.device_id, recovery_hash):
                    db.session.commit()
                else:
                    db.session.rollback()
                    recovery_raw = None
            except Exception:
                db.session.rollback()
                recovery_raw = None
        return jsonify({'success': True, 'registered': True, 'nickname': existing.nickname,
                        'device_id': existing.device_id, 'recovery_token': recovery_raw})
    data = request.get_json(silent=True) or {}
    nickname = re.sub(r'\s+', ' ', str(data.get('nickname') or '').strip())
    if len(nickname) < 2 or len(nickname) > 50:
        return jsonify({'error': 'Please enter your real name (2–50 characters).'}), 400
    if any(ch in nickname for ch in '<>{}[]\\/'):
        return jsonify({'error': 'Name contains unsupported characters.'}), 400
    raw_token = secrets.token_urlsafe(32)
    token_hash = _access_hash_token_v632740(raw_token)
    recovery_raw, recovery_hash = _access_new_recovery_token_v632765()
    device_id = 'dev_' + secrets.token_hex(8)
